INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8e8202-f326-4d56-8427-6ce20a3cc684', '水殿拋毬曲二首 一', '水殿拋毬曲二首 一', 'e1122d6c-4b44-4c83-9842-5e572fe6b73c', '唐', '["侍宴黃昏曉未休，玉階夜色月如流。","朝來自覺承恩最，笑倩傍人認繡毬。"]', '["侍宴黄昏晓未休，玉階夜色月如流。","朝来自覺承恩最，笑倩傍人認繡毬。"]', '诗', 'shi', '', NULL, '水殿拋毬曲二首 一 李謹言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1674f002-ec41-4719-ba47-875daf4afdf8', '水殿拋毬曲二首 二', '水殿拋毬曲二首 二', 'e1122d6c-4b44-4c83-9842-5e572fe6b73c', '唐', '["堪恨隋家幾帝王，舞裀揉盡繡鴛鴦。","如今重到拋毬處，不是金鑪舊日香。"]', '["堪恨隋家幾帝王，舞裀揉尽繡鴛鴦。","如今重到拋毬处，不是金鑪旧日香。"]', '诗', 'shi', '', NULL, '水殿拋毬曲二首 二 李謹言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d10358-8e8d-4f3a-aa04-72242e7f6c4d', '銅雀妓', '銅雀妓', '472d1c82-2f0d-4050-90fe-0dd951aeefa6', '唐', '["秋色西陵滿綠蕪，繁弦急管強歡娛。","長舒羅袖不成舞，却向風前承淚珠。"]', '["秋色西陵满綠蕪，繁弦急管強歡娛。","长舒羅袖不成舞，却向风前承泪珠。"]', '诗', 'shi', '', NULL, '銅雀妓 吳燭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40804199-70c1-4391-8b58-2ff400bf2d7d', '戲示諸妓', '戲示諸妓', '52087753-9f99-4470-a983-dc18c4dae45a', '唐', '["綠羅裙上標三棒，紅粉腮邊淚兩行。","抄手向前咨大使，這回不敢惱兒郎。"]', '["綠羅裙上標三棒，紅粉腮邊泪兩行。","抄手向前咨大使，這回不敢惱兒郎。"]', '诗', 'shi', '', NULL, '戲示諸妓 張保嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d31107b-993b-4d35-b4b2-f570994b8690', '末秋到家', '末秋到家', '665fc6e8-250c-47a0-aaf7-dd96f6ee653c', '唐', '["歸來無所利，骨肉亦不喜。","黃犬却有情，當門臥搖尾。"]', '["归来無所利，骨肉亦不喜。","黄犬却有情，當门臥搖尾。"]', '诗', 'shi', '', NULL, '末秋到家 潘圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f6eca8-526e-4d8c-8d12-8c34f6ffe803', '送人往宣城', '送人往宣城', '9667ff28-6429-47d6-b852-379fa05d50d1', '唐', '["江畔送行人，千山生暮氛。","謝安團扇上，爲畫敬亭雲。"]', '["江畔送行人，千山生暮氛。","謝安團扇上，爲畫敬亭云。"]', '诗', 'shi', '', NULL, '送人往宣城 潘佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f138b05-2a7a-4904-bfce-fd2c558281e0', '洛陽河亭奉酬留守郡公追送', '洛陽河亭奉酬留守郡公追送', '9600536e-fc5f-4308-9cd4-bb8134d9f4ae', '唐', '["離亭餞落暉，臘酒減征衣。","歲晚煙霞重，川寒雲樹微。","戎裝千里至，舊路十年歸。","還似汀洲雁，相逢又背飛。"]', '["離亭餞落暉，臘酒減征衣。","歲晚煙霞重，川寒云樹微。","戎裝千里至，旧路十年归。","還似汀洲雁，相逢又背飞。"]', '诗', 'shi', '', NULL, '洛陽河亭奉酬留守郡公追送 李逸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a54ed041-c06e-4209-b179-7917fc94e1f2', '送道士曾昭瑩', '送道士曾昭瑩', 'd4e1d1f0-61ab-4bc4-8fd1-b9c08ef3369f', '唐', '["南北東西事，人間會也無。","昔曾棲玉笥，今也返玄都。","雪片隨天闊，泉聲落石孤。","丹霄人有約，去採石菖蒲。"]', '["南北东西事，人间會也無。","昔曾棲玉笥，今也返玄都。","雪片隨天闊，泉声落石孤。","丹霄人有約，去採石菖蒲。"]', '诗', 'shi', '', NULL, '送道士曾昭瑩 沈麟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7299df6-2342-4321-b836-2faebbda8eb5', '贈別徐侃', '贈別徐侃', 'bd65e602-ad55-4256-ba26-be38b31f9236', '唐', '["一自離鄉國，十年在咸秦。","泣盡卞和血，不逢一故人。","今日舊友別，羞此漂泊身。","離情吟詩處，麻衣掩淚頻。","淚別各分袂，且及來年春。"]', '["一自離乡国，十年在咸秦。","泣尽卞和血，不逢一故人。","今日旧友別，羞此漂泊身。","離情吟诗处，麻衣掩泪頻。","泪別各分袂，且及来年春。"]', '诗', 'shi', '', NULL, '贈別徐侃 安鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5978fe7b-d679-48bb-a306-16e01c80318a', '顧城', '顧城', '0e33dbf7-0866-473f-bb13-b8cb798df42a', '唐', '["世久荒墟在，白雲幾代耕。","市廛新草綠，里社故煙輕。","不謹罹天討，來蘇豈忿兵。","誰云殷鑒遠，今古在人程。"]', '["世久荒墟在，白云幾代耕。","市廛新草綠，里社故煙轻。","不謹罹天討，来蘇豈忿兵。","誰云殷鑒远，今古在人程。"]', '诗', 'shi', '', NULL, '顧城 李倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39979cce-c52f-4d12-b62d-bcea5d634811', '金錢花', '金錢花', 'a91de108-9462-4d3a-bce6-dd0c5393eb3f', '唐', '["輪廓休誇四字書，紅窠寫出對庭除。","時時買得佳人笑，本色金錢却不如。"]', '["輪廓休誇四字书，紅窠寫出对庭除。","时时買得佳人笑，本色金錢却不如。"]', '诗', 'shi', '', NULL, '金錢花 盧子發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6868df3-5680-4cab-a889-b7141187f995', '故白巖禪師院', '故白巖禪師院', 'e4e44865-afd7-491d-8694-352a414fd931', '唐', '["能師還世名還在，空閉禪堂滿院苔。","花樹不隨人寂寞，數株猶自出牆來。"]', '["能師還世名還在，空閉禪堂满院苔。","花樹不隨人寂寞，數株猶自出牆来。"]', '诗', 'shi', '', NULL, '故白巖禪師院 王夢周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ff687f-e183-4075-9376-872591fd7a31', '題九天使者廟', '題九天使者廟', 'c8fb9bc1-e2f9-42e5-90cd-cecb75cf1f4c', '唐', '["獨入玄宮禮至真，焚香不爲賤貧身。","秦淮兩岸沙埋骨，湓浦千家血染塵。","廬阜煙霞誰是主，虎溪風月屬何人。","九江太守勤王事，好放天兵渡要津。"]', '["独入玄宮禮至真，焚香不爲賤貧身。","秦淮兩岸沙埋骨，湓浦千家血染塵。","廬阜煙霞誰是主，虎溪风月屬何人。","九江太守勤王事，好放天兵渡要津。"]', '诗', 'shi', '', NULL, '題九天使者廟 孫咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aaf0c9b-fecf-4183-a50f-b12ce5a46b5f', '房公舊竹亭聞琴', '房公旧竹亭闻琴', '1aed1655-2510-403a-88d5-1e12b6b35ab2', '唐', '["石室寒飆警，孫枝雅器裁。","坐來山水操，弦斷弔塵埃。"]', '["石室寒飆警，孫枝雅器裁。","坐来山水操，弦斷弔塵埃。"]', '诗', 'shi', '', NULL, '房公舊竹亭聞琴 李澣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6152ec54-7878-43c5-817b-00f27f4a6598', '清溪館作', '清溪館作', 'e2be3871-c4f8-481f-b338-f26504c28ea4', '唐', '["指途清溪裏，左右唯深林。","雲蔽望鄉處，雨愁爲客心。","遇人多物役，聽鳥時幽音。","何必滄浪水，庶茲浣塵襟。"]', '["指途清溪裏，左右唯深林。","云蔽望乡处，雨愁爲客心。","遇人多物役，听鸟时幽音。","何必滄浪水，庶茲浣塵襟。"]', '诗', 'shi', '', NULL, '清溪館作 錢戭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe9f655-b81e-4af2-a281-f400670cc02c', '晚春宴', '晚春宴', 'c648195c-c205-4dc7-9e3f-343cda7a0ce3', '唐', '["日斜賓館晚，春輕麥候初。","簾暄巢幕燕，池躍戲蓮魚。","石聲隨流響，桐影傍巖疎。","誰能千里外，獨寄八行書。"]', '["日斜賓館晚，春轻麦候初。","簾暄巢幕燕，池躍戲蓮鱼。","石声隨流响，桐影傍巖疎。","誰能千里外，独寄八行书。"]', '诗', 'shi', '', NULL, '晚春宴 韋道遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd504159-7ef5-40f8-a723-947b7b40fb2d', '長沙六快詩', '长沙六快诗', '95fe3fae-b135-4983-a2be-21fe64abe007', '唐', '["湖外風物奇，長沙信難續。","衡峰排古青，湘水湛寒綠。","舟檝通大江，車輪會平陸。","昔賢官是邦，仁澤流豐沃。","今賢官是邦，刳啗人脂肉。","懷昔甘棠花，傷今猛虎毒。","然此一郡內，所樂人纔六。","漕與二憲僚，守連兩通屬。","高堂日暮會，深夜繼以燭。","幃幕皆綺紈，器皿盡金玉。","歌喉若珠纍，舞腰如素束。","千態與萬狀，六人歡不足。","因成快活詩，薦之堯舜目。"]', '["湖外风物奇，长沙信难續。","衡峰排古青，湘水湛寒綠。","舟檝通大江，车輪會平陸。","昔賢官是邦，仁澤流豐沃。","今賢官是邦，刳啗人脂肉。","懷昔甘棠花，傷今猛虎毒。","然此一郡內，所乐人纔六。","漕與二憲僚，守連兩通屬。","高堂日暮會，深夜繼以燭。","幃幕皆綺紈，器皿尽金玉。","歌喉若珠纍，舞腰如素束。","千態與万狀，六人歡不足。","因成快活诗，薦之堯舜目。"]', '诗', 'shi', '', NULL, '長沙六快詩 王揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f20d8a-8c7b-4a45-b3d1-fd60e1503be2', '廣州王園寺伏日即事寄北中親友', '廣州王园寺伏日即事寄北中親友', 'e16ae16a-05eb-43d6-8239-ec235ccd2ebb', '唐', '["南越逢初伏，東林度一朝。","曲池煎畏景，高閣絕微飆。","竹簟移先灑，蒲葵破復搖。","地偏毛瘴近，山毒火威饒。","裛汗絺如濯，親牀枕並燒。","墮枝傷翠羽，萎葉惜紅蕉。","且困流金熾，難成獨酌謠。","望霖窺潤礎，思吹候纖條。","旅恨生烏滸，鄉心繫浴橋。","誰憐在炎客，一夕壯容銷。"]', '["南越逢初伏，东林度一朝。","曲池煎畏景，高閣絕微飆。","竹簟移先灑，蒲葵破复搖。","地偏毛瘴近，山毒火威饒。","裛汗絺如濯，親牀枕並燒。","墮枝傷翠羽，萎葉惜紅蕉。","且困流金熾，难成独酌謠。","望霖窺潤礎，思吹候纖條。","旅恨生烏滸，乡心繫浴橋。","誰怜在炎客，一夕壯容銷。"]', '诗', 'shi', '', NULL, '廣州王園寺伏日即事寄北中親友 王言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8146e42-2d5a-4ccc-b11c-f5613ae37f60', '春日', '春日', 'cf5c0e6d-5469-4915-944d-90b780195cb9', '唐', '["輕花細葉滿林端，昨夜春風曉色寒。","黃鳥不堪愁裏聽，綠楊宜向雨中看。"]', '["轻花細葉满林端，昨夜春风晓色寒。","黄鸟不堪愁裏听，綠楊宜向雨中看。"]', '诗', 'shi', '', NULL, '春日 宋雍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df743a74-b342-4642-9bcb-3efccd54202d', '失題', '失題', 'cf5c0e6d-5469-4915-944d-90b780195cb9', '唐', '["斜雨飛絲織晚風，疎簾半捲野亭空。","荷花開盡秋光晚，零落殘紅綠沼中。"]', '["斜雨飞絲织晚风，疎簾半捲野亭空。","荷花开尽秋光晚，零落殘紅綠沼中。"]', '诗', 'shi', '', NULL, '失題 宋雍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2b0970-93d5-4f0c-bdeb-6cbd94f546f2', '古意', '古意', '99806116-2ab5-43b4-b42a-31ea7cf990a0', '唐', '["窮秋朔風起，滄海愁陰漲。","虜騎掠河南，漢兵屯灞上。","羽書驚沙漠，刁斗喧亭障。","關塞何蒼茫，遙烽遞相望。","弱齡負奇節，俠客多招訪。","投筆棄繻生，提戈逐飛將。","拔劒照霜白，怒髮衝冠壯。","會立萬里功，視君封侯相。"]', '["窮秋朔风起，滄海愁陰漲。","虜騎掠河南，漢兵屯灞上。","羽书驚沙漠，刁斗喧亭障。","关塞何蒼茫，遙烽遞相望。","弱齡負奇節，俠客多招訪。","投笔棄繻生，提戈逐飞將。","拔劒照霜白，怒髮衝冠壯。","會立万里功，視君封侯相。"]', '诗', 'shi', '', NULL, '古意 戴休珽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf41249-0d03-4746-a375-f3ba7ee82f60', '勗曹生', '勗曹生', 'c0042e6f-5b01-4af5-b890-884e630deb22', '唐', '["桑扈交飛百舌忙，祖亭聞樂倍思鄉。","尊前有恨慚卑宦，席上無憀愛豔妝。","莫爲狂花迷眼界，須求真理定心王。","遊蜂採掇何時已，祗恐多言議短長。"]', '["桑扈交飞百舌忙，祖亭闻乐倍思乡。","尊前有恨慚卑宦，席上無憀愛豔妝。","莫爲狂花迷眼界，須求真理定心王。","游蜂採掇何时已，祗恐多言議短长。"]', '诗', 'shi', '', NULL, '勗曹生 盧鉟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b07aeac-f930-4400-a3d7-7deabcaa3e7a', '琴歌', '琴歌', 'e39913a4-12b8-4213-8b2a-c08b16139353', '唐', '["綠琴製自桐孫枝，十年窗下無人知。","清聲不與衆樂雜，所以屈受塵埃欺。","七弦脆斷蟲絲朽，辨別不曾逢好手。","琴聲若似琵琶聲，賣與時人應已久。","玉徽冷落無光彩，堪恨鍾期不相待。","鳳囀吟幽鶴舞時，撚弄錚摐聲亦在。","向曾守貧貧不徹，賤價與人人不別。","前迴忍淚却收來，泣向秋風兩條血。","乃知凡俗難可名，輕者却重重者輕。","真龍不聖土龍聖，鳳皇啞舌鴟梟鳴。","何殊此琴哀怨苦，寂寞沈埋在幽戶。","萬重山水不肯聽，俗耳樂聞人打鼓。","知君立身待分義，驅喝風雷在平地。","一生從事不因人，健步窣雲皆自致。","不辭重拂弦上塵，市廛不買多讒人。","莫辭憔悴與買取，爲君一曲號青春。"]', '["綠琴製自桐孫枝，十年窗下無人知。","清声不與衆乐杂，所以屈受塵埃欺。","七弦脆斷蟲絲朽，辨別不曾逢好手。","琴声若似琵琶声，賣與时人應已久。","玉徽冷落無光彩，堪恨鍾期不相待。","鳳囀吟幽鹤舞时，撚弄錚摐声亦在。","向曾守貧貧不徹，賤價與人人不別。","前迴忍泪却收来，泣向秋风兩條血。","乃知凡俗难可名，轻者却重重者轻。","真龙不聖土龙聖，鳳皇啞舌鴟梟鳴。","何殊此琴哀怨苦，寂寞沈埋在幽戶。","万重山水不肯听，俗耳乐闻人打鼓。","知君立身待分義，驱喝风雷在平地。","一生從事不因人，健步窣云皆自致。","不辞重拂弦上塵，市廛不買多讒人。","莫辞憔悴與買取，爲君一曲號青春。"]', '诗', 'shi', '', NULL, '琴歌 趙摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7184e0-8b1d-4b69-907c-48183d821421', '廢長行', '廢长行', 'e39913a4-12b8-4213-8b2a-c08b16139353', '唐', '["紫牙鏤合方如斗，二十四星銜月口。","貴人迷此華筵中，運木手交如陣鬬。","不算勞神運枯木，且廢爲官恤惸獨。","門前有吏嚇孤窮，欲訴門深抱冤哭。","耳厭人催坐衙早，纔聞此戲身先到。","理人似愛長行心，天下安平多草草。","何當化局爲明鏡，挂在高堂辨邪正。","何當化子作筆鋒，常在手中行法令。","莫令終日迷如此，不治生民負天子。"]', '["紫牙鏤合方如斗，二十四星銜月口。","貴人迷此华筵中，運木手交如陣鬬。","不算勞神運枯木，且廢爲官恤惸独。","门前有吏嚇孤窮，欲訴门深抱冤哭。","耳厭人催坐衙早，纔闻此戲身先到。","理人似愛长行心，天下安平多草草。","何當化局爲明镜，挂在高堂辨邪正。","何當化子作笔鋒，常在手中行法令。","莫令終日迷如此，不治生民負天子。"]', '诗', 'shi', '', NULL, '廢長行 趙摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6601d0-9053-4397-a4bd-1e4a4b5b85ef', '玉女詞', '玉女词', 'c4b6b2b7-5f02-4459-a1d7-f6d7090aca4d', '唐', '["綺薦銀屏空積塵，柳眉桃臉暗銷春。","不須更學陽臺女，爲雨爲雲趁惱人。"]', '["綺薦銀屏空積塵，柳眉桃臉暗銷春。","不須更学陽台女，爲雨爲云趁惱人。"]', '诗', 'shi', '', NULL, '玉女詞 張安石 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4423fe-73f6-40aa-8ac7-3649bfafbeeb', '苦別', '苦別', 'c4b6b2b7-5f02-4459-a1d7-f6d7090aca4d', '唐', '["向前不信別離苦，而今自到別離處。","兩行粉淚紅闌干，一朵芙蕖帶殘露。"]', '["向前不信別離苦，而今自到別離处。","兩行粉泪紅闌干，一朵芙蕖带殘露。"]', '诗', 'shi', '', NULL, '苦別 張安石 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833d7c10-b5e7-45e4-a53e-80ab372f3f28', '石城', '石城', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["繫纜石城下，恣吟懷暫開。","江人橈艇子，將謂莫愁來。"]', '["繫纜石城下，恣吟懷暫开。","江人橈艇子，將謂莫愁来。"]', '诗', 'shi', '', NULL, '石城 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('380183a0-f8cb-4af7-b10e-1020bf3aff0d', '漢東道中', '漢东道中', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["九十九岡遙，天寒雪未消。","羸童牽瘦馬，不敢過危橋。"]', '["九十九岡遙，天寒雪未消。","羸童牽瘦马，不敢過危橋。"]', '诗', 'shi', '', NULL, '漢東道中 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291ee704-2de1-46da-8cb1-f10e0ce76806', '高溪有懷', '高溪有懷', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["駐馬高溪側，旅人千里情。","雁山山下水，還作此泉聲。"]', '["駐马高溪側，旅人千里情。","雁山山下水，還作此泉声。"]', '诗', 'shi', '', NULL, '高溪有懷 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('478f129b-206f-4716-9eff-57a13e2303fc', '寄進士賈希', '寄進士賈希', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["恨苦淚不落，耿然東北心。","空囊與瘦馬，羈紲意應深。"]', '["恨苦泪不落，耿然东北心。","空囊與瘦马，羈紲意應深。"]', '诗', 'shi', '', NULL, '寄進士賈希 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf76ba3-d84f-4d36-a605-43cb7d38ef8c', '出塞', '出塞', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["瘦馬羸童行背秦，暮鴉撩亂入殘雲。","北風吹起寒營角，直至榆關人盡聞。"]', '["瘦马羸童行背秦，暮鴉撩亂入殘云。","北风吹起寒營角，直至榆关人尽闻。"]', '诗', 'shi', '', NULL, '出塞 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b21949d-9d1a-40e7-9059-f929452d824f', '旅泊', '旅泊', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["霜月正高鸚鵡洲，美人清唱發紅樓。","鄉心暗逐秋江水，直到吳山脚下流。"]', '["霜月正高鸚鵡洲，美人清唱發紅楼。","乡心暗逐秋江水，直到吳山脚下流。"]', '诗', 'shi', '', NULL, '旅泊 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1adbbffb-98b2-40f5-bfcd-750aeb36e03b', '次青雲驛', '次青云驛', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["馬轉櫟林山鳥飛，商溪流水背殘暉。","行人幾在青雲路，底事風塵猶滿衣。"]', '["马轉櫟林山鸟飞，商溪流水背殘暉。","行人幾在青云路，底事风塵猶满衣。"]', '诗', 'shi', '', NULL, '次青雲驛 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd1f0b9-4bf3-4493-ac14-8dea55f51125', '大庾驛有懷', '大庾驛有懷', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["一囊書重百餘斤，郵吏寧知去計貧。","莫訝偏吟望鄉句，明朝便見嶺南人。"]', '["一囊书重百餘斤，郵吏寧知去計貧。","莫訝偏吟望乡句，明朝便见嶺南人。"]', '诗', 'shi', '', NULL, '大庾驛有懷 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1afcdfd1-60bb-4ac5-995a-c3aa2e9a4fb3', '題商山修路僧院', '題商山修路僧院', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["此地修行山幾枯，草堂生計只缾盂。","支郎既解除艱險，試看人心平得無。"]', '["此地修行山幾枯，草堂生計只缾盂。","支郎既解除艱險，試看人心平得無。"]', '诗', 'shi', '', NULL, '題商山修路僧院 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a889da-4afe-4e6e-9986-c306c4e1d1a2', '題長安僧院', '題长安僧院', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["出門爭走九衢塵，總是浮生不了身。","惟有水田衣下客，大家忙處作閑人。"]', '["出门爭走九衢塵，總是浮生不了身。","惟有水田衣下客，大家忙处作闲人。"]', '诗', 'shi', '', NULL, '題長安僧院 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b5e3ea-b813-4432-96d7-5b994d1f8b30', '次商於感舊寄盧中丞', '次商於感旧寄盧中丞', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["昔年簪組隘丘門，今日旌幢一院存。","何事商於淚如雨，小儒偏受陸家恩。"]', '["昔年簪組隘丘门，今日旌幢一院存。","何事商於泪如雨，小儒偏受陸家恩。"]', '诗', 'shi', '', NULL, '次商於感舊寄盧中丞 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa23bb2-fb7c-47dc-a33e-edc077ad85ac', '樵翁', '樵翁', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["獨入深山信脚行，慣當貙虎不曾驚。","路傍花發無心看，惟見枯枝刮眼明。"]', '["独入深山信脚行，慣當貙虎不曾驚。","路傍花發無心看，惟见枯枝刮眼明。"]', '诗', 'shi', '', NULL, '樵翁 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633bc9bc-aa49-408a-8ef6-c4e406aa8ee9', '四老廟', '四老廟', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["無端捨釣學干名，不得溪山養性情。","自省此身非達者，今朝羞拜四先生。"]', '["無端捨釣学干名，不得溪山養性情。","自省此身非達者，今朝羞拜四先生。"]', '诗', 'shi', '', NULL, '四老廟 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb549dc-31b0-42d9-8de3-be362e441c24', '昭君冢', '昭君冢', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["曾爲漢帝眼中人，今作狂胡陌上塵。","身死不知多少載，冢花猶帶洛陽春。"]', '["曾爲漢帝眼中人，今作狂胡陌上塵。","身死不知多少載，冢花猶带洛陽春。"]', '诗', 'shi', '', NULL, '昭君冢 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf1ba9e-bbd1-4a60-a8bd-76dbf1e22228', '聞歌竹枝', '闻歌竹枝', '6239bb3e-19fa-48a6-8475-e41f566afbea', '唐', '["巡隄聽唱竹枝詞，正是月高風靜時。","獨向東南人不會，弟兄俱在楚江湄。"]', '["巡隄听唱竹枝词，正是月高风静时。","独向东南人不會，弟兄俱在楚江湄。"]', '诗', 'shi', '', NULL, '聞歌竹枝 蔣吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc9aad69-b497-4a6f-a97f-a039c841b027', '重門曲', '重门曲', '4f3f957a-93e5-4157-8d50-4362fb4e6538', '唐', '["憔悴容華怯對春，寂寥宮殿鎖閑門。","此身却羨宮中樹，不失芳時雨露恩。"]', '["憔悴容华怯对春，寂寥宮殿鎖闲门。","此身却羨宮中樹，不失芳时雨露恩。"]', '诗', 'shi', '', NULL, '重門曲 周濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6a50b3-b02a-4b58-a98b-a6704de4e393', '山下水', '山下水', '4f3f957a-93e5-4157-8d50-4362fb4e6538', '唐', '["背雲衝石出深山，淺碧泠泠一帶寒。","不獨有聲流出此，會歸滄海助波瀾。"]', '["背云衝石出深山，淺碧泠泠一带寒。","不独有声流出此，會归滄海助波瀾。"]', '诗', 'shi', '', NULL, '山下水 周濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7b5d31-6e9c-4e59-b2da-c14e61c27fb0', '逢鄰女', '逢鄰女', '4f3f957a-93e5-4157-8d50-4362fb4e6538', '唐', '["日高鄰女笑相逢，慢束羅裙半露胸。","莫向秋池照綠水，參差羞殺白芙蓉。"]', '["日高鄰女笑相逢，慢束羅裙半露胸。","莫向秋池照綠水，參差羞殺白芙蓉。"]', '诗', 'shi', '', NULL, '逢鄰女 周濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c1f609-4fa5-4b40-a981-9bf5a28fda04', '廢宅', '廢宅', '4f3f957a-93e5-4157-8d50-4362fb4e6538', '唐', '["牢落畫堂空鎖塵，荒涼庭樹暗消春。","豪家莫笑此中事，曾見此中人笑人。"]', '["牢落畫堂空鎖塵，荒涼庭樹暗消春。","豪家莫笑此中事，曾见此中人笑人。"]', '诗', 'shi', '', NULL, '廢宅 周濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e852d14-b9f0-4927-aabf-fbdfd5fe927c', '奉和登會昌山應制', '奉和登會昌山應制', 'a6affc34-444e-4ac0-b043-4a29d4684b82', '唐', '["睿想入希夷，真游到具茨。","玉鸞登嶂遠，雲輅出花遲。","泉壑凝神處，陽和布澤時。","六龍多順動，四海正雍熙。"]', '["睿想入希夷，真游到具茨。","玉鸾登嶂远，云輅出花遲。","泉壑凝神处，陽和布澤时。","六龙多順动，四海正雍熙。"]', '诗', 'shi', '', NULL, '奉和登會昌山應制 趙起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8bc15ae-fde4-4f10-be54-1e5bb51fcf48', '冬日與羣公泛舟焦山 一', '冬日與羣公泛舟焦山 一', '8a71fdb1-a475-4d9f-a6ee-fe4707ac53a4', '唐', '["江外水不凍，今年寒復遲。","衆芳且未歇，近臘仍裌衣。","載酒適我情，興來趣漸微。","方舟大川上，環酌對落暉。","兩片青石稜，波際無因依。","三山安可到，欲到風引歸。","滄溟壯觀多，心目豁暫時。","況得窮日夕，乘槎何所之。"]', '["江外水不凍，今年寒复遲。","衆芳且未歇，近臘仍裌衣。","載酒適我情，兴来趣漸微。","方舟大川上，环酌对落暉。","兩片青石稜，波際無因依。","三山安可到，欲到风引归。","滄溟壯观多，心目豁暫时。","況得窮日夕，乘槎何所之。"]', '诗', 'shi', '', NULL, '冬日與羣公泛舟焦山 一 王瓚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f91c2a3-fa44-439f-85fe-efbfc11f1ecb', '冬日與羣公泛舟焦山 二', '冬日與羣公泛舟焦山 二', '8a71fdb1-a475-4d9f-a6ee-fe4707ac53a4', '唐', '["縱步不知遠，夕陽猶未回。","好花隨處發，流水趂人來。"]', '["縱步不知远，夕陽猶未回。","好花隨处發，流水趂人来。"]', '诗', 'shi', '', NULL, '冬日與羣公泛舟焦山 二 王瓚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e01c32e-bf5c-4021-9199-6ed20c0067ba', '度揭鴻嶺', '度揭鴻嶺', 'bfd5aea5-17f1-4e31-ae82-619286c987ef', '唐', '["閩越曾爲塞，將軍舊置營。","我歌空感慨，西北望神京。"]', '["閩越曾爲塞，將軍旧置營。","我歌空感慨，西北望神京。"]', '诗', 'shi', '', NULL, '度揭鴻嶺 慕容韋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('050b4047-5141-4db7-b833-b248311b3835', '湘江', '湘江', '299d8e94-4100-4e59-a024-c17d645dd844', '唐', '["瀟湘江頭三月春，柳條弄日搖黃金。","鷓鴣一聲在何許，黃陵廟前煙靄深。","丹青欲畫無好手，穩提玉勒沈吟久。","馬蹄不爲行客留，心挂長林屢回首。"]', '["瀟湘江头三月春，柳條弄日搖黄金。","鷓鴣一声在何許，黄陵廟前煙靄深。","丹青欲畫無好手，穩提玉勒沈吟久。","马蹄不爲行客留，心挂长林屢回首。"]', '诗', 'shi', '', NULL, '湘江 黃文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98865db-762f-4349-a0d6-e5ca98f89a3f', '題龍陽縣青草湖', '題龙陽縣青草湖', '71fdda8d-51fd-4819-9938-8a4dbb9b6d3d', '唐', '["西風吹老洞庭波，一夜湘君白髮多。","醉後不知天在水，滿船清夢壓星河。"]', '["西风吹老洞庭波，一夜湘君白髮多。","醉後不知天在水，满船清梦壓星河。"]', '诗', 'shi', '', NULL, '題龍陽縣青草湖 唐溫如 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e715ed-9d82-4a58-ade6-b788aba2abcb', '訾家洲', '訾家洲', 'e6c62fe3-c393-4168-a27f-486eb94be012', '唐', '["舊業分明桂水頭，人歸業盡水東流。","春風日暮江頭立，不及漁人有釣舟。"]', '["旧業分明桂水头，人归業尽水东流。","春风日暮江头立，不及漁人有釣舟。"]', '诗', 'shi', '', NULL, '訾家洲 歐陽賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e139d0b-02e2-4f95-bb55-bfcadc917690', '題吉州龍溪', '題吉州龙溪', 'b207dff5-c304-4724-a174-2bfa95682df4', '唐', '["龍溪之山秀而峙，龍溪之水清無底。","狂風激烈翻春濤，薄霧冥濛溢清泚。","奔流百折銀河通，落花滾滾浮霞紅。","四時佳境不可窮，彷彿直與桃源通。"]', '["龙溪之山秀而峙，龙溪之水清無底。","狂风激烈翻春濤，薄霧冥濛溢清泚。","奔流百折銀河通，落花滾滾浮霞紅。","四时佳境不可窮，彷彿直與桃源通。"]', '诗', 'shi', '', NULL, '題吉州龍溪 何敬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c7e05b-0eee-4e44-badf-ac6d2ee11f0f', '過睦州青溪渡', '過睦州青溪渡', 'c613406a-8131-409d-844a-ccdf8557ef82', '唐', '["天闊銜江雨，冥冥上客衣。","潭清魚可數，沙晚鴈爭飛。","川谷留雲氣，鵜鶘傍釣磯。","瓢零江海客，欹側一帆歸。"]', '["天闊銜江雨，冥冥上客衣。","潭清鱼可數，沙晚鴈爭飞。","川谷留云氣，鵜鶘傍釣磯。","瓢零江海客，欹側一帆归。"]', '诗', 'shi', '', NULL, '過睦州青溪渡 楊彝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f8b1da-1e9b-4284-b46f-17c85d56c973', '闔閭城懷古', '闔閭城懷古', '672dc210-42c8-438e-a7ee-88572d741133', '唐', '["五湖春水接遙天，國破君亡不記年。","惟有妖娥曾舞處，古臺寂寞起愁煙。"]', '["五湖春水接遙天，国破君亡不記年。","惟有妖娥曾舞处，古台寂寞起愁煙。"]', '诗', 'shi', '', NULL, '闔閭城懷古 裴瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d99e05a-4f8b-43a5-bb47-2616466e0f7a', '葦谷', '葦谷', 'df114a07-ad7d-4c7f-a0c9-365a0ce26524', '唐', '["水會三川漾碧波，雕陰人唱採花歌。","舊時白翟今荒壤，葦谷淒淒風雨多。"]', '["水會三川漾碧波，雕陰人唱採花歌。","旧时白翟今荒壤，葦谷淒淒风雨多。"]', '诗', 'shi', '', NULL, '葦谷 鄭玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dead6b4-9462-4e8c-9e70-cd1801b9eab8', '登岳陽樓', '登岳陽楼', '0aa09c1d-1be1-41fd-a829-36ad5fa57b90', '唐', '["湖邊景物屬秋天，樓上風光似去年。","仙侶緱生留福地，湘娥帝子寄哀弦。","雲門自統軒臺外，木葉偏飛楚客前。","極目江山何處是，一帆萬里信歸船。"]', '["湖邊景物屬秋天，楼上风光似去年。","仙侶緱生留福地，湘娥帝子寄哀弦。","云门自統軒台外，木葉偏飞楚客前。","極目江山何处是，一帆万里信归船。"]', '诗', 'shi', '', NULL, '登岳陽樓 麻溫其 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1a26d1-67b6-4517-aec7-c230ccbd1ffa', '經望湖驛', '經望湖驛', 'e75279e5-aeda-4159-8b22-ab28a2772159', '唐', '["大漠無屯雲，孤峰出亂柳。","前驅白登道，顧失飛狐口。","遙憶代王城，俯臨恆山後。","纍纍多古墓，寂寞爲墟久。","豈不固金湯，終聞擊銅斗。","交懽初仗信，接讌翻貽咎。","埋寶賊夫人，磨笄傷彼婦。","功成行且薄，義立名不朽。","莫慎纖微端，其何社稷守。","身歿國遂亡，此立人君醜。"]', '["大漠無屯云，孤峰出亂柳。","前驱白登道，顧失飞狐口。","遙憶代王城，俯臨恆山後。","纍纍多古墓，寂寞爲墟久。","豈不固金湯，終闻擊銅斗。","交懽初仗信，接讌翻貽咎。","埋寶賊夫人，磨笄傷彼婦。","功成行且薄，義立名不朽。","莫慎纖微端，其何社稷守。","身歿国遂亡，此立人君醜。"]', '诗', 'shi', '', NULL, '經望湖驛 韋鎰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fab37a8-b460-4592-acf6-bc0eefd81cc9', '杪秋洞庭懷王道士', '杪秋洞庭懷王道士', '61117a0a-5c31-48f1-8eaa-8c7bfe89e1bc', '唐', '["漂泊日復日，洞庭今更秋。","青桃亦何意，此夜催人愁。","惆悵客中月，裴回江上樓。","心知楚天遠，目送滄波流。","謝客久已滅，微言無處求。","空餘白雲在，客興隨孤舟。","千里杳難盡，一身常獨游。","故園復何許，江漢徒遲留。"]', '["漂泊日复日，洞庭今更秋。","青桃亦何意，此夜催人愁。","惆悵客中月，裴回江上楼。","心知楚天远，目送滄波流。","謝客久已滅，微言無处求。","空餘白云在，客兴隨孤舟。","千里杳难尽，一身常独游。","故园复何許，江漢徒遲留。"]', '诗', 'shi', '', NULL, '杪秋洞庭懷王道士 謝太虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e35a9f8-f951-4d7c-8f99-b967ce7a2df4', '君山祠', '君山祠', 'ebeed188-e273-4862-80f1-aae0204145fb', '唐', '["萬頃湖波浸碧天，旌封香火幾千年。","風濤澎湃魚龍舞，棟宇崢嶸燕雀遷。","遠岫光中濃淡樹，斜陽影裏往來船。","江河願借吹噓便，應有神功在目前。"]', '["万頃湖波浸碧天，旌封香火幾千年。","风濤澎湃鱼龙舞，棟宇崢嶸燕雀遷。","远岫光中濃淡樹，斜陽影裏往来船。","江河願借吹噓便，應有神功在目前。"]', '诗', 'shi', '', NULL, '君山祠 周岳秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('332bfe21-dd40-4029-8434-51ea87f16771', '新樂府', '新乐府', '591ee30a-a2a6-4d30-a5d1-6a17be2fd338', '唐', '["溫谷春生至，宸遊近甸榮。","雲隨天上轉，風入御筵輕。","翠蓋浮佳氣，朱樓依太清。","朝臣冠劒退，宮女管弦迎。"]', '["溫谷春生至，宸游近甸榮。","云隨天上轉，风入御筵轻。","翠蓋浮佳氣，朱楼依太清。","朝臣冠劒退，宮女管弦迎。"]', '诗', 'shi', '', NULL, '新樂府 馬逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38acf987-857b-457e-8324-a538baf0473c', '部落曲', '部落曲', '591ee30a-a2a6-4d30-a5d1-6a17be2fd338', '唐', '["蕃軍傍塞遊，代馬噴風秋。","老將垂金甲，閼支著錦裘。","琱戈蒙豹尾，紅斾插狼頭。","日暮天山下，鳴笳漢使愁。"]', '["蕃軍傍塞游，代马噴风秋。","老將垂金甲，閼支著錦裘。","琱戈蒙豹尾，紅斾插狼头。","日暮天山下，鳴笳漢使愁。"]', '诗', 'shi', '', NULL, '部落曲 馬逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d552771-d4db-41a9-9314-98c83f89bde9', '從軍', '從軍', '591ee30a-a2a6-4d30-a5d1-6a17be2fd338', '唐', '["漢馬千蹄合一羣，單于鼓角隔山聞。","沙塠風起紅樓下，飛上胡天作陣雲。"]', '["漢马千蹄合一羣，單于鼓角隔山闻。","沙塠风起紅楼下，飞上胡天作陣云。"]', '诗', 'shi', '', NULL, '從軍 馬逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216b73fe-f9f6-444b-a570-f7f37f0421e2', '宮詞二首 一', '宮词二首 一', '591ee30a-a2a6-4d30-a5d1-6a17be2fd338', '唐', '["金吾持戟護軒簷，天樂傳教萬姓瞻。","樓上美人相倚看，紅妝透出水晶簾。"]', '["金吾持戟護軒簷，天乐傳教万姓瞻。","楼上美人相倚看，紅妝透出水晶簾。"]', '诗', 'shi', '', NULL, '宮詞二首 一 馬逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c2b3f90-f45a-40f8-a872-d5e8c1d962ae', '宮詞二首 二', '宮词二首 二', '591ee30a-a2a6-4d30-a5d1-6a17be2fd338', '唐', '["玉樓天半起笙歌，風送宮人笑語和。","月影殿開聞曉漏，水晶簾捲近秋河。"]', '["玉楼天半起笙歌，风送宮人笑語和。","月影殿开闻晓漏，水晶簾捲近秋河。"]', '诗', 'shi', '', NULL, '宮詞二首 二 馬逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4fd288-3692-4d5a-bbc6-e9ed86584c1b', '長門失寵', '长门失寵', '30172928-7686-4eac-b961-1ddbc2c36c46', '唐', '["自從別鑾殿，長門幾度春。","不知金屋裏，更貯若爲人。"]', '["自從別鑾殿，长门幾度春。","不知金屋裏，更貯若爲人。"]', '诗', 'shi', '', NULL, '長門失寵 蕭意 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f89e3741-8dc3-413e-94e5-bbee754eb43a', '下山逢故夫', '下山逢故夫', '51c33d0d-ef1e-4af7-b75b-da8372e729e4', '唐', '["踟躕下山婦，共申別離久。","爲問織縑人，何必長相守。"]', '["踟躕下山婦，共申別離久。","爲问织縑人，何必长相守。"]', '诗', 'shi', '', NULL, '下山逢故夫 徐之才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7950d906-83ad-4868-83dd-f043f4545fc3', '虜患', '虜患', 'f6e0fda7-1b25-4c18-b0b1-c8ad476c6517', '唐', '["今日漢家探使迴，蟻疊胡兵來未歇。","春風渭水不敢流，總作六軍心上血。"]', '["今日漢家探使迴，蟻叠胡兵来未歇。","春风渭水不敢流，總作六軍心上血。"]', '诗', 'shi', '', NULL, '虜患 張陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2401de54-8072-4143-89a6-c42b91acc0f7', '夏日閨怨', '夏日閨怨', '02584868-a7cc-4cc3-b62c-715e5591650e', '唐', '["桃徑李蹊絕芳園，炎氛熾日滿愁軒。","枝上鳥驚朱槿落，池中魚戲綠蘋翻。","君戀京師久留滯，妾怨高樓積年歲。","非關曾入楚王宮，直爲相思腰轉細。","臥簟乘閑乍逐涼，熏爐畏熱嬾焚香。","雨霑柳葉如啼眼，露滴蓮花似汗妝。","全由獨自羞看影，豔是孤眠疑夜永。","無情拂鏡不成妝，有時却扇還風靜。","近日書來道欲歸，鴛鴦文錦字息機。","但恐愁容不相識，爲教恆著別時衣。"]', '["桃徑李蹊絕芳园，炎氛熾日满愁軒。","枝上鸟驚朱槿落，池中鱼戲綠蘋翻。","君戀京師久留滯，妾怨高楼積年歲。","非关曾入楚王宮，直爲相思腰轉細。","臥簟乘闲乍逐涼，熏爐畏熱嬾焚香。","雨霑柳葉如啼眼，露滴蓮花似汗妝。","全由独自羞看影，豔是孤眠疑夜永。","無情拂镜不成妝，有时却扇還风静。","近日书来道欲归，鴛鴦文錦字息機。","但恐愁容不相識，爲教恆著別时衣。"]', '诗', 'shi', '', NULL, '夏日閨怨 蔡瓌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('122b367c-2425-4692-a76d-d59def95cec8', '詠破扇', '詠破扇', '55229db8-24c4-4dcf-b1e4-15cdbc051a9d', '唐', '["輪如明月盡，羅似薄雲穿。","無由重掩笑，分在秋風前。"]', '["輪如明月尽，羅似薄云穿。","無由重掩笑，分在秋风前。"]', '诗', 'shi', '', NULL, '詠破扇 唐怡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f0bc11b-7cd5-4952-b53e-237efceffed9', '述懷', '述懷', '55229db8-24c4-4dcf-b1e4-15cdbc051a9d', '唐', '["萬事皆零落，平生不可思。","惟餘酒中趣，不減少年時。"]', '["万事皆零落，平生不可思。","惟餘酒中趣，不減少年时。"]', '诗', 'shi', '', NULL, '述懷 唐怡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb18d0d-45f9-4cab-b16b-e132be9286c9', '詠燭寄人', '詠燭寄人', '8e819613-c963-40e7-8e32-28be28412d8c', '唐', '["燭與人相似，通宵遽白煎。","不應須下淚，祗是爲人然。"]', '["燭與人相似，通宵遽白煎。","不應須下泪，祗是爲人然。"]', '诗', 'shi', '', NULL, '詠燭寄人 潘求仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f743f30-6678-4ce6-82de-3c7d5a445313', '薛王花燭行', '薛王花燭行', 'f34777eb-a26b-4676-b9d8-21cfaf6b4bd5', '唐', '["王子仙車下鳳臺，紫纓金勒馭龍媒。","□□□□□□出，環佩鏘鏘天上來。","鳷鵲樓前雲半捲，鴛鴦殿上月裴回。","玉盤錯落銀燈照，珠帳𤫩瓏寶扇開。","盈盈二八誰家子，紅粉新妝勝桃李。","從來六行比齊姜，自許千門奉楚王。","楚王宮裏能服飾，顧盼傾城復傾國。","合歡錦帶蒲萄花，連理香裙石榴色。","金爐半夜起氛氳，翡翠被重蘇合熏。","不學曹王遇神女，莫言羅敷邀使君。","同心婉娩若琴瑟，更笑天河有靈匹。","一朝福履盛王門，百代光輝增帝室。","富貴榮華實可憐，路傍觀者謂神仙。","祗應早得淮南術，會見雙飛入紫煙。"]', '["王子仙车下鳳台，紫纓金勒馭龙媒。","□□□□□□出，环佩鏘鏘天上来。","鳷鵲楼前云半捲，鴛鴦殿上月裴回。","玉盤錯落銀灯照，珠帳𤫩瓏寶扇开。","盈盈二八誰家子，紅粉新妝勝桃李。","從来六行比齊姜，自許千门奉楚王。","楚王宮裏能服飾，顧盼傾城复傾国。","合歡錦带蒲萄花，連理香裙石榴色。","金爐半夜起氛氳，翡翠被重蘇合熏。","不学曹王遇神女，莫言羅敷邀使君。","同心婉娩若琴瑟，更笑天河有靈匹。","一朝福履盛王门，百代光輝增帝室。","富貴榮华實可怜，路傍观者謂神仙。","祗應早得淮南術，會见雙飞入紫煙。"]', '诗', 'shi', '', NULL, '薛王花燭行 閻德隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751b7f22-75a0-4c36-88a5-4fa0f0d189a0', '三月歌', '三月歌', 'f34777eb-a26b-4676-b9d8-21cfaf6b4bd5', '唐', '["洛陽城路九春衢，洛陽城外柳千株。","能得來時作眼覓，天津橋側錦屠蘇。"]', '["洛陽城路九春衢，洛陽城外柳千株。","能得来时作眼覓，天津橋側錦屠蘇。"]', '诗', 'shi', '', NULL, '三月歌 閻德隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00a5c52-f109-4e69-8ef7-edbfc736c799', '妾薄命', '妾薄命', '4430e30b-a89c-448d-abc5-24803c3221d9', '唐', '["自從離別守空閨，遙聞征戰赴雲梯。","夜夜思君遼海北，年年棄妾渭橋西。","陽春白日照空暖，紫燕銜花向庭滿。","彩鸞琴裏怨聲多，飛鵲鏡前妝梳斷。","誰家夫壻不從征，應是漁陽別有情。","莫道紅顏燕地少，家家還似洛陽城。","旦逐新人殊未歸，還令秋至夜霜飛。","北斗星前橫旅鴈，南樓月下擣寒衣。","夜深聞鴈腸欲絕，獨坐縫衣燈又滅。","暗啼羅帳空自憐，夢度陽關向誰說。","每憐容貌宛如神，如何薄命不如人。","待君朝夕燕山至，好作明年楊柳春。"]', '["自從離別守空閨，遙闻征戰赴云梯。","夜夜思君遼海北，年年棄妾渭橋西。","陽春白日照空暖，紫燕銜花向庭满。","彩鸾琴裏怨声多，飞鵲镜前妝梳斷。","誰家夫壻不從征，應是漁陽別有情。","莫道紅顏燕地少，家家還似洛陽城。","旦逐新人殊未归，還令秋至夜霜飞。","北斗星前橫旅鴈，南楼月下擣寒衣。","夜深闻鴈腸欲絕，独坐縫衣灯又滅。","暗啼羅帳空自怜，梦度陽关向誰说。","每怜容貌宛如神，如何薄命不如人。","待君朝夕燕山至，好作明年楊柳春。"]', '诗', 'shi', '', NULL, '妾薄命 劉元叔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8923c73c-a3e2-46d5-88f2-b1cf9a631b74', '古別離', '古別離', '5b86c69d-c7a8-4466-ad20-8a0da4247ada', '唐', '["君御狐白裘，妾居緗綺幬。","粟鈿金夾膝，花錯玉搔頭。","離別生庭草，征衣斷戍樓。","蠨蛸網清曙，菡萏落紅秋。","小膽空房怯，長眉滿鏡愁。","爲傳兒女意，不用遠封侯。"]', '["君御狐白裘，妾居緗綺幬。","粟鈿金夾膝，花錯玉搔头。","離別生庭草，征衣斷戍楼。","蠨蛸網清曙，菡萏落紅秋。","小膽空房怯，长眉满镜愁。","爲傳兒女意，不用远封侯。"]', '诗', 'shi', '', NULL, '古別離 常理 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837d7051-f496-434f-b606-59bef749f048', '妾薄命', '妾薄命', '5b86c69d-c7a8-4466-ad20-8a0da4247ada', '唐', '["十五玉童色，雙蛾青彎彎。","鳥銜櫻桃花，此時刺繡閑。","嬌小恣所愛，誤人金指環。","豔花句引落，滅燭屏風關。","妾怕愁中畫，君偷薄裏還。","初謂來心平若案，誰知別意險如山。","乍啼羅袖嬌遮面，不忍看君莫惜顏。"]', '["十五玉童色，雙蛾青彎彎。","鸟銜櫻桃花，此时刺繡闲。","嬌小恣所愛，誤人金指环。","豔花句引落，滅燭屏风关。","妾怕愁中畫，君偷薄裏還。","初謂来心平若案，誰知別意險如山。","乍啼羅袖嬌遮面，不忍看君莫惜顏。"]', '诗', 'shi', '', NULL, '妾薄命 常理 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e91c2a3-f175-4e34-a97f-7aef63499698', '虞姬怨', '虞姬怨', 'dc21ce50-6923-4ae8-8c14-d25fc25a8147', '唐', '["妾本江南采蓮女，君是江東學劒人。","逢君游俠英雄日，值妾年華桃李春。","年華灼灼豔桃李，結髮簪花配君子。","行逢楚漢正相持，辭家上馬從君起。","歲歲年年事征戰，侍君帷幕損紅顏。","不惜羅衣沾馬汗，不辭紅粉著刀環。","相期相許定關中，鳴鑾鳴佩入秦宮。","誰誤四面楚歌起，果知五星漢道雄。","天時人事有興滅，智窮計屈心摧折。","澤中馬力先戰疲，帳下蛾眉□□□。","君王是日無神彩，賤妾此時容貌改。","拔山意氣都已無，渡江面目今何在。","終天隔地與君辭，恨似流波無息時。","使妾本來不相識，豈見中途懷苦悲。"]', '["妾本江南采蓮女，君是江东学劒人。","逢君游俠英雄日，值妾年华桃李春。","年华灼灼豔桃李，結髮簪花配君子。","行逢楚漢正相持，辞家上马從君起。","歲歲年年事征戰，侍君帷幕損紅顏。","不惜羅衣沾马汗，不辞紅粉著刀环。","相期相許定关中，鳴鑾鳴佩入秦宮。","誰誤四面楚歌起，果知五星漢道雄。","天时人事有兴滅，智窮計屈心摧折。","澤中马力先戰疲，帳下蛾眉□□□。","君王是日無神彩，賤妾此时容貌改。","拔山意氣都已無，渡江面目今何在。","終天隔地與君辞，恨似流波無息时。","使妾本来不相識，豈见中途懷苦悲。"]', '诗', 'shi', '', NULL, '虞姬怨 馮待徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c1c2d5-918c-49a6-993d-64d823d54761', '越谿怨', '越谿怨', 'f4497d9e-4b4c-4a0d-ac38-21659ed2215c', '唐', '["越王宮裏如花人，越水谿頭采白蘋。","白蘋未盡人先盡，誰見江南春復春。"]', '["越王宮裏如花人，越水谿头采白蘋。","白蘋未尽人先尽，誰见江南春复春。"]', '诗', 'shi', '', NULL, '越谿怨 冷朝光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a99f66-7b2b-4b4f-9261-f8adaaace3ef', '吳宮怨', '吳宮怨', '9b917faa-efa6-4148-be3f-e573a6a642d8', '唐', '["君不見吳王宮閣臨江起，不見珠簾見江水。","曉氣晴來雙闕間，潮聲夜落千門裏。","句踐城中非舊春，姑蘇臺下起黃塵。","祗今唯有西江月，曾照吳王宮裏人。"]', '["君不见吳王宮閣臨江起，不见珠簾见江水。","晓氣晴来雙闕间，潮声夜落千门裏。","句踐城中非旧春，姑蘇台下起黄塵。","祗今唯有西江月，曾照吳王宮裏人。"]', '诗', 'shi', '', NULL, '吳宮怨 衛萬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f83fac16-7b3e-4cfb-8744-0b76bc5a023f', '春游吟', '春游吟', '9dfc9c4c-4b74-46c0-a765-a0d0389c992a', '唐', '["初春徧芳甸，十里藹盈矚。","美人摘新英，步步翫春綠。","所思杳何處，宛在吳江曲。","可憐不得共芳菲，日暮歸來淚滿衣。"]', '["初春徧芳甸，十里藹盈矚。","美人摘新英，步步翫春綠。","所思杳何处，宛在吳江曲。","可怜不得共芳菲，日暮归来泪满衣。"]', '诗', 'shi', '', NULL, '春游吟 李章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7ec794-d196-4f0d-b07f-efaf5b13e97e', '婕妤怨', '婕妤怨', '6d5797d5-d9c8-4985-82de-f4779089067b', '唐', '["長信梨花暗欲棲，應門上鑰草萋萋。","春風吹花亂撲戶，[班]絕車聲不至啼。"]', '["长信梨花暗欲棲，應门上鑰草萋萋。","春风吹花亂撲戶，[班]絕车声不至啼。"]', '诗', 'shi', '', NULL, '婕妤怨 王沈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915851e4-c9a8-4631-9179-8ccaac52ff41', '夜夜曲', '夜夜曲', 'ed7684c5-7336-496c-b177-980a1337b513', '唐', '["北斗星移銀漢低，班姬愁思鳳城西。","青槐陌上行人絕，明月樓前烏夜啼。"]', '["北斗星移銀漢低，班姬愁思鳳城西。","青槐陌上行人絕，明月楼前烏夜啼。"]', '诗', 'shi', '', NULL, '夜夜曲 王偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f0639b-6b8d-4878-86fe-d900ee87fe42', '明君詞', '明君词', 'ed7684c5-7336-496c-b177-980a1337b513', '唐', '["北望單于日半斜，明君馬上泣胡沙。","一雙淚滴黃河水，應得東流入漢家。"]', '["北望單于日半斜，明君马上泣胡沙。","一雙泪滴黄河水，應得东流入漢家。"]', '诗', 'shi', '', NULL, '明君詞 王偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991e24b9-eaf2-466d-91af-dff38b9283cd', '擬古東飛伯勞歌', '擬古东飞伯勞歌', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["秦王龍劒燕后琴，珊瑚寶匣鏤雙心。","誰家女兒抱香枕，開衾滅燭願侍寢。","瓊窗半上金鏤幬，輕羅掩面不遮羞。","青綺幃中坐相憶，紅鸞鏡裏見愁色。","簷花照月鶯對棲，空將可憐暗中啼。"]', '["秦王龙劒燕后琴，珊瑚寶匣鏤雙心。","誰家女兒抱香枕，开衾滅燭願侍寢。","瓊窗半上金鏤幬，轻羅掩面不遮羞。","青綺幃中坐相憶，紅鸾镜裏见愁色。","簷花照月鶯对棲，空將可怜暗中啼。"]', '诗', 'shi', '', NULL, '擬古東飛伯勞歌 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7debe622-91bb-4f76-acfa-7652ced1ec2d', '怨詩三首 一', '怨诗三首 一', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["羅敷初總髻，蕙芳正嬌小。","月落始歸船，春眠恆著曉。"]', '["羅敷初總髻，蕙芳正嬌小。","月落始归船，春眠恆著晓。"]', '诗', 'shi', '', NULL, '怨詩三首 一 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f0d6a0-e797-44cd-a1a6-eb7b728e4722', '怨詩三首 二', '怨诗三首 二', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["何處期郎遊，小苑花臺間。","相憶不可見，且復乘月還。"]', '["何处期郎游，小苑花台间。","相憶不可见，且复乘月還。"]', '诗', 'shi', '', NULL, '怨詩三首 二 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be94263-6da2-4941-957f-916e7aa92383', '怨詩三首 三', '怨诗三首 三', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["別前花照路，別後露垂葉。","歌舞須及時，如何坐悲妾。"]', '["別前花照路，別後露垂葉。","歌舞須及时，如何坐悲妾。"]', '诗', 'shi', '', NULL, '怨詩三首 三 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942432cd-6095-423f-8923-fbb37c74e265', '碧玉歌', '碧玉歌', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["碧玉上官妓，出入千花林。","珠被玳瑁牀，感郎情意深。"]', '["碧玉上官妓，出入千花林。","珠被玳瑁牀，感郎情意深。"]', '诗', 'shi', '', NULL, '碧玉歌 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f23f7a83-bdb1-4f30-a69b-1ba8f97fa81b', '見美人聞琴不聽', '见美人闻琴不听', '13f7b2aa-1470-42f9-9ca6-fac4b26349ef', '唐', '["洛浦風流雪，陽臺朝暮雲。","聞琴不肯聽，似妒卓文君。"]', '["洛浦风流雪，陽台朝暮云。","闻琴不肯听，似妒卓文君。"]', '诗', 'shi', '', NULL, '見美人聞琴不聽 李播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc69461b-eb7c-4a52-9050-e5aaa2bba17a', '賦詩', '賦诗', '02b38e68-c8f5-4f17-b317-f93e0a9ace55', '唐', '["君爲河邊草，逢春心剩生。","妾如臺上鏡，得照始分明。"]', '["君爲河邊草，逢春心剩生。","妾如台上镜，得照始分明。"]', '诗', 'shi', '', NULL, '賦詩 辛弘智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03365949-e73b-49e1-b5c1-3de14cc2eaa9', '自君之出矣', '自君之出矣', '02b38e68-c8f5-4f17-b317-f93e0a9ace55', '唐', '["自君之出矣，梁塵靜不飛。","思君如滿月，夜夜減容輝。"]', '["自君之出矣，梁塵静不飞。","思君如满月，夜夜減容輝。"]', '诗', 'shi', '', NULL, '自君之出矣 辛弘智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785a7173-4151-4402-b93b-482fa27f2391', '又自君之出矣', '又自君之出矣', '02b38e68-c8f5-4f17-b317-f93e0a9ace55', '唐', '["自君之出矣，寶鏡爲誰明。","思君如隴水，常聞嗚咽聲。"]', '["自君之出矣，寶镜爲誰明。","思君如隴水，常闻嗚咽声。"]', '诗', 'shi', '', NULL, '又自君之出矣 辛弘智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797f4c02-692a-4ff2-a964-e6561b3eb802', '題春夢秋歸故里', '題春梦秋归故里', '94c7e246-2fbc-43ff-ba65-4b27c7e2dbdc', '唐', '["故國歸路賒，春晚在天涯。","明月夜來夢，碧山秋到家。","開窗聞落葉，遠墅見晴鴉。","驚起曉庭際，鶯啼桃杏花。"]', '["故国归路賒，春晚在天涯。","明月夜来梦，碧山秋到家。","开窗闻落葉，远墅见晴鴉。","驚起晓庭際，鶯啼桃杏花。"]', '诗', 'shi', '', NULL, '題春夢秋歸故里 吉師老 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2574727e-02c7-4b65-b1bc-2f23c1777235', '看蜀女轉昭君變', '看蜀女轉昭君变', '94c7e246-2fbc-43ff-ba65-4b27c7e2dbdc', '唐', '["妖姬未著石榴裠，自道家連錦水濆。","檀口解知千載事，清詞堪歎九秋文。","翠眉顰處楚邊月，畫卷開時塞外雲。","說盡綺羅當日恨，昭君傳意向文君。"]', '["妖姬未著石榴裠，自道家連錦水濆。","檀口解知千載事，清词堪歎九秋文。","翠眉顰处楚邊月，畫卷开时塞外云。","说尽綺羅當日恨，昭君傳意向文君。"]', '诗', 'shi', '', NULL, '看蜀女轉昭君變 吉師老 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c77c48d-9a3c-4bc7-8a2b-565214e334b3', '放猨', '放猨', '94c7e246-2fbc-43ff-ba65-4b27c7e2dbdc', '唐', '["放爾千山萬水身，野泉晴樹好爲鄰。","啼時莫近瀟湘岸，明月孤舟有旅人。"]', '["放爾千山万水身，野泉晴樹好爲鄰。","啼时莫近瀟湘岸，明月孤舟有旅人。"]', '诗', 'shi', '', NULL, '放猨 吉師老 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132e2505-fc0e-4073-82a9-bbf6d17337e2', '鴛鴦', '鴛鴦', '94c7e246-2fbc-43ff-ba65-4b27c7e2dbdc', '唐', '["江島濛濛煙靄微，綠蕪深處刷毛衣。","渡頭驚起一雙去，飛上文君舊錦機。"]', '["江島濛濛煙靄微，綠蕪深处刷毛衣。","渡头驚起一雙去，飞上文君旧錦機。"]', '诗', 'shi', '', NULL, '鴛鴦 吉師老 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b7e6e9-8eb9-4bf8-baac-678c6a4ef6dd', '巫峽聽猿', '巫峽听猿', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["巴江猨嘯苦，響入客舟中。","孤枕破殘夢，三聲隨曉風。","連雲波澹澹，和霧雨濛濛。","巫峽去家遠，不堪魂斷空。"]', '["巴江猨嘯苦，响入客舟中。","孤枕破殘梦，三声隨晓风。","連云波澹澹，和霧雨濛濛。","巫峽去家远，不堪魂斷空。"]', '诗', 'shi', '', NULL, '巫峽聽猿 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0350e624-409a-4f2d-b527-3addb1a1063d', '長安春贈友人', '长安春贈友人', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["繁華堪泣帝城春，粉堞青樓勢礙雲。","花對玉鉤簾外發，歌飄塵土路邊聞。","幾多遠客魂空斷，何處王孫酒自醺。","各有歸程千萬里，東風時節恨離羣。"]', '["繁华堪泣帝城春，粉堞青楼勢礙云。","花对玉鉤簾外發，歌飄塵土路邊闻。","幾多远客魂空斷，何处王孫酒自醺。","各有归程千万里，东风时節恨離羣。"]', '诗', 'shi', '', NULL, '長安春贈友人 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6e570e-5d4f-48d2-9692-dc8f9a20f72b', '塞上即事', '塞上即事', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["身似星流跡似蓬，玉關孤望杳溟濛。","寒沙萬里平鋪月，曉角一聲高捲風。","戰士歿邊魂尚哭，單于獵處火猶紅。","分明更想殘宵夢，故國依然在甬東。"]', '["身似星流跡似蓬，玉关孤望杳溟濛。","寒沙万里平鋪月，晓角一声高捲风。","戰士歿邊魂尚哭，單于獵处火猶紅。","分明更想殘宵梦，故国依然在甬东。"]', '诗', 'shi', '', NULL, '塞上即事 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b064e9db-9ce2-4794-a240-67475590e4d5', '宿山驛', '宿山驛', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["文戰何堪功未圖，又驅羸馬指天衢。","露華凝夜渚蓮盡，月彩滿輪山驛孤。","岐路辛勤終日有，鄉關音信隔年無。","好同范蠡扁舟興，高挂一帆歸五湖。"]', '["文戰何堪功未圖，又驱羸马指天衢。","露华凝夜渚蓮尽，月彩满輪山驛孤。","岐路辛勤終日有，乡关音信隔年無。","好同范蠡扁舟兴，高挂一帆归五湖。"]', '诗', 'shi', '', NULL, '宿山驛 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d865681-9856-429b-bc80-1dd0700683b5', '北邙山', '北邙山', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["北邙山草又青青，今日銷魂事可明。","綠酒醉來春未歇，白楊風起柳初晴。","岡原旋葬松新長，年代無人闕半平。","堪取金爐九還藥，不能隨夢向浮生。"]', '["北邙山草又青青，今日銷魂事可明。","綠酒醉来春未歇，白楊风起柳初晴。","岡原旋葬松新长，年代無人闕半平。","堪取金爐九還藥，不能隨梦向浮生。"]', '诗', 'shi', '', NULL, '北邙山 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c7762a9-55bd-4e6e-b442-9f8193a4cb3d', '秋塘曉望', '秋塘晓望', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["鐘盡疎桐散曙鴉，故山煙樹隔天涯。","西風一夜秋塘曉，零落幾多紅藕花。"]', '["鐘尽疎桐散曙鴉，故山煙樹隔天涯。","西风一夜秋塘晓，零落幾多紅藕花。"]', '诗', 'shi', '', NULL, '秋塘曉望 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a8fe92-3175-400a-a875-249a7a4fce19', '水樓感事', '水楼感事', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["高柳螿啼雨後秋，年光空感淚如流。","滿湖菱荇東歸晚，閑倚南軒盡日愁。"]', '["高柳螿啼雨後秋，年光空感泪如流。","满湖菱荇东归晚，闲倚南軒尽日愁。"]', '诗', 'shi', '', NULL, '水樓感事 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('464fcb8e-1bac-4cd7-aadb-5610655818e2', '泊舟', '泊舟', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["身逐煙波魂自驚，木蘭舟上一帆輕。","雲中有寺在何處，山底宿時聞磬聲。"]', '["身逐煙波魂自驚，木蘭舟上一帆轻。","云中有寺在何处，山底宿时闻磬声。"]', '诗', 'shi', '', NULL, '泊舟 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bedcaa71-c405-4222-83ac-0a3f9c61754d', '湘雲', '湘云', 'bdaf9baa-8748-404c-ba27-2ec6bafe4845', '唐', '["□滿湘江雲瑩空，紛紛長對水溶溶。","日西遙望自歸處，盡挂九疑千萬峰。"]', '["□满湘江云瑩空，紛紛长对水溶溶。","日西遙望自归处，尽挂九疑千万峰。"]', '诗', 'shi', '', NULL, '湘雲 吳商浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57bdfc5-2bf5-4295-aaae-99563881bdaf', '秋閨', '秋閨', 'b31ebfc0-ba9b-4b62-9d89-ce574319a0a3', '唐', '["白馬三軍客，青娥十載思。","玉庭霜落夜，羅幌月明時。","鑪冷蜘蛛喜，燈高熠燿期。","愁多不可曙，流涕坐空幃。"]', '["白马三軍客，青娥十載思。","玉庭霜落夜，羅幌月明时。","鑪冷蜘蛛喜，灯高熠燿期。","愁多不可曙，流涕坐空幃。"]', '诗', 'shi', '', NULL, '秋閨 沈祖仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f2599b-31c7-420f-be1b-ef07d79c78c3', '秋閨', '秋閨', 'bb265c81-c0ed-4042-8681-8bf46312038c', '唐', '["斜日空庭暮，幽閨積恨盈。","細風吹帳冷，微月度窗明。","怨坐啼相續，愁眠夢不成。","調琴欲有弄，畏作斷腸聲。"]', '["斜日空庭暮，幽閨積恨盈。","細风吹帳冷，微月度窗明。","怨坐啼相續，愁眠梦不成。","調琴欲有弄，畏作斷腸声。"]', '诗', 'shi', '', NULL, '秋閨 邵士彥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60eba8cc-f726-4bbd-baca-de2989c7d579', '擣衣', '擣衣', '5ee377d4-397c-401d-9d18-bc4907bea0ef', '唐', '["沙塞秋應晚，金閨恨已空。","那堪裂紈素，時許出房櫳。","杵影弄寒月，砧聲調夜風。","裁縫雙淚盡，萬里寄雲中。"]', '["沙塞秋應晚，金閨恨已空。","那堪裂紈素，时許出房櫳。","杵影弄寒月，砧声調夜风。","裁縫雙泪尽，万里寄云中。"]', '诗', 'shi', '', NULL, '擣衣 吳大江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32aa9ad8-f083-41d7-b5c3-bf8dfa13df44', '題慈恩塔', '題慈恩塔', '5bb6f36f-5ad1-4224-9689-baa939fb71fe', '唐', '["漢國山河在，秦陵草樹深。","暮雲千里色，無處不傷心。"]', '["漢国山河在，秦陵草樹深。","暮云千里色，無处不傷心。"]', '诗', 'shi', '', NULL, '題慈恩塔 荆叔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c31f6f-4093-44fb-98c3-9c575e82e56c', '三湘有懷', '三湘有懷', 'fd71e563-c35d-42ba-b32a-fd7b6373a7ed', '唐', '["柳絮飛來別洛陽，梅花落後到三湘。","世情已逐浮雲散，離恨空隨江水長。"]', '["柳絮飞来別洛陽，梅花落後到三湘。","世情已逐浮云散，離恨空隨江水长。"]', '诗', 'shi', '', NULL, '三湘有懷 蕭靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6aae49f-b1b0-418c-8065-ccf0ac3dc7ef', '九日對酒', '九日对酒', 'f44f9bbf-3f19-4695-b0a2-7706500c504c', '唐', '["嘉辰復遇登高臺，良朋笑語傾金罍。","煙攤秋色正堪翫，風惹菊香無限來。","未保亂離今日後，且謀歡洽玉山頹。","誰知靖節當時事，空學狂歌倒載迴。"]', '["嘉辰复遇登高台，良朋笑語傾金罍。","煙攤秋色正堪翫，风惹菊香無限来。","未保亂離今日後，且謀歡洽玉山頹。","誰知靖節當时事，空学狂歌倒載迴。"]', '诗', 'shi', '', NULL, '九日對酒 元凜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55bab28-3326-4f18-8634-b87dfacacdff', '中秋夜不見月', '中秋夜不见月', 'f44f9bbf-3f19-4695-b0a2-7706500c504c', '唐', '["蟾輪何事色全微，賺得佳人出繡幃。","四野霧凝空寂寞，九霄雲鎖絕光輝。","吟詩得句翻停筆，翫處臨尊却掩扉。","公子倚欄猶悵望，嬾將紅燭草堂歸。"]', '["蟾輪何事色全微，賺得佳人出繡幃。","四野霧凝空寂寞，九霄云鎖絕光輝。","吟诗得句翻停笔，翫处臨尊却掩扉。","公子倚欄猶悵望，嬾將紅燭草堂归。"]', '诗', 'shi', '', NULL, '中秋夜不見月 元凜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1dde6b-ca3f-4a0f-bc8a-04e0076cf8d8', '雷塘', '雷塘', 'bb31e977-04ad-485b-b922-304f864f0f6e', '唐', '["九重城闕悲涼盡，一聚園林怨恨長。","花憶所爲猶自笑，草知無道更應荒。","詩名占得風流在，酒興催教運祚亡。","若問皇天惆悵事，只應斜日照雷塘。"]', '["九重城闕悲涼尽，一聚园林怨恨长。","花憶所爲猶自笑，草知無道更應荒。","诗名占得风流在，酒兴催教運祚亡。","若问皇天惆悵事，只應斜日照雷塘。"]', '诗', 'shi', '', NULL, '雷塘 徐振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('242b4ada-ccaf-4507-a401-0e969dab6271', '古意', '古意', 'bb31e977-04ad-485b-b922-304f864f0f6e', '唐', '["擾擾都城曉又昏，六街車馬五侯門。","箕山渭水空明月，可是巢由絕子孫。"]', '["擾擾都城晓又昏，六街车马五侯门。","箕山渭水空明月，可是巢由絕子孫。"]', '诗', 'shi', '', NULL, '古意 徐振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b126375c-a50f-4aed-90a6-2534f8cec3af', '寄人', '寄人', '96380133-80ca-4a8b-aa3a-d6b6181e5508', '唐', '["酷憐風月爲多情，還到春時別恨生。","倚柱尋思倍惆悵，一塲春夢不分明。"]', '["酷怜风月爲多情，還到春时別恨生。","倚柱尋思倍惆悵，一塲春梦不分明。"]', '诗', 'shi', '', NULL, '寄人 張侹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebabaaeb-5a92-4be0-becd-98faaf89cb39', '武昌阻風', '武昌阻风', 'ef06dede-975c-4233-992e-3a9e66e47a8f', '唐', '["江上春風留客舟，無窮歸思滿東流。","與君盡日閑臨水，貪看飛花忘却愁。"]', '["江上春风留客舟，無窮归思满东流。","與君尽日闲臨水，貪看飞花忘却愁。"]', '诗', 'shi', '', NULL, '武昌阻風 方澤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc699167-cda1-4e83-bf22-c5ebb0c30ffd', '秋夜宿淮口', '秋夜宿淮口', 'd14593ef-e50b-4415-8656-99608f8ed1b7', '唐', '["露白草猶青，淮舟倚岸停。","風帆幾處客，天地兩河星。","樹靜禽眠草，沙寒鹿過汀。","明朝誰結伴，直去泛滄溟。"]', '["露白草猶青，淮舟倚岸停。","风帆幾处客，天地兩河星。","樹静禽眠草，沙寒鹿過汀。","明朝誰結伴，直去泛滄溟。"]', '诗', 'shi', '', NULL, '秋夜宿淮口 景池 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c6042a-9a0c-4dd0-9cfa-d75d37e435e3', '贈喬尊師', '贈喬尊師', '43bca173-bd00-4ff8-86f5-73208fd530a3', '唐', '["長忌時人識，有家雲澗深。","性惟耽嗜酒，貧不破除琴。","靜鼓三通齒，頻湯一味參。","知師最知我，相引坐檉陰。"]', '["长忌时人識，有家云澗深。","性惟耽嗜酒，貧不破除琴。","静鼓三通齒，頻湯一味參。","知師最知我，相引坐檉陰。"]', '诗', 'shi', '', NULL, '贈喬尊師 張鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a778c4d-8d35-4b73-bf1a-1f60cb687407', '村行', '村行', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["天淡雨初晴，遊人恨不勝。","亂山啼蜀魄，孤櫂宿巴陵。","影暗村橋柳，光寒水寺燈。","罷吟思故國，窗外有漁罾。"]', '["天淡雨初晴，游人恨不勝。","亂山啼蜀魄，孤櫂宿巴陵。","影暗村橋柳，光寒水寺灯。","罷吟思故国，窗外有漁罾。"]', '诗', 'shi', '', NULL, '村行 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47adf5f0-709b-4edc-bee7-71bc2675bd44', '頴川客舍', '頴川客舍', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["素琴孤劒尚閑遊，誰共芳尊話唱酬。","鄉夢有時生枕上，客情終日在眉頭。","雲拖雨脚連天去，樹夾河聲繞郡流。","回首帝京歸未得，不堪吟倚夕陽樓。"]', '["素琴孤劒尚闲游，誰共芳尊話唱酬。","乡梦有时生枕上，客情終日在眉头。","云拖雨脚連天去，樹夾河声繞郡流。","回首帝京归未得，不堪吟倚夕陽楼。"]', '诗', 'shi', '', NULL, '頴川客舍 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e618eda-400e-4611-b45b-3dc0122b7432', '獨不見', '独不见', '3d6014ae-1bb8-4d0a-bff9-fcba228dfe22', '唐', '["日晚宜春暮，風軟上林朝。","對酒近初節，開樓蕩夜謠。","石橋通小澗，竹路上青霄。","持底誰見許，長愁成細腰。"]', '["日晚宜春暮，风軟上林朝。","对酒近初節，开楼蕩夜謠。","石橋通小澗，竹路上青霄。","持底誰见許，长愁成細腰。"]', '诗', 'shi', '', NULL, '獨不見 王訓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b945b076-18ae-4f09-aed3-b0986f44030a', '歸去來引', '归去来引', 'b6fcbf3a-114f-4b05-bbfb-b26c236c335d', '唐', '["歸去來，歸期不可違。","相見旋明月，浮雲共我歸。"]', '["归去来，归期不可違。","相见旋明月，浮云共我归。"]', '诗', 'shi', '', NULL, '歸去來引 張熾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd1e3a37-cd81-4b4b-998c-efdb7f8df9ae', '結客少年場行', '結客少年場行', 'cbd92d57-cc9c-4374-90aa-06d246d4f394', '唐', '["幽幷俠少年，金絡控連錢。","竊符方救趙，擊筑正懷燕。","輕生辭鳳闕，揮袂上祈連。","陸離橫寶劒，出沒騖征旃。","蒙輪恆顧敵，超乘忽爭先。","摧枯逾百戰，拓地遠三千。","骨都魂已散，樓蘭首復傳。","龍城含宿霧，瀚海接遙天。","歌吹金微返，振旅玉門旋。","烽火今已息，非復照甘泉。"]', '["幽幷俠少年，金絡控連錢。","竊符方救趙，擊筑正懷燕。","轻生辞鳳闕，揮袂上祈連。","陸離橫寶劒，出沒騖征旃。","蒙輪恆顧敵，超乘忽爭先。","摧枯逾百戰，拓地远三千。","骨都魂已散，楼蘭首复傳。","龙城含宿霧，瀚海接遙天。","歌吹金微返，振旅玉门旋。","烽火今已息，非复照甘泉。"]', '诗', 'shi', '', NULL, '結客少年場行 虞羽客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53cd72f1-bdfe-402b-8fa8-13d8afcc74a4', '塞上', '塞上', 'a684e3a8-270e-4df1-aec8-ac36b0288dd3', '唐', '["出門何處問西東，指畫翻爲語論同。","到此客頭潛覺白，未秋山葉已飄紅。","帳前影落傳書鴈，日下聲交失馬翁。","早晚回鞭復南去，大衣高蓋漢鄉風。"]', '["出门何处问西东，指畫翻爲語論同。","到此客头潛覺白，未秋山葉已飄紅。","帳前影落傳书鴈，日下声交失马翁。","早晚回鞭复南去，大衣高蓋漢乡风。"]', '诗', 'shi', '', NULL, '塞上 鄭渥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd7e8bc-9298-4e18-b1cf-8fe71398c653', '洛陽道', '洛陽道', 'a684e3a8-270e-4df1-aec8-ac36b0288dd3', '唐', '["客亭門外路東西，多少喧騰事不齊。","楊柳惹鞭公子醉，苧麻掩淚魯人迷。","通宵塵土飛山月，是處經營夾御堤。","頃刻知音幾存歿，半回依約認輪蹄。"]', '["客亭门外路东西，多少喧腾事不齊。","楊柳惹鞭公子醉，苧麻掩泪魯人迷。","通宵塵土飞山月，是处經營夾御堤。","頃刻知音幾存歿，半回依約認輪蹄。"]', '诗', 'shi', '', NULL, '洛陽道 鄭渥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209d0409-e140-4813-8b15-c82443376912', '宜春郡城聞猨', '宜春郡城闻猨', '3777dd6d-2eae-4dd1-ac0b-dded06b1d172', '唐', '["怨抱霜枝向月啼，數聲清繞郡城低。","那堪日夜有雲雨，便似巫山與建溪。"]', '["怨抱霜枝向月啼，數声清繞郡城低。","那堪日夜有云雨，便似巫山與建溪。"]', '诗', 'shi', '', NULL, '宜春郡城聞猨 崔江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3801b7-f70f-4697-aa86-d86d9351e0af', '謫宜陽到荆渚', '謫宜陽到荆渚', 'ebcf0b26-d30c-44d4-b927-97a06de68c81', '唐', '["漢江江水水連天，被謫宜陽路幾千。","爲問野人山鳥語，問予歸櫂是何年。"]', '["漢江江水水連天，被謫宜陽路幾千。","爲问野人山鸟語，问予归櫂是何年。"]', '诗', 'shi', '', NULL, '謫宜陽到荆渚 李伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cabb20ae-5de8-4a89-8bb2-9fa8355a3a4f', '九嶷山', '九嶷山', '277c0081-2665-451b-a3f7-79a4d6fc40ef', '唐', '["鼎湖冠劒有遺蹤，晉漢真人羽化同。","九轉藥成丹竈冷，五車雲去玉堂空。","仙家日月蓬壺裏，塵世煙花夢寐中。","徒有舊山流水畔，老松枝葉苦吟風。"]', '["鼎湖冠劒有遺蹤，晉漢真人羽化同。","九轉藥成丹竈冷，五车云去玉堂空。","仙家日月蓬壺裏，塵世煙花梦寐中。","徒有旧山流水畔，老松枝葉苦吟风。"]', '诗', 'shi', '', NULL, '九嶷山 劉望 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e20a10b1-b1a0-4369-8923-9a2ba3596dd0', '郡城放猨獻衛使君', '郡城放猨獻衛使君', '78e16b40-eeca-48bc-93a8-583bd369e617', '唐', '["千巖萬壑與雲連，放出雕籠任自然。","葉洒驚風啼暮雨，月凝殘雪飲流泉。","臨岐莫似三聲日，避射須依繞樹年。","應解感恩尋太守，攀蘿時復到樓前。"]', '["千巖万壑與云連，放出雕籠任自然。","葉洒驚风啼暮雨，月凝殘雪饮流泉。","臨岐莫似三声日，避射須依繞樹年。","應解感恩尋太守，攀蘿时复到楼前。"]', '诗', 'shi', '', NULL, '郡城放猨獻衛使君 易思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c14ba46d-8982-450d-a89e-e56d92237218', '題袁州龍興寺', '題袁州龙兴寺', '78e16b40-eeca-48bc-93a8-583bd369e617', '唐', '["百尺古松松下寺，寶幡朱蓋畫珊珊。","閑庭甘露幾回落，青石綠苔猶未乾。"]', '["百尺古松松下寺，寶幡朱蓋畫珊珊。","闲庭甘露幾回落，青石綠苔猶未乾。"]', '诗', 'shi', '', NULL, '題袁州龍興寺 易思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae67fcf9-cc58-40e9-a772-e64a753d2dc3', '山中送弟方質', '山中送弟方質', '78e16b40-eeca-48bc-93a8-583bd369e617', '唐', '["山中殷勤弟別兄，兄還送弟下山行。","蘆花飛處秋風起，日暮不堪聞鴈聲。"]', '["山中殷勤弟別兄，兄還送弟下山行。","蘆花飞处秋风起，日暮不堪闻鴈声。"]', '诗', 'shi', '', NULL, '山中送弟方質 易思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ed340f-3b49-4865-be19-0255c52bf52a', '尋易尊師不遇', '尋易尊師不遇', '78e16b40-eeca-48bc-93a8-583bd369e617', '唐', '["爛熳紅霞光照衣，苔封白石路微微。","華陽洞裏人何在，落盡松花不見歸。"]', '["爛熳紅霞光照衣，苔封白石路微微。","华陽洞裏人何在，落尽松花不见归。"]', '诗', 'shi', '', NULL, '尋易尊師不遇 易思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89d0803f-a44a-4348-a004-2f5f3da50319', '秋日寄弟', '秋日寄弟', 'f8d74f61-5256-4ff6-9e94-974fae7588cc', '唐', '["涼風颯庭戶，漸疑華髮侵。","已經楊柳謝，猶聽蟪蛄吟。","雨助灘聲出，雲連野色深。","鶺鴒今在遠，年酒共誰斟。"]', '["涼风颯庭戶，漸疑华髮侵。","已經楊柳謝，猶听蟪蛄吟。","雨助灘声出，云連野色深。","鶺鴒今在远，年酒共誰斟。"]', '诗', 'shi', '', NULL, '秋日寄弟 趙防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8aed50c-ce5d-40e2-9104-b7f232096e48', '楊岐山', '楊岐山', '3ffa75b7-5a66-41c4-b140-d97caf8051fd', '唐', '["千峰圍古寺，深處敞樓臺。","景異尋常處，人須特達來。","松杉寒更茂，嵐靄晝還開。","欲續豐碑語，含毫恨不才。"]', '["千峰圍古寺，深处敞楼台。","景異尋常处，人須特達来。","松杉寒更茂，嵐靄晝還开。","欲續豐碑語，含毫恨不才。"]', '诗', 'shi', '', NULL, '楊岐山 劉廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06cc777-45e3-4469-aec4-89107c08dd8f', '南源山', '南源山', '6487b79b-547f-4a72-b2ee-28218875ddae', '唐', '["修徑投幽隱，輕裘怯暮寒。","閑僧能解榻，倦客得休鞍。","白雨鳴山麓，青燈語夜闌。","明朝梯石路，更仗筍輿安。"]', '["修徑投幽隐，轻裘怯暮寒。","闲僧能解榻，倦客得休鞍。","白雨鳴山麓，青灯語夜闌。","明朝梯石路，更仗筍輿安。"]', '诗', 'shi', '', NULL, '南源山 姚偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c6c4cf-9bbe-401a-96c8-984edc71dd0b', '下第夜吟', '下第夜吟', '3047859c-eebe-4c73-8c0f-5889119edf86', '唐', '["擾擾東西南北情，何人於此悟浮生。","還緣無月春風夜，暫得獨聞流水聲。"]', '["擾擾东西南北情，何人於此悟浮生。","還緣無月春风夜，暫得独闻流水声。"]', '诗', 'shi', '', NULL, '下第夜吟 戴衢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090b7e2e-5691-41ad-a0af-27571fc7464e', '句', '句', '3047859c-eebe-4c73-8c0f-5889119edf86', '唐', '["坐落千門日，吟殘午夜燈。"]', '["坐落千门日，吟殘午夜灯。"]', '诗', 'shi', '', NULL, '句 戴衢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147cef42-ffdc-4a29-b902-c693ded7739f', '詠月', '詠月', '16cd72a3-94d7-4aef-b114-3dbfc5d9e78f', '唐', '["昨夜圓非今夜圓，却疑圓處減嬋娟。","一年十二度圓缺，能得幾多時少年。"]', '["昨夜圓非今夜圓，却疑圓处減嬋娟。","一年十二度圓缺，能得幾多时少年。"]', '诗', 'shi', '', NULL, '詠月 李建樞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b31907-9837-444c-818a-e3416fabe791', '謝人惠琴材', '謝人惠琴材', 'e24c33f1-8218-4b24-90cc-c0c928b1429b', '唐', '["風撼桐絲帶月明，羽人乘醉截秋聲。","七弦妙制饒仙品，三尺良材稱道情。","池小未開春浪泛，岳低猶欠暮雲生。","何因乞與元中術，臨化無妨膝上橫。"]', '["风撼桐絲带月明，羽人乘醉截秋声。","七弦妙制饒仙品，三尺良材稱道情。","池小未开春浪泛，岳低猶欠暮云生。","何因乞與元中術，臨化無妨膝上橫。"]', '诗', 'shi', '', NULL, '謝人惠琴材 謝邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a68fccd-0f54-4d5a-8890-6e1dd8cb7ace', '謝僧寄拄杖', '謝僧寄拄杖', 'e24c33f1-8218-4b24-90cc-c0c928b1429b', '唐', '["峭壁猨啼採處深，一枝奇異出孤岑。","感師千里寄來意，發我片雲歸去心。","窗外冷敲簷凍折，溪邊閑點戲魚沉。","他年必藉相攜力，蹇步猶能返故林。"]', '["峭壁猨啼採处深，一枝奇異出孤岑。","感師千里寄来意，發我片云归去心。","窗外冷敲簷凍折，溪邊闲点戲鱼沉。","他年必藉相携力，蹇步猶能返故林。"]', '诗', 'shi', '', NULL, '謝僧寄拄杖 謝邈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a2a3209-ca09-4207-b90f-4c125d569654', '失題二首 一', '失題二首 一', 'd288504d-f971-4d34-b815-5877ba6dfb34', '唐', '["天若無雪霜，青松不如草。","地若無山川，何人重平道。"]', '["天若無雪霜，青松不如草。","地若無山川，何人重平道。"]', '诗', 'shi', '', NULL, '失題二首 一 唐備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d92c10-f2bc-4223-865a-b3611bbfc4d6', '失題二首 二', '失題二首 二', 'd288504d-f971-4d34-b815-5877ba6dfb34', '唐', '["一日天無風，四溟波盡息。","人心風不吹，波浪高百尺。"]', '["一日天無风，四溟波尽息。","人心风不吹，波浪高百尺。"]', '诗', 'shi', '', NULL, '失題二首 二 唐備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a114a95b-97b8-491f-a049-4572de79fbe3', '道傍木', '道傍木', 'd288504d-f971-4d34-b815-5877ba6dfb34', '唐', '["狂風拔倒樹，樹倒根已露。","上有數枝藤，青青猶未悟。"]', '["狂风拔倒樹，樹倒根已露。","上有數枝藤，青青猶未悟。"]', '诗', 'shi', '', NULL, '道傍木 唐備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f61af241-e470-4cef-9910-d963a54841ce', '失題', '失題', '71dd057c-7ca9-4077-b84e-2179728def37', '唐', '["午醉醒來晚，無人夢自驚。","夕陽如有意，長傍小窗明。"]', '["午醉醒来晚，無人梦自驚。","夕陽如有意，长傍小窗明。"]', '诗', 'shi', '', NULL, '失題 方棫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4b5610-c5c6-4855-bff8-206911bccdea', '失題', '失題', '8ca950be-1ecc-4fc0-9a66-dd7c89c6c8d8', '唐', '["舉意三江竭，興心四海枯。","南游李邕死，北望宋珪殂。"]', '["舉意三江竭，兴心四海枯。","南游李邕死，北望宋珪殂。"]', '诗', 'shi', '', NULL, '失題 范夜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52d532f-fe8c-4ba0-a374-0f14c9fcf23b', '失題', '失題', '957e8693-821c-410d-9016-7fc4d217d96e', '唐', '["酒瀉銀瓶倒底清，夜深絲竹鳳凰鳴。","紅妝醉起一花落，更引春風無限情。"]', '["酒瀉銀瓶倒底清，夜深絲竹鳳凰鳴。","紅妝醉起一花落，更引春风無限情。"]', '诗', 'shi', '', NULL, '失題 盧羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c15f7c-15a1-4b4b-b3e3-5f89dad851b4', '投盧尚書', '投盧尚书', '957e8693-821c-410d-9016-7fc4d217d96e', '唐', '["無力不任爲走役，有文安敢滯清平。","從來若把耕桑定，免恃雕蟲悞此生。"]', '["無力不任爲走役，有文安敢滯清平。","從来若把耕桑定，免恃雕蟲悞此生。"]', '诗', 'shi', '', NULL, '投盧尚書 盧羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04594d8e-1160-4f31-88d6-a5797f175c82', '失題二首 一', '失題二首 一', '62ca6d5e-d157-48e7-bdfa-c4b6afad1ca9', '唐', '["駑駘嘶叫知無定，騏驥低垂自有心。","山上高松溪畔竹，清風纔動是知音。"]', '["駑駘嘶叫知無定，騏驥低垂自有心。","山上高松溪畔竹，清风纔动是知音。"]', '诗', 'shi', '', NULL, '失題二首 一 楊行敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8489e54-4cf8-4b83-93d1-9eeccbd70676', '失題二首 二', '失題二首 二', '62ca6d5e-d157-48e7-bdfa-c4b6afad1ca9', '唐', '["杜鵑花裏杜鵑啼，淺紫深紅更傍溪。","遲日霽光搜客思，曉來山路恨如迷。"]', '["杜鵑花裏杜鵑啼，淺紫深紅更傍溪。","遲日霽光搜客思，晓来山路恨如迷。"]', '诗', 'shi', '', NULL, '失題二首 二 楊行敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e2555d3-3988-4425-89fc-40f5db11ddbf', '吳江別王長史', '吳江別王长史', 'eee2b0d9-d682-45e7-b13c-4e807f54d675', '唐', '["多年襆被玉山岑，鬢雪欺人忽滿簪。","駑馬雖然貪短豆，野麋終是憶長林。","鱸魚未得乘歸興，鷗鳥惟應信此心。","見說新橋好風景，會須乘月濯煩襟。"]', '["多年襆被玉山岑，鬢雪欺人忽满簪。","駑马雖然貪短豆，野麋終是憶长林。","鱸鱼未得乘归兴，鷗鸟惟應信此心。","见说新橋好风景，會須乘月濯煩襟。"]', '诗', 'shi', '', NULL, '吳江別王長史 張懷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b32b877-081c-4713-87ca-5095a5ca6844', '題天台石橋', '題天台石橋', '8acf99a5-7032-42db-bc8c-e797e5173800', '唐', '["白石峰猶在，橫橋一徑微。","多年無客過，落日有雲歸。","水淨苔生髮，山寒樹著衣。","如何方廣寺，千古去人稀。"]', '["白石峰猶在，橫橋一徑微。","多年無客過，落日有云归。","水淨苔生髮，山寒樹著衣。","如何方廣寺，千古去人稀。"]', '诗', 'shi', '', NULL, '題天台石橋 趙湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcfb1c37-bfc3-40ac-9b4a-18929c60a7a2', '寄朗陵兄', '寄朗陵兄', '15144d96-4cb3-41b3-bf22-d6788756b1da', '唐', '["刺舉官猶屈，風謠政已成。","行看換龜組，奏最謁承明。"]', '["刺舉官猶屈，风謠政已成。","行看換龟組，奏最謁承明。"]', '诗', 'shi', '', NULL, '寄朗陵兄 楊持 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16af518c-7417-4402-9a24-d32858116958', '詠𣻕溪在歷陽西一里', '詠𣻕溪在歷陽西一里', '72ffeda4-4554-4ae4-8976-b05081e443da', '唐', '["泠泠一帶清溪水，遠派□通歷陽市。","涓涓出自碧湖中，流入楚江煙霧裏。"]', '["泠泠一带清溪水，远派□通歷陽市。","涓涓出自碧湖中，流入楚江煙霧裏。"]', '诗', 'shi', '', NULL, '詠𣻕溪在歷陽西一里 李聰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0352140f-db28-4a6d-bbb9-ab44da07780a', '耒陽杜工部祠堂', '耒陽杜工部祠堂', '23f203f5-7389-4182-a0ef-dc9ecbc62eb8', '唐', '["手接汨羅水，天心知所存。","固教工部死，來伴大夫魂。","流落同千古，風騷共一源。","消凝傷往事，斜日隱頹垣。"]', '["手接汨羅水，天心知所存。","固教工部死，来伴大夫魂。","流落同千古，风騷共一源。","消凝傷往事，斜日隐頹垣。"]', '诗', 'shi', '', NULL, '耒陽杜工部祠堂 徐介 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f0f7c7-ef32-42c8-92f5-7fe4672efe89', '登單于臺', '登單于台', 'e4bcaf94-5b0d-4add-8c68-c08d2eca37a5', '唐', '["悔上層樓望，翻成極目愁。","路沿蔥嶺去，河背玉關流。","馬散眠沙磧，兵閑倚戍樓。","殘陽三會角，吹白旅人頭。"]', '["悔上層楼望，翻成極目愁。","路沿蔥嶺去，河背玉关流。","马散眠沙磧，兵闲倚戍楼。","殘陽三會角，吹白旅人头。"]', '诗', 'shi', '', NULL, '登單于臺 李士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b6c7dc-3204-4fcc-816c-e05748204638', '登閣', '登閣', 'e4bcaf94-5b0d-4add-8c68-c08d2eca37a5', '唐', '["亂後獨來登大閣，凭闌舉目盡傷心。","長堤過雨人行少，廢苑經秋草自深。","破落侯家通永巷，蕭條宮樹接疎林。","總輸釋氏青蓮館，依舊重重布地金。"]', '["亂後独来登大閣，凭闌舉目尽傷心。","长堤過雨人行少，廢苑經秋草自深。","破落侯家通永巷，蕭條宮樹接疎林。","總輸釋氏青蓮館，依旧重重布地金。"]', '诗', 'shi', '', NULL, '登閣 李士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e580be6a-13b0-43fc-97a9-5748cf0cf4da', '山中作', '山中作', '29266868-c898-4e4b-8f4e-9d2eae62425d', '唐', '["草堂在巖下，卜居聊自適。","桂氣滿堦庭，松陰生枕席。","遠瞻惟鳥度，旁信無人跡。","靄靄雲生峰，潺潺水流石。","頗尋黃卷理，庶就丹砂益。","此即契吾生，何爲苦塵役。"]', '["草堂在巖下，卜居聊自適。","桂氣满堦庭，松陰生枕席。","远瞻惟鸟度，旁信無人跡。","靄靄云生峰，潺潺水流石。","頗尋黄卷理，庶就丹砂益。","此即契吾生，何爲苦塵役。"]', '诗', 'shi', '', NULL, '山中作 馮道之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33da592-a67a-4866-a95e-abf58db3b46f', '短歌二首 一', '短歌二首 一', 'c5485771-dd45-4cf9-a76c-6a3ed16e1cf7', '唐', '["窮通皆是運，榮辱豈關身。","不願門前客，看時逢故人。"]', '["窮通皆是運，榮辱豈关身。","不願门前客，看时逢故人。"]', '诗', 'shi', '', NULL, '短歌二首 一 徐謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49511eb0-9fe4-4eba-b85b-c0d88bb5876f', '短歌二首 二', '短歌二首 二', 'c5485771-dd45-4cf9-a76c-6a3ed16e1cf7', '唐', '["意氣青雲裏，爽朗煙霞外。","不羨一囊錢，唯重心襟會。"]', '["意氣青云裏，爽朗煙霞外。","不羨一囊錢，唯重心襟會。"]', '诗', 'shi', '', NULL, '短歌二首 二 徐謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c6f067-f897-47b0-9352-cc832be7195b', '塞下曲', '塞下曲', '743cb80e-754a-4d49-ac64-0876297052b2', '唐', '["秋日幷州路，黃榆落故關。","孤城吹角罷，數騎射鵰還。","帳幕遙臨水，牛羊自下山。","行人正垂淚，烽火起雲間。"]', '["秋日幷州路，黄榆落故关。","孤城吹角罷，數騎射鵰還。","帳幕遙臨水，牛羊自下山。","行人正垂泪，烽火起云间。"]', '诗', 'shi', '', NULL, '塞下曲 楊達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('462a63d2-b637-48f7-a395-e17ac2eac337', '明妃怨', '明妃怨', '743cb80e-754a-4d49-ac64-0876297052b2', '唐', '["漢國明妃去不還，馬駝弦管向陰山。","匣中縱有菱花鏡，羞對單于照舊顏。"]', '["漢国明妃去不還，马駝弦管向陰山。","匣中縱有菱花镜，羞对單于照旧顏。"]', '诗', 'shi', '', NULL, '明妃怨 楊達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a24051a-8720-48fc-969e-d0c385f02198', '送鄒尊師歸洞庭', '送鄒尊師归洞庭', 'd5f2d220-d508-4f20-803b-49149e458736', '唐', '["衆島在波心，曾居舊隱林。","近聞飛檄急，轉憶臥雲深。","賣藥唯供酒，歸舟只載琴。","遙知明月夜，坐石自開襟。"]', '["衆島在波心，曾居旧隐林。","近闻飞檄急，轉憶臥云深。","賣藥唯供酒，归舟只載琴。","遙知明月夜，坐石自开襟。"]', '诗', 'shi', '', NULL, '送鄒尊師歸洞庭 楊逵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2cb6031-e625-4c23-b3df-b46f20f4e5ed', '送張兵曹赴營田', '送張兵曹赴營田', '82aa15f1-dc04-440b-9f53-47c582876a0b', '唐', '["河曲今無戰，王師每務農。","選才當重委，足食乃深功。","草色孤城外，雲陰絕漠中。","蕭關休歎別，歸望在乘騘。"]', '["河曲今無戰，王師每務農。","選才當重委，足食乃深功。","草色孤城外，云陰絕漠中。","蕭关休歎別，归望在乘騘。"]', '诗', 'shi', '', NULL, '送張兵曹赴營田 魏兼恕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ddcc0b-4a69-492b-8611-85f8446373e6', '晚霽登汝南大雲閣', '晚霽登汝南大云閣', '2531b786-440c-4997-816e-2afffd1e1d2f', '唐', '["禪宮新歇雨，香閣晚登臨。","邑樹晴光起，川苗佳氣深。","水包城下岸，雲細郢中岑。","自歎牽卑日，聊開望遠心。"]', '["禪宮新歇雨，香閣晚登臨。","邑樹晴光起，川苗佳氣深。","水包城下岸，云細郢中岑。","自歎牽卑日，聊开望远心。"]', '诗', 'shi', '', NULL, '晚霽登汝南大雲閣 賈彥璋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1bad74-9d09-448f-a90e-9fb6482d4043', '宿香山閣', '宿香山閣', '2531b786-440c-4997-816e-2afffd1e1d2f', '唐', '["暝望香山閣，梯雲宿半空。","軒窗閉潮海，枕席拂煙虹。","朱網防棲鴿，紗燈護夕蟲。","一聞雞唱曉，已見日曈曈。"]', '["暝望香山閣，梯云宿半空。","軒窗閉潮海，枕席拂煙虹。","朱網防棲鴿，紗灯護夕蟲。","一闻雞唱晓，已见日曈曈。"]', '诗', 'shi', '', NULL, '宿香山閣 賈彥璋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7743a29-eba6-442f-bf74-4c03814ef69b', '蘇著作山池', '蘇著作山池', '2531b786-440c-4997-816e-2afffd1e1d2f', '唐', '["水樹子雲家，峯瀛宛不賒。","芥浮舟是葉，蓮發岫爲花。","酌蟻開春甕，觀魚憑海查。","游蘇多石友，題贈滿瑤華。"]', '["水樹子云家，峯瀛宛不賒。","芥浮舟是葉，蓮發岫爲花。","酌蟻开春甕，观鱼憑海查。","游蘇多石友，題贈满瑤华。"]', '诗', 'shi', '', NULL, '蘇著作山池 賈彥璋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47dd530-e0e2-4fc3-bd82-bf23df3f7997', '王龍驤墓', '王龙驤墓', '2531b786-440c-4997-816e-2afffd1e1d2f', '唐', '["昔擅登壇寵，爰光典午朝。","刀懸臨益夢，龍啓渡江謠。","茂績當年舉，英魂此地銷。","唯餘孤壠上，日夕起松飆。"]', '["昔擅登壇寵，爰光典午朝。","刀懸臨益梦，龙啓渡江謠。","茂績當年舉，英魂此地銷。","唯餘孤壠上，日夕起松飆。"]', '诗', 'shi', '', NULL, '王龍驤墓 賈彥璋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a80573-86e7-46cf-84e7-97db424eed08', '折楊柳', '折楊柳', 'fac6668d-5959-42b6-bc5f-b0059f44cf39', '唐', '["垂柳拂妝臺，葳蕤葉半開。","年華枝上見，邊思曲中來。","嫩色宜新雨，輕花伴落梅。","朝朝倦攀折，征戍幾時回。"]', '["垂柳拂妝台，葳蕤葉半开。","年华枝上见，邊思曲中来。","嫩色宜新雨，轻花伴落梅。","朝朝倦攀折，征戍幾时回。"]', '诗', 'shi', '', NULL, '折楊柳 歐陽瑾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fc3952a-8dfd-4f22-bcdd-06dfe9c1cf91', '江南曲', '江南曲', 'e641bec4-bce9-4750-93da-6adefed75dfa', '唐', '["湖上女，江南花，無雙越女春浣紗。","風似箭，月如弦，少年吳兒曉進船。","郗家子弟謝家郎，烏巾白袷紫香囊。","菱歌思欲絕，楚舞斷人腸。","歌舞未終涕雙隕，舊宮坡陁纔嶙隱。","西山暮雨過江來，北渚春雲沿海盡。","渡口水流緩，妾歸宵剩遲。","含情爲君再理曲，月華照出澄江時。"]', '["湖上女，江南花，無雙越女春浣紗。","风似箭，月如弦，少年吳兒晓進船。","郗家子弟謝家郎，烏巾白袷紫香囊。","菱歌思欲絕，楚舞斷人腸。","歌舞未終涕雙隕，旧宮坡陁纔嶙隐。","西山暮雨過江来，北渚春云沿海尽。","渡口水流緩，妾归宵剩遲。","含情爲君再理曲，月华照出澄江时。"]', '诗', 'shi', '', NULL, '江南曲 李叔卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f48b4c67-9f39-4667-b557-723bbd4d5eb9', '芳樹', '芳樹', 'e641bec4-bce9-4750-93da-6adefed75dfa', '唐', '["春看玫瑰樹，西鄰即宋家。","門深重暗葉，牆近度飛花。","影拂桃陰淺，香傳李逕斜。","靚妝愁日暮，流涕向窗紗。"]', '["春看玫瑰樹，西鄰即宋家。","门深重暗葉，牆近度飞花。","影拂桃陰淺，香傳李逕斜。","靚妝愁日暮，流涕向窗紗。"]', '诗', 'shi', '', NULL, '芳樹 李叔卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d3543d-429b-423e-9b80-70d66a4e9ec7', '送楊諫議赴河西節度判官兼呈韓王二侍御', '送楊諫議赴河西節度判官兼呈韓王二侍御', '2e9fb39d-f793-489b-868f-2b97bb8c9daa', '唐', '["賢哉征西將，幕府多俊人。","籌議秉刀尺，話言在經綸。","先鞭羨之子，走馬辭咸秦。","庭論許名實，數公當即真。","行行弄文翰，婉婉光使臣。","今者所從誰，不聞歌苦辛。","黃雲蕭關道，白日驚沙塵。","虜寇有時獵，漢兵行復巡。","王師已無戰，傳檄奉良臣。"]', '["賢哉征西將，幕府多俊人。","籌議秉刀尺，話言在經綸。","先鞭羨之子，走马辞咸秦。","庭論許名實，數公當即真。","行行弄文翰，婉婉光使臣。","今者所從誰，不闻歌苦辛。","黄云蕭关道，白日驚沙塵。","虜寇有时獵，漢兵行复巡。","王師已無戰，傳檄奉良臣。"]', '诗', 'shi', '', NULL, '送楊諫議赴河西節度判官兼呈韓王二侍御 熊曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac0b9cb-3aee-4c3f-bc88-b822bcccb36d', '登巴陵開元寺西閣贈衡嶽僧方外', '登巴陵开元寺西閣贈衡嶽僧方外', '8ff88681-e02a-43c6-a971-6e14890d81f3', '唐', '["衡嶽有開士，五峰秀貞骨。","見君萬里心，海水照秋月。","大臣南溟去，問道皆請謁。","灑以甘露言，清涼潤肌髮。","湖海落天鏡，香閣凌銀闕。","登眺餐惠風，心花期啓發。"]', '["衡嶽有开士，五峰秀貞骨。","见君万里心，海水照秋月。","大臣南溟去，问道皆請謁。","灑以甘露言，清涼潤肌髮。","湖海落天镜，香閣凌銀闕。","登眺餐惠风，心花期啓發。"]', '诗', 'shi', '', NULL, '登巴陵開元寺西閣贈衡嶽僧方外 李賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62a83c3-7e5d-409f-bba3-9fa3358461f6', '登瓦官寺閣', '登瓦官寺閣', '8ff88681-e02a-43c6-a971-6e14890d81f3', '唐', '["晨登瓦官閣，極眺金陵城。","鍾山對北戶，淮水入南榮。","漫漫雨花落，嘈嘈天樂鳴。","兩廊振法鼓，四角吹風箏。","杳無霄漢上，仰攀日月行。","山空霸氣滅，地古寒陰生。","寥廓雲海晚，蒼茫宮觀平。","門餘閶闔字，樓識鳳凰名。","雷作百川動，神扶萬栱傾。","靈光一向貴，長此鎮吳京。"]', '["晨登瓦官閣，極眺金陵城。","鍾山对北戶，淮水入南榮。","漫漫雨花落，嘈嘈天乐鳴。","兩廊振法鼓，四角吹风箏。","杳無霄漢上，仰攀日月行。","山空霸氣滅，地古寒陰生。","寥廓云海晚，蒼茫宮观平。","门餘閶闔字，楼識鳳凰名。","雷作百川动，神扶万栱傾。","靈光一向貴，长此鎮吳京。"]', '诗', 'shi', '', NULL, '登瓦官寺閣 李賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a9a056-6d6e-4d72-b635-29c8a99c7f10', '金陵懷古', '金陵懷古', '0cb3f733-e3da-45ba-a427-2c1d13ecde30', '唐', '["晉末英雄起，神器淪荒服。","胡月蝕中原，白日升暘谷。","金陵實形勝，關山固重複。","巨壑隍北壖，長江塹西隩。","鑿山擬嵩華，穿地象伊穀。","草昧席羅圖，蓽路戴黃屋。","一時因地險，五世享天祿。","禮樂何煌煌，文章紛郁郁。","多士春林秀，作頌清風穆。","出入三百年，朝事幾翻覆。","攙搶如雲勃，鯨鯢旋自曝。","倦聞金鼎移，驟覩靈龜卜。","吁嗟王氣盡，坐悲天運倏。","天道何茫茫，善淫乃相復。","行路偏衣半，遂亡大梁族。","日隱汀洲上，登艫𦪇川陸。","月迴吳山樹，風聞楚江鵠。","因依蘭蕙藂，採擷不盈掬。"]', '["晉末英雄起，神器淪荒服。","胡月蝕中原，白日升暘谷。","金陵實形勝，关山固重複。","巨壑隍北壖，长江塹西隩。","鑿山擬嵩华，穿地象伊穀。","草昧席羅圖，蓽路戴黄屋。","一时因地險，五世享天祿。","禮乐何煌煌，文章紛郁郁。","多士春林秀，作頌清风穆。","出入三百年，朝事幾翻覆。","攙搶如云勃，鯨鯢旋自曝。","倦闻金鼎移，驟覩靈龟卜。","吁嗟王氣尽，坐悲天運倏。","天道何茫茫，善淫乃相复。","行路偏衣半，遂亡大梁族。","日隐汀洲上，登艫𦪇川陸。","月迴吳山樹，风闻楚江鵠。","因依蘭蕙藂，採擷不盈掬。"]', '诗', 'shi', '', NULL, '金陵懷古 唐堯臣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6c3b55-ffa4-4f74-97b4-3acf36502034', '詠浮漚爲辛明府作', '詠浮漚爲辛明府作', 'd85c3f29-9d51-4ab3-8eee-e5c79baf251c', '唐', '["行潦散輕漚，清規吐未收。","雨來波際合，風起浪中浮。","晶晃明苔砌，參差繞芥舟。","影疑星泛曉，光似露涵秋。","皎皎珠同淨，漂漂梗共流。","潔容無變染，圓知有謙柔。","欲作微涓效，先從淡水游。"]', '["行潦散轻漚，清規吐未收。","雨来波際合，风起浪中浮。","晶晃明苔砌，參差繞芥舟。","影疑星泛晓，光似露涵秋。","皎皎珠同淨，漂漂梗共流。","潔容無变染，圓知有謙柔。","欲作微涓效，先從淡水游。"]', '诗', 'shi', '', NULL, '詠浮漚爲辛明府作 鄭縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20797ea1-e498-43a1-88db-e913d48b7fed', '鶯', '鶯', 'd85c3f29-9d51-4ab3-8eee-e5c79baf251c', '唐', '["欲囀聲猶澀，將飛羽未調。","高風不借便，何處得遷喬。"]', '["欲囀声猶澀，將飞羽未調。","高风不借便，何处得遷喬。"]', '诗', 'shi', '', NULL, '鶯 鄭縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16db7fcc-3f65-46cb-bcf9-85f63bb1f694', '鸚鵡', '鸚鵡', 'b956d3f3-139f-4b79-9033-810482f9c06f', '唐', '["莫把金籠閉鸚鵡，箇箇聰明解人語。","忽然更向君前言，三十六宮愁幾許。"]', '["莫把金籠閉鸚鵡，箇箇聰明解人語。","忽然更向君前言，三十六宮愁幾許。"]', '诗', 'shi', '', NULL, '鸚鵡 吳英秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307c7884-0b30-4442-830c-081085bfc25d', '馬', '马', '5ee0dd6c-f3e9-4c56-a364-743e40bceea9', '唐', '["未明龍骨駿，幸得到神州。","自有千金價，寧忘伯樂酬。","雖知殊欵段，莫敢比驊騮。","若遇追風便，當軒一舉頭。"]', '["未明龙骨駿，幸得到神州。","自有千金價，寧忘伯乐酬。","雖知殊欵段，莫敢比驊騮。","若遇追风便，當軒一舉头。"]', '诗', 'shi', '', NULL, '馬 陳凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4da333-70ed-4782-8f92-db4cde0c760b', '鳳', '鳳', '03128eb6-28a2-4101-8e63-9836d3a9db04', '唐', '["好是山家鳳，歌成非楚雞。","毫光灑風雨，紋綵動雲霓。","竹實不得飽，桐孫何足栖。","岐陽今好去，律呂正淒淒。"]', '["好是山家鳳，歌成非楚雞。","毫光灑风雨，紋綵动云霓。","竹實不得飽，桐孫何足栖。","岐陽今好去，律呂正淒淒。"]', '诗', 'shi', '', NULL, '鳳 伊夢昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a2fae63-3b43-46c5-8df4-aba01b6c27bb', '送韋員外赴朔方', '送韋員外赴朔方', 'bb42e8ca-1282-4e5f-ae7e-7a1c6612cc5e', '唐', '["白露邊秋早，皇華戎事催。","已推仙省妙，更是幕中才。","出餞傾朝列，深功佇帝臺。","坐聞長策利，終見勒銘迴。"]', '["白露邊秋早，皇华戎事催。","已推仙省妙，更是幕中才。","出餞傾朝列，深功佇帝台。","坐闻长策利，終见勒銘迴。"]', '诗', 'shi', '', NULL, '送韋員外赴朔方 鄭嚴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db062845-57cf-4818-bc18-603c26ac64b0', '險竿行', '險竿行', '9af45f8f-77e3-465b-8b47-099c7689691e', '唐', '["山險驚摧輈，水險能覆舟。","奈何平地不肯立，走上百尺高竿頭。","我不知爾是人耶復猱耶？","使我爲爾長嘆嗟。","我聞孝子不許國，忠臣不愛家。","爾今輕命重黃金，忠孝兩虧徒爾誇。","始以險技悅君目，終以貪心媚君祿。","百尺高竿百度緣，一足參差一家哭。","險竿兒，聽我語，更有險徒險於汝。","重於權者失君恩，落向天涯海邊去。","險竿兒，爾須知，險途欲往爾可思。","上得不下下不得，我謂此輩險於險竿兒。"]', '["山險驚摧輈，水險能覆舟。","奈何平地不肯立，走上百尺高竿头。","我不知爾是人耶复猱耶？","使我爲爾长嘆嗟。","我闻孝子不許国，忠臣不愛家。","爾今轻命重黄金，忠孝兩虧徒爾誇。","始以險技悅君目，終以貪心媚君祿。","百尺高竿百度緣，一足參差一家哭。","險竿兒，听我語，更有險徒險於汝。","重於權者失君恩，落向天涯海邊去。","險竿兒，爾須知，險途欲往爾可思。","上得不下下不得，我謂此輩險於險竿兒。"]', '诗', 'shi', '', NULL, '險竿行 柳曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6232f4f5-94d3-4111-abad-c398fd80beb8', '琵琶行', '琵琶行', 'e3c1e626-445c-4eb5-9c54-ee8416a3dd3c', '唐', '["何人斸得一片木，三尺春冰五音足。","一彈決破真珠囊，迸落金盤聲斷續。","飄飄颻颻寒丁丁，蟲豸出蟄神鬼驚。","秋鴻叫侶代雲黑，猩猩夜啼蠻月明。","潏潏汩汩聲不定，胡雛學漢語未正。","若似長安月蝕時，滿城敲鼓聲噒噒。","青山飛起不壓物，野水流來欲濕人。","傷人憶得陳後主，春殿半酣細腰舞。","黃鶯百舌正相呼，玉樹後庭花帶雨。","二妃哭處山重重，二妃沒後雲溶溶。","夜深霜露鎖空廟，零落一叢斑竹風。","金谷園中草初綠，石崇一弄思歸曲。","當時二十四友人，手把金杯聽不足。","又似賈客蜀道間，千鐸萬磬鳴空山。","未若此調呦呦兮啁啁，嘈嘈兮啾啾。","引之於山，獸不能走。","吹之於水，魚不能游。","方知此藝不可有，人間萬事憑雙手。","若何爲我再三彈，送却花前一尊酒。"]', '["何人斸得一片木，三尺春冰五音足。","一彈決破真珠囊，迸落金盤声斷續。","飄飄颻颻寒丁丁，蟲豸出蟄神鬼驚。","秋鴻叫侶代云黑，猩猩夜啼蠻月明。","潏潏汩汩声不定，胡雛学漢語未正。","若似长安月蝕时，满城敲鼓声噒噒。","青山飞起不壓物，野水流来欲濕人。","傷人憶得陳後主，春殿半酣細腰舞。","黄鶯百舌正相呼，玉樹後庭花带雨。","二妃哭处山重重，二妃沒後云溶溶。","夜深霜露鎖空廟，零落一叢斑竹风。","金谷园中草初綠，石崇一弄思归曲。","當时二十四友人，手把金杯听不足。","又似賈客蜀道间，千鐸万磬鳴空山。","未若此調呦呦兮啁啁，嘈嘈兮啾啾。","引之於山，獸不能走。","吹之於水，鱼不能游。","方知此藝不可有，人间万事憑雙手。","若何爲我再三彈，送却花前一尊酒。"]', '诗', 'shi', '', NULL, '琵琶行 牛殳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964d490c-6ecf-4afe-b2a7-67ae8b2281ce', '方響歌', '方响歌', 'e3c1e626-445c-4eb5-9c54-ee8416a3dd3c', '唐', '["樂中何樂偏堪賞，無過夜深聽方響。","緩擊急擊曲未終，暴雨飄飄生坐上。","鏗鏗鐺鐺寒重重，盤渦蹙派鳴蛟龍。","高樓漏滴金壺水，碎電打著山寺鐘。","又似公卿入朝去，環珮鳴玉長街路。","忽然碎打入破聲，石崇推倒珊瑚樹。","長短參差十六片，敲擊宮商無不遍。","此樂不教外人聞，尋常只向堂前宴。"]', '["乐中何乐偏堪賞，無過夜深听方响。","緩擊急擊曲未終，暴雨飄飄生坐上。","鏗鏗鐺鐺寒重重，盤渦蹙派鳴蛟龙。","高楼漏滴金壺水，碎電打著山寺鐘。","又似公卿入朝去，环珮鳴玉长街路。","忽然碎打入破声，石崇推倒珊瑚樹。","长短參差十六片，敲擊宮商無不遍。","此乐不教外人闻，尋常只向堂前宴。"]', '诗', 'shi', '', NULL, '方響歌 牛殳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9dc3433-27c0-439c-bc86-d2de245f1628', '經太華', '經太华', '2d6c8690-035d-4b21-9a56-ae17cde7b641', '唐', '["太華五千尋，重嵒合沓起。","勢飛白雲外，影倒黃河裏。","上有千蓮葉，服之久不死。","山高採難得，歎息徒仰止。"]', '["太华五千尋，重嵒合沓起。","勢飞白云外，影倒黄河裏。","上有千蓮葉，服之久不死。","山高採难得，歎息徒仰止。"]', '诗', 'shi', '', NULL, '經太華 衛光一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('236688b7-72dc-4ceb-975c-8a8d590a0b1e', '季夏入北山', '季夏入北山', '91187514-1b0c-4e2f-9889-e330f4446b20', '唐', '["整駕俟明發，逶迤歷險途。","天形逼峰盡，地勢入谿無。","樹繞圓潭密，雲橫疊障孤。","誰憐後時者，六月未南圖。"]', '["整駕俟明發，逶迤歷險途。","天形逼峰尽，地勢入谿無。","樹繞圓潭密，云橫叠障孤。","誰怜後时者，六月未南圖。"]', '诗', 'shi', '', NULL, '季夏入北山 林璠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89d9747-8682-45a1-b213-f0e937ab90b2', '適思', '適思', 'd00ac319-c4ce-453a-8f4c-51b8946314a1', '唐', '["芳歲不我與，颯然涼風生。","繁華掃地歇，蟋蟀充堂鳴。","感物增憂思，奮衣出遊行。","行值古墓林，白骨下縱橫。","田豎鞭髑髏，村童掃精靈。","精靈無奈何，像設安所榮。","石人徒瞑目，表柱燒無聲。","試讀碑上文，乃是昔時英。","位極君詔葬，勳高盈忠貞。","寵終禁樵採，立嗣修墳塋。","運否前政缺，羣盜多蚊䖟。","即此丘壠壞，鐵心爲霑纓。","當其崇樹日，豈意侵奪併。","冥漠生變故，淒涼結幽明。","悲端豈自我，外物紛相縈。","所適非所見，前登江上城。","倚樓臨綠水，一望解傷情。"]', '["芳歲不我與，颯然涼风生。","繁华掃地歇，蟋蟀充堂鳴。","感物增憂思，奮衣出游行。","行值古墓林，白骨下縱橫。","田豎鞭髑髏，村童掃精靈。","精靈無奈何，像設安所榮。","石人徒瞑目，表柱燒無声。","試读碑上文，乃是昔时英。","位極君詔葬，勳高盈忠貞。","寵終禁樵採，立嗣修墳塋。","運否前政缺，羣盜多蚊䖟。","即此丘壠壞，鐵心爲霑纓。","當其崇樹日，豈意侵奪併。","冥漠生变故，淒涼結幽明。","悲端豈自我，外物紛相縈。","所適非所见，前登江上城。","倚楼臨綠水，一望解傷情。"]', '诗', 'shi', '', NULL, '適思 顏胄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3184ca5-f7a3-45fb-b93a-f419915ba9f2', '古意', '古意', '9f2fe962-c75e-4bca-a1d5-567e1c0e681d', '唐', '["家中酒新熟，園裏葉初榮。","佇杯欲取醉，悒然思友生。","忽聞有奇客，何姓復何名。","嗜酒陶彭澤，能琴阮步兵。","何須問寒暑，徑共坐山亭。","舉袂祛啼鳥，揚巾掃落英。","心神無俗累，歌詠有新聲。","新聲是何曲，滄浪之水清。"]', '["家中酒新熟，园裏葉初榮。","佇杯欲取醉，悒然思友生。","忽闻有奇客，何姓复何名。","嗜酒陶彭澤，能琴阮步兵。","何須问寒暑，徑共坐山亭。","舉袂祛啼鸟，揚巾掃落英。","心神無俗累，歌詠有新声。","新声是何曲，滄浪之水清。"]', '诗', 'shi', '', NULL, '古意 邢象玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aee47902-bd67-4fa5-ad94-7bb246a7a305', '採蓮曲', '採蓮曲', 'bcbf5186-32fb-4747-9930-270117492690', '唐', '["遊女泛江晴，蓮紅水復清。","競多愁日暮，爭疾畏船傾。","波動疑釵落，風生覺袖輕。","相看未盡意，歸浦櫂歌聲。"]', '["游女泛江晴，蓮紅水复清。","競多愁日暮，爭疾畏船傾。","波动疑釵落，风生覺袖轻。","相看未尽意，归浦櫂歌声。"]', '诗', 'shi', '', NULL, '採蓮曲 張敬徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695fe028-91f4-4e6a-9fac-4c989146d3a1', '采蓮', '采蓮', '071d9972-304a-42b9-84ad-ad92e2859cbe', '唐', '["越豔荆姝慣采蓮，蘭橈畫檝滿長川。","秋來江水澄如練，映水紅妝如可見。","此時蓮浦珠翠光，此日荷風羅綺香。","纖手周遊不暫息，紅英爛熳殊未極。","夕鳥棲林人欲稀，長歌哀怨采蓮歸。"]', '["越豔荆姝慣采蓮，蘭橈畫檝满长川。","秋来江水澄如練，映水紅妝如可见。","此时蓮浦珠翠光，此日荷风羅綺香。","纖手周游不暫息，紅英爛熳殊未極。","夕鸟棲林人欲稀，长歌哀怨采蓮归。"]', '诗', 'shi', '', NULL, '采蓮 徐玄之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb1ebdf-1ca2-4548-8037-55b5ac7153b6', '同崔員外溫泉宮即事', '同崔員外溫泉宮即事', '6f17c30a-ea53-4372-bdf5-bbc91a5b4549', '唐', '["輦輅移雙闕，宸遊整六師。","天迴紫微座，日轉羽林旗。","雷氣寒戈戟，軍容壯武貔。","弓鳴射雁處，泉暖躍龍時。","惠化成觀俗，謳謠入賦詩。","同歡王道盛，相與詠雍熙。"]', '["輦輅移雙闕，宸游整六師。","天迴紫微座，日轉羽林旗。","雷氣寒戈戟，軍容壯武貔。","弓鳴射雁处，泉暖躍龙时。","惠化成观俗，謳謠入賦诗。","同歡王道盛，相與詠雍熙。"]', '诗', 'shi', '', NULL, '同崔員外溫泉宮即事 郭汭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac3d0a2-fb47-4283-a056-9e05a5bb9c1a', '題沈黎城', '題沈黎城', '4b44d626-c84f-4b4a-bd78-ff5ed2504521', '唐', '["蘇子臥北海，馬翁渡南洲。","迹恨事乃立，功達名遂休。","夜聞羽書至，召募此邊州。","鐵騎燿楚甲，玉匣橫吳鉤。","雪厚羣山凍，蓬飛荒塞秋。","久戍曷辭苦，數戰期封侯。","不學豎儒輩，談經空白頭。"]', '["蘇子臥北海，马翁渡南洲。","迹恨事乃立，功達名遂休。","夜闻羽书至，召募此邊州。","鐵騎燿楚甲，玉匣橫吳鉤。","雪厚羣山凍，蓬飞荒塞秋。","久戍曷辞苦，數戰期封侯。","不学豎儒輩，談經空白头。"]', '诗', 'shi', '', NULL, '題沈黎城 權徹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d46ef2-27de-44aa-b03c-e9229bdd5937', '登樂遊原懷古', '登乐游原懷古', 'a1d7f7a6-f769-4278-a01d-29343a142e6c', '唐', '["緬惟漢宣帝，初謂皇曾孫。","雖在襁褓中，亦遭巫蠱冤。","至哉丙廷尉，感激義彌敦。","馳逐蓮勺道，出入諸陵門。","一朝風雲會，竟登天位尊。","握符升寶曆，負扆御華軒。","赫奕文物備，葳蕤休瑞繁。","卒爲中興主，垂名於後昆。","雄圖奄已謝，餘址空復存。","昔爲樂遊苑，今爲狐兔園。","朝見牧豎集，夕聞棲鳥喧。","蕭條灞亭岸，寂寞杜陵原。","羃䍥野煙起，蒼茫嵐氣昏。","二曜屢迴薄，四時更涼溫。","天道尚如此，人理安可論。"]', '["緬惟漢宣帝，初謂皇曾孫。","雖在襁褓中，亦遭巫蠱冤。","至哉丙廷尉，感激義彌敦。","驰逐蓮勺道，出入諸陵门。","一朝风云會，竟登天位尊。","握符升寶曆，負扆御华軒。","赫奕文物備，葳蕤休瑞繁。","卒爲中兴主，垂名於後昆。","雄圖奄已謝，餘址空复存。","昔爲乐游苑，今爲狐兔园。","朝见牧豎集，夕闻棲鸟喧。","蕭條灞亭岸，寂寞杜陵原。","羃䍥野煙起，蒼茫嵐氣昏。","二曜屢迴薄，四时更涼溫。","天道尚如此，人理安可論。"]', '诗', 'shi', '', NULL, '登樂遊原懷古 豆盧回 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5565ad-3603-4539-a43e-a3b8d6b31aed', '靜女歌', '静女歌', '84a98eba-91e7-4d9a-918b-6c3ee3ce0438', '唐', '["靜女樂於靜，動合古人則。","妙年工詩書，弱歲勤組織。","端居愁若癡，誰復理容色。","十五坐幽閨，四鄰不相識。","夭夭鄰家子，百花裝首餙。","日月淇上遊，笑人不踰閾。","河水自濁濟自清，仙臺蛾眉秦鏡明。","爲照齊王門下醜，何如漢帝掌中輕。"]', '["静女乐於静，动合古人則。","妙年工诗书，弱歲勤組织。","端居愁若癡，誰复理容色。","十五坐幽閨，四鄰不相識。","夭夭鄰家子，百花裝首餙。","日月淇上游，笑人不踰閾。","河水自濁濟自清，仙台蛾眉秦镜明。","爲照齊王门下醜，何如漢帝掌中轻。"]', '诗', 'shi', '', NULL, '靜女歌 張南容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae6a8e8-1f8a-4337-93cc-f2e23d4b126e', '古興二首 一', '古兴二首 一', '19459bdf-cb58-42f7-b8f3-2068ec13272f', '唐', '["蔓草自細微，女蘿始夭夭。","夤緣至百尺，榮耀非一朝。","敷色高碧嶺，流芳薄丹霄。","如何摧秀木，正爲餘波漂。","莖葉落巖跡，英蕤從風飆。","洪柯不足恃，況乃託陵苕。"]', '["蔓草自細微，女蘿始夭夭。","夤緣至百尺，榮耀非一朝。","敷色高碧嶺，流芳薄丹霄。","如何摧秀木，正爲餘波漂。","莖葉落巖跡，英蕤從风飆。","洪柯不足恃，況乃託陵苕。"]', '诗', 'shi', '', NULL, '古興二首 一 沈徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f90f5aa-0968-487d-b177-0be514cb6750', '古興二首 二', '古兴二首 二', '19459bdf-cb58-42f7-b8f3-2068ec13272f', '唐', '["長安富豪右，信是天下樞。","戚里笙歌發，禁門冠蓋趨。","攀雲無醜士，唾地盡成珠。","日晏下雙闕，煙花亂九衢。","恩榮在片言，零落亦須臾。","何意還自及，曲池今已蕪。"]', '["长安富豪右，信是天下樞。","戚里笙歌發，禁门冠蓋趨。","攀云無醜士，唾地尽成珠。","日晏下雙闕，煙花亂九衢。","恩榮在片言，零落亦須臾。","何意還自及，曲池今已蕪。"]', '诗', 'shi', '', NULL, '古興二首 二 沈徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024d7799-ac7c-4acb-b356-2971dd55bc42', '晚望', '晚望', '2d1005ba-ae56-4b3b-bc1f-8838a6d13f01', '唐', '["清晨孤亭裏，極目對前岑。","遠與天水合，長霞生夕林。","蒼然平楚意，杳靄半秋陰。","落日川上盡，關城雲外深。","方予事巖壑，及此欲抽簪。","詩就蓬山道，還茲契宿心。"]', '["清晨孤亭裏，極目对前岑。","远與天水合，长霞生夕林。","蒼然平楚意，杳靄半秋陰。","落日川上尽，关城云外深。","方予事巖壑，及此欲抽簪。","诗就蓬山道，還茲契宿心。"]', '诗', 'shi', '', NULL, '晚望 林琨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b584bd8d-c8ba-4c1f-9041-aa387849e116', '陽春歌', '陽春歌', '4d0ad111-c956-4e05-8d39-1c679e177b01', '唐', '["簾低曉露濕，簾捲鶯聲急。","欲起把箜篌，如凝綵弦澀。","孤眠愁不轉，點淚聲相及。","淨掃階上花，風來更吹入。"]', '["簾低晓露濕，簾捲鶯声急。","欲起把箜篌，如凝綵弦澀。","孤眠愁不轉，点泪声相及。","淨掃階上花，风来更吹入。"]', '诗', 'shi', '', NULL, '陽春歌 吳象之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f7b878-59d0-46a5-92a4-2ae713e2dfe7', '少年行', '少年行', '4d0ad111-c956-4e05-8d39-1c679e177b01', '唐', '["承恩借獵小平津，使氣常遊中貴人。","一擲千金渾是膽，家無四壁不知貧。"]', '["承恩借獵小平津，使氣常游中貴人。","一擲千金渾是膽，家無四壁不知貧。"]', '诗', 'shi', '', NULL, '少年行 吳象之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec53a259-f2a7-43b2-a254-eab08ad6dc44', '晚至鄉亭', '晚至乡亭', '3b2719bf-cc25-4d2e-ab72-5cce15bd4a4f', '唐', '["長亭日已暮，駐馬暫盤桓。","山川杳不極，徒侶默相看。","雲夕荆臺暗，風秋郢路寒。","客心一如此，誰復采芳蘭。"]', '["长亭日已暮，駐马暫盤桓。","山川杳不極，徒侶默相看。","云夕荆台暗，风秋郢路寒。","客心一如此，誰复采芳蘭。"]', '诗', 'shi', '', NULL, '晚至鄉亭 鄭德玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64bab1eb-a0a9-4555-9193-f59f730cf14d', '舟行旦發', '舟行旦發', 'c6a4e48c-80e6-4799-a4c9-17158aee5a6b', '唐', '["夜帆時未發，同侶暗相催。","山曉月初下，江鳴潮欲來。","稍分揚子岸，不辨越王臺。","自客水鄉裏，舟行知幾迴。"]', '["夜帆时未發，同侶暗相催。","山晓月初下，江鳴潮欲来。","稍分揚子岸，不辨越王台。","自客水乡裏，舟行知幾迴。"]', '诗', 'shi', '', NULL, '舟行旦發 張軫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f099a2b5-e9d1-4b4d-8487-592d3a33cdac', '奉和夏日遊山應制', '奉和夏日游山應制', 'f284e935-d721-4766-a2c7-690cf054cba5', '唐', '["首夏林壑清，薄暮煙霞上。","連巖聳百仞，絕壑臨千丈。","照灼晚花鮮，潺湲夕流聲。","悠然動睿思，息駕尋真賞。","掞彼渦川作，懷茲洛濱想。","竊吹等齊竽，何用承恩獎。"]', '["首夏林壑清，薄暮煙霞上。","連巖聳百仞，絕壑臨千丈。","照灼晚花鲜，潺湲夕流声。","悠然动睿思，息駕尋真賞。","掞彼渦川作，懷茲洛濱想。","竊吹等齊竽，何用承恩獎。"]', '诗', 'shi', '', NULL, '奉和夏日遊山應制 蔡文恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569a80c0-9309-40c8-ad66-9a41d3fcd404', '旅泊江津言懷', '旅泊江津言懷', 'abf4c147-4915-402e-85d8-adc7ac3c0ae1', '唐', '["征途幾迢遰，客子倦西東。","乘流如泛梗，逐吹似驚蓬。","飄颻萬里外，辛苦百年中。","異縣心期阻，他鄉風月同。","雲歸全嶺暗，日落半江紅。","自然堪迸淚，非是泣途窮。"]', '["征途幾迢遰，客子倦西东。","乘流如泛梗，逐吹似驚蓬。","飄颻万里外，辛苦百年中。","異縣心期阻，他乡风月同。","云归全嶺暗，日落半江紅。","自然堪迸泪，非是泣途窮。"]', '诗', 'shi', '', NULL, '旅泊江津言懷 賈宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cafced51-dc7d-4afa-9ee6-f0a6a1316328', '大梁行', '大梁行', 'c4fac64b-b72e-4b97-9086-0fee97bf889a', '唐', '["客有成都來，爲我彈鳴琴。","前彈別鶴操，後奏大梁吟。","大梁傷客情，荒臺對古城。","版築有陳跡，歌吹舞遺聲。","雄哉魏公子，疇日好羅英。","秀士三千人，煌煌列衆星。","金槌奪晉鄙，白刃刎侯嬴。","邯鄲救趙北，函谷走秦兵。","君子榮且昧，忠信莫之明。","間諜忽來及，雄圖靡克成。","千齡萬化盡，但見汴水清。","舊國多孤壘，夷門荆棘生。","蒼梧綵雲沒，湘浦綠池平。","聞有東山去，蕭蕭班馬鳴。","河洲搴宿莽，日夕淚霑纓。","因之唁公子，慷慨此歌行。"]', '["客有成都来，爲我彈鳴琴。","前彈別鹤操，後奏大梁吟。","大梁傷客情，荒台对古城。","版築有陳跡，歌吹舞遺声。","雄哉魏公子，疇日好羅英。","秀士三千人，煌煌列衆星。","金槌奪晉鄙，白刃刎侯嬴。","邯鄲救趙北，函谷走秦兵。","君子榮且昧，忠信莫之明。","间諜忽来及，雄圖靡克成。","千齡万化尽，但见汴水清。","旧国多孤壘，夷门荆棘生。","蒼梧綵云沒，湘浦綠池平。","闻有东山去，蕭蕭班马鳴。","河洲搴宿莽，日夕泪霑纓。","因之唁公子，慷慨此歌行。"]', '诗', 'shi', '', NULL, '大梁行 唐堯客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba4c978-518e-469b-b32e-50ca49a12a4d', '秋日送別', '秋日送別', 'de83c8da-f621-4dee-83cc-3b668fe1316d', '唐', '["荒郊古陌時時斷，野水浮雲處處秋。","唯有河邊衰柳樹，蟬聲相送到揚州。"]', '["荒郊古陌时时斷，野水浮云处处秋。","唯有河邊衰柳樹，蟬声相送到揚州。"]', '诗', 'shi', '', NULL, '秋日送別 朱晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe4ff37-0c30-4219-a48a-52df8169e0f6', '送人歸山', '送人归山', 'fde9f07c-ab91-477c-9739-5c498dab7d22', '唐', '["相逢唯道在，誰不共知貧。","歸路分殘雨，停舟別故人。","霜明松嶺曉，花暗竹房春。","亦有棲閑意，何年可寄身。"]', '["相逢唯道在，誰不共知貧。","归路分殘雨，停舟別故人。","霜明松嶺晓，花暗竹房春。","亦有棲闲意，何年可寄身。"]', '诗', 'shi', '', NULL, '送人歸山 石召 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4985a178-54f7-4000-b4c5-4ce5b2068ee0', '早行遇雪', '早行遇雪', 'fde9f07c-ab91-477c-9739-5c498dab7d22', '唐', '["荒郊昨夜雪，羸馬又須行。","四顧無人迹，雞鳴第一聲。"]', '["荒郊昨夜雪，羸马又須行。","四顧無人迹，雞鳴第一声。"]', '诗', 'shi', '', NULL, '早行遇雪 石召 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b4a897-bac7-4278-8e4d-523b7ec7e8f1', '送安養閻主簿還竹寺', '送安養閻主簿還竹寺', '92a85b63-eade-441e-b0f0-1ed7c0c269c2', '唐', '["分手怨河梁，南征歷漢陽。","江山追宋玉，雲雨夢襄王。","醉裏宜城近，歌中郢路長。","更尋棲枳處，猶是念仇香。"]', '["分手怨河梁，南征歷漢陽。","江山追宋玉，云雨梦襄王。","醉裏宜城近，歌中郢路长。","更尋棲枳处，猶是念仇香。"]', '诗', 'shi', '', NULL, '送安養閻主簿還竹寺 林珝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5edaba1-8b4a-4420-a7ae-eee6e8356765', '晚投南村', '晚投南村', 'f02e1654-76d9-47f2-bfe2-361318c06824', '唐', '["客行逢日暮，原野散秋暉。","南陌人初斷，西林鳥盡歸。","暗蓬沙上轉，寒葉月中飛。","村落無多在，聲聲近擣衣。"]', '["客行逢日暮，原野散秋暉。","南陌人初斷，西林鸟尽归。","暗蓬沙上轉，寒葉月中飞。","村落無多在，声声近擣衣。"]', '诗', 'shi', '', NULL, '晚投南村 衛葉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6524abb-984c-4f99-a2a1-ca0966b3dc7c', '題季子廟', '題季子廟', '311ad9a1-edc8-4b41-82c0-b506b1f268ef', '唐', '["季子讓社稷，又能聽國風。","寧知千載後，蘋藻冷祠宮。"]', '["季子讓社稷，又能听国风。","寧知千載後，蘋藻冷祠宮。"]', '诗', 'shi', '', NULL, '題季子廟 李季華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4790d81-875d-4e8a-af11-4ab1f2894735', '聽琴', '听琴', 'b262b6b1-b50c-4cb1-a614-2158418d6f58', '唐', '["拂塵開按匣，何事獨顰眉。","古調俗不樂，正聲君自知。"]', '["拂塵开按匣，何事独顰眉。","古調俗不乐，正声君自知。"]', '诗', 'shi', '', NULL, '聽琴 王玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba354c7-862a-44e8-b1d9-ae356d78754a', '失鷺鶿', '失鷺鶿', 'aaaeebf8-01d4-413d-a047-5a53e2df6bf3', '唐', '["惜養來來歲月深，籠開不見意沈吟。","也知祗在秋江上，明月蘆花何處尋。"]', '["惜養来来歲月深，籠开不见意沈吟。","也知祗在秋江上，明月蘆花何处尋。"]', '诗', 'shi', '', NULL, '失鷺鶿 李歸唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbe84d0-fc90-4d10-a085-f51ae7cf7159', '銅雀妓', '銅雀妓', '60fd2c42-848e-47a7-9cf6-ff0a5b96ea6e', '唐', '["魏王銅雀妓，日暮管弦清。","一見西陵樹，心悲舞不成。"]', '["魏王銅雀妓，日暮管弦清。","一见西陵樹，心悲舞不成。"]', '诗', 'shi', '', NULL, '銅雀妓 朱光弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2826eb-9d80-4b13-8182-ab08df506fe9', '宮詞', '宮词', '60fd2c42-848e-47a7-9cf6-ff0a5b96ea6e', '唐', '["夢裏君王近，宮中河漢高。","秋風能再熱，團扇不辭勞。"]', '["梦裏君王近，宮中河漢高。","秋风能再熱，團扇不辞勞。"]', '诗', 'shi', '', NULL, '宮詞 朱光弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d1c4fb-7ffc-4557-9c0e-cc9b7ec63b9d', '惆悵詩九首 一', '惆悵诗九首 一', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["魂黯黯兮情脈脈，簾風清兮窗月白。","夢驚枕上爐燼銷，不見蘂珠宮裏客。"]', '["魂黯黯兮情脈脈，簾风清兮窗月白。","梦驚枕上爐燼銷，不见蘂珠宮裏客。"]', '诗', 'shi', '', NULL, '惆悵詩九首 一 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df629a7-308c-45f7-9e1c-d9de57bbb85f', '惆悵詩九首 二', '惆悵诗九首 二', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["禁漏聲稀蟾魂冷，紗廚筠簟波光淨。","獨坐愁吟暗斷魂，滿窗風動芭蕉影。"]', '["禁漏声稀蟾魂冷，紗廚筠簟波光淨。","独坐愁吟暗斷魂，满窗风动芭蕉影。"]', '诗', 'shi', '', NULL, '惆悵詩九首 二 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ca18d4-068c-4fec-ae9a-a27b7882ccd0', '惆悵詩九首 三', '惆悵诗九首 三', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["別恨離腸空惻惻，風動虛軒池水白。","莫言靈圃步難尋，有心終效偷桃客。"]', '["別恨離腸空惻惻，风动虛軒池水白。","莫言靈圃步难尋，有心終效偷桃客。"]', '诗', 'shi', '', NULL, '惆悵詩九首 三 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f27757-a831-474c-b588-22561a4a3a51', '惆悵詩九首 四', '惆悵诗九首 四', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["秋遇人間好風景，焦桐韻滿華堂靜。","鑑鸞釵燕恨何窮，忍向銀牀空抱影。"]', '["秋遇人间好风景，焦桐韻满华堂静。","鑑鸾釵燕恨何窮，忍向銀牀空抱影。"]', '诗', 'shi', '', NULL, '惆悵詩九首 四 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c280f26-1606-4096-b8a7-ae35d2645a6b', '惆悵詩九首 五', '惆悵诗九首 五', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["綠槐影裏傍青樓，陌上行人空舉頭。","煙水露花無處問，搖鞭凝睇不勝愁。"]', '["綠槐影裏傍青楼，陌上行人空舉头。","煙水露花無处问，搖鞭凝睇不勝愁。"]', '诗', 'shi', '', NULL, '惆悵詩九首 五 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0076939-533d-488a-842e-a2e9b5799cc7', '惆悵詩九首 六', '惆悵诗九首 六', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["役盡心神銷盡骨，恩情未斷忽分離。","平生此恨無言處，只有衣襟淚得知。"]', '["役尽心神銷尽骨，恩情未斷忽分離。","平生此恨無言处，只有衣襟泪得知。"]', '诗', 'shi', '', NULL, '惆悵詩九首 六 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78101e80-4201-4736-a13c-cba8070534b8', '惆悵詩九首 七', '惆悵诗九首 七', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["濃醪豔唱愁難破，骨瘦魂消病已成。","若爲多羅年少死，始甘人道有風情。"]', '["濃醪豔唱愁难破，骨瘦魂消病已成。","若爲多羅年少死，始甘人道有风情。"]', '诗', 'shi', '', NULL, '惆悵詩九首 七 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de8f5a6-eb4a-455d-adc5-9676bce23c47', '惆悵詩九首 八', '惆悵诗九首 八', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["淚滿羅衣酒滿巵，一聲歌斷怨傷離。","如今兩地心中事，直是瞿曇也不知。"]', '["泪满羅衣酒满巵，一声歌斷怨傷離。","如今兩地心中事，直是瞿曇也不知。"]', '诗', 'shi', '', NULL, '惆悵詩九首 八 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6437c34-9a3d-4b3b-b540-37f4aa79f8e8', '惆悵詩九首 九', '惆悵诗九首 九', '6735fe98-9f3e-485d-9fbc-28570fc07bf7', '唐', '["橫泥杯觴醉復醒，愁牽時有小詩成。","早知惹得千般恨，悔不天生解薄情。"]', '["橫泥杯觴醉复醒，愁牽时有小诗成。","早知惹得千般恨，悔不天生解薄情。"]', '诗', 'shi', '', NULL, '惆悵詩九首 九 顧甄遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d5e324d-804a-492a-b9fb-aa7552eac045', '登清居臺', '登清居台', '610efbbc-16b5-4712-9d34-a4b7552e6438', '唐', '["迤邐清居臺，連延白雲外。","側聆天上語，下視飛鳥背。"]', '["迤邐清居台，連延白云外。","側聆天上語，下視飞鸟背。"]', '诗', 'shi', '', NULL, '登清居臺 魏巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231db098-b836-4d6f-be61-9af01afdd48e', '游昌化精舍', '游昌化精舍', '50325a2f-cebc-4a56-b74b-4c65245560eb', '唐', '["寶臺侵漢遠，金地接霞高。","何必遊天外，忻此契盧敖。"]', '["寶台侵漢远，金地接霞高。","何必游天外，忻此契盧敖。"]', '诗', 'shi', '', NULL, '游昌化精舍 柳明獻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb05cce-2d14-4415-b734-60647ef2eaa8', '善卷先生壇', '善卷先生壇', '8ef04c6d-cf27-4052-baee-39407441a442', '唐', '["幾到壇邊登閣望，因思遺跡詠今朝。","當時爲有重華出，不是先生傲帝堯。"]', '["幾到壇邊登閣望，因思遺跡詠今朝。","當时爲有重华出，不是先生傲帝堯。"]', '诗', 'shi', '', NULL, '善卷先生壇 蔡崑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a73857-b6d8-4a4d-9a6e-3f4158ef51a2', '句', '句', '8ef04c6d-cf27-4052-baee-39407441a442', '唐', '["飄飄隨暮雨，颯颯落秋山。"]', '["飄飄隨暮雨，颯颯落秋山。"]', '诗', 'shi', '', NULL, '句 蔡崑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f1f593-6365-46d8-a9b7-916ee86c0e90', '題鄜州相思鋪', '題鄜州相思鋪', '9417c439-f139-4036-95fa-2ab4ff1951c6', '唐', '["誰把相思號此河，塞垣車馬往來多。","只應自古征人淚，灑向空川作逝波。"]', '["誰把相思號此河，塞垣车马往来多。","只應自古征人泪，灑向空川作逝波。"]', '诗', 'shi', '', NULL, '題鄜州相思鋪 令狐挺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44759fb1-54f5-4277-88e2-906e1a6c94ac', '鳳歸雲二首 一', '鳳归云二首 一', '3a0ad6d9-6176-4bcc-a8f7-ddbaf56950ca', '唐', '["金井欄邊見羽儀，梧桐枝上宿寒枝。","五陵公子憐文彩，畫與佳人刺繡衣。"]', '["金井欄邊见羽儀，梧桐枝上宿寒枝。","五陵公子怜文彩，畫與佳人刺繡衣。"]', '诗', 'shi', '', NULL, '鳳歸雲二首 一 滕潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7501ed6-09a7-451e-8725-8519d1692a72', '鳳歸雲二首 二', '鳳归云二首 二', '3a0ad6d9-6176-4bcc-a8f7-ddbaf56950ca', '唐', '["飲啄蓬山最上頭，和煙飛下禁城秋。","曾將弄玉歸雲去，金翿斜開十二樓。"]', '["饮啄蓬山最上头，和煙飞下禁城秋。","曾將弄玉归云去，金翿斜开十二楼。"]', '诗', 'shi', '', NULL, '鳳歸雲二首 二 滕潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('416ba3ce-61fe-4665-bcd8-d5dcef069342', '藥圃', '藥圃', '1b6fb017-2971-42c4-9b06-27281061b9bf', '唐', '["綠葉紅英遍，僊經自討論。","偶移巖畔菊，鋤斷白雲根。"]', '["綠葉紅英遍，僊經自討論。","偶移巖畔菊，鋤斷白云根。"]', '诗', 'shi', '', NULL, '藥圃 夏侯子雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15fdd82-86cf-4656-ad17-254bcf5806a0', '讀孝經', '读孝經', 'b308681f-f5ab-4c59-bd1b-374db4c91ce3', '唐', '["星彩滿天朝北極，源流是處赴東溟。","爲臣爲子不忠孝，辜負宣尼一卷經。"]', '["星彩满天朝北極，源流是处赴东溟。","爲臣爲子不忠孝，辜負宣尼一卷經。"]', '诗', 'shi', '', NULL, '讀孝經 方愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d357ebc8-1e93-4c76-88f9-1a3547d5baec', '贈葛氏小娘子', '贈葛氏小娘子', '707c0cb3-8578-49db-95e0-40ad1f01021b', '唐', '["曾聞仙子住天台，欲結靈姻媿短才。","若許隨君洞中住，不同劉阮卻歸來。"]', '["曾闻仙子住天台，欲結靈姻媿短才。","若許隨君洞中住，不同劉阮卻归来。"]', '诗', 'shi', '', NULL, '贈葛氏小娘子 潘雍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67fa64fa-b2b7-48c0-bf26-565b9b1e53b3', '送孫舍人歸湘州', '送孫舍人归湘州', '05c540f3-612b-45c5-b8aa-b02c18f494ff', '唐', '["盛才傾世重，清論滿朝歸。","作隼他年計，爲鴛此日飛。","比肩移日近，抗首出郊畿。","爲報清漳水，分明照錦衣。"]', '["盛才傾世重，清論满朝归。","作隼他年計，爲鴛此日飞。","比肩移日近，抗首出郊畿。","爲報清漳水，分明照錦衣。"]', '诗', 'shi', '', NULL, '送孫舍人歸湘州 梁陟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7eece6b-5e73-4643-8b57-4eb825ea7fe4', '再登河陽城懷古', '再登河陽城懷古', '1a81a68a-fc6c-4330-b445-931ba6f7380f', '唐', '["客遊倦旅思，憩駕陟崇墉。","元凱標奇跡，安仁擅美蹤。","遠近濁河流，出沒青山峰。","佇想空不極，懷古悵無從。"]', '["客游倦旅思，憩駕陟崇墉。","元凱標奇跡，安仁擅美蹤。","远近濁河流，出沒青山峰。","佇想空不極，懷古悵無從。"]', '诗', 'shi', '', NULL, '再登河陽城懷古 朱延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f3f5f57-ae35-44bc-a3c5-eae1a86764a7', '題瑩上人院', '題瑩上人院', '550cd3fd-7472-4d8f-8041-7b892fcc787d', '唐', '["捨筏求香偈，因泉演妙音。","是明捐俗網，何獨在山林。","繚繞藤軒密，逶迤竹徑深。","爲傳同學志，茲宇可清心。"]', '["捨筏求香偈，因泉演妙音。","是明捐俗網，何独在山林。","繚繞藤軒密，逶迤竹徑深。","爲傳同学志，茲宇可清心。"]', '诗', 'shi', '', NULL, '題瑩上人院 寇埴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c747565-0818-4de3-b929-1faf9fcd9cc1', '燕啣泥', '燕啣泥', 'ba5a2bc0-304a-4ba4-a7a2-b498d724e97f', '唐', '["雙燕碌碌飛入屋，屋中老人喜燕歸，裴回繞我牀頭飛。","去年爲爾逐黃雀，雨多屋漏泥土落。","爾莫厭老翁茅屋低，梁頭作窠梁下棲。","爾不見東家黃𪅏鳴嘖嘖，虵盤瓦溝鼠穿壁。","豪家大屋爾莫居，驕兒少婦採爾雛。","井旁寫水泥自足，啣泥上屋隨爾欲。"]', '["雙燕碌碌飞入屋，屋中老人喜燕归，裴回繞我牀头飞。","去年爲爾逐黄雀，雨多屋漏泥土落。","爾莫厭老翁茅屋低，梁头作窠梁下棲。","爾不见东家黄𪅏鳴嘖嘖，虵盤瓦溝鼠穿壁。","豪家大屋爾莫居，驕兒少婦採爾雛。","井旁寫水泥自足，啣泥上屋隨爾欲。"]', '诗', 'shi', '', NULL, '燕啣泥 馮渚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fed232a-097f-43f8-9f53-7bed49602af0', '日暖萬年枝', '日暖万年枝', '80e6790a-5655-4744-ad17-58b03086a7c4', '唐', '["靄靄彤庭裏，沈沈玉砌陲。","初升九華日，潛暖萬年枝。","煦嫗光偏好，青葱色轉宜。","每因韶景麗，長沐惠風吹。","隱映當龍闕，氛氳隔鳳池。","朝陽光照處，唯有近臣知。"]', '["靄靄彤庭裏，沈沈玉砌陲。","初升九华日，潛暖万年枝。","煦嫗光偏好，青葱色轉宜。","每因韶景丽，长沐惠风吹。","隐映當龙闕，氛氳隔鳳池。","朝陽光照处，唯有近臣知。"]', '诗', 'shi', '', NULL, '日暖萬年枝 王約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a06f15f0-0c00-4503-86cb-66916821e0e0', '日暖萬年枝', '日暖万年枝', '8e3b626f-3d1a-4d88-87a0-308b369b414a', '唐', '["旭日升溟海，芳枝散曙煙。","溫仁臨樹久，煦嫗在條偏。","陽德符君惠，嘉名表聖年。","若承恩渥厚，常屬棟梁賢。","生植雖依地，光華只信天。","不才堪仄陋，徒望向榮先。"]', '["旭日升溟海，芳枝散曙煙。","溫仁臨樹久，煦嫗在條偏。","陽德符君惠，嘉名表聖年。","若承恩渥厚，常屬棟梁賢。","生植雖依地，光华只信天。","不才堪仄陋，徒望向榮先。"]', '诗', 'shi', '', NULL, '日暖萬年枝 郭求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af868c3a-69a9-425d-ba51-bfcea5bb6f44', '日暖萬年枝', '日暖万年枝', '41cbbbdd-1398-4cff-ad2a-a57c1927cb0a', '唐', '["禁樹敷榮早，偏將麗日宜。","光搖連北闕，影泛滿南枝。","得地方知照，逢時異赫曦。","葉和盈數積，根是永年移。","宵露猶殘潤，薰風更共吹。","餘暉誠可託，況近鳳凰池。"]', '["禁樹敷榮早，偏將丽日宜。","光搖連北闕，影泛满南枝。","得地方知照，逢时異赫曦。","葉和盈數積，根是永年移。","宵露猶殘潤，薰风更共吹。","餘暉誠可託，況近鳳凰池。"]', '诗', 'shi', '', NULL, '日暖萬年枝 鄭師貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218797a3-a043-49fd-bd48-c0340ca0ef48', '日華川上動', '日华川上动', 'fcbbb90f-78dd-468d-86a6-348664bde7ba', '唐', '["曙霞攢旭日，浮景弄晴川。","晃曜層潭上，悠揚極浦前。","岸高時擁媚，波遠漸澄鮮。","萍實空隨浪，珠胎不照淵。","早暄依曲渚，微動觸輕漣。","孰假咸池望，幽情得古篇。"]', '["曙霞攢旭日，浮景弄晴川。","晃曜層潭上，悠揚極浦前。","岸高时擁媚，波远漸澄鲜。","萍實空隨浪，珠胎不照淵。","早暄依曲渚，微动觸轻漣。","孰假咸池望，幽情得古篇。"]', '诗', 'shi', '', NULL, '日華川上動 石殷士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9df2ae-2597-482c-9f83-7d8f29503d58', '聞擊壤', '闻擊壤', 'fcbbb90f-78dd-468d-86a6-348664bde7ba', '唐', '["堯年聽野老，擊壤復何云。","自謂歡由己，寧知德在君。","氣平閑易暢，聲賀作難分。","耕鑿方隨日，恩威比望雲。","簣桴均下調，和木等南薰。","無落於吾事，誰將帝力聞。"]', '["堯年听野老，擊壤复何云。","自謂歡由己，寧知德在君。","氣平闲易暢，声賀作难分。","耕鑿方隨日，恩威比望云。","簣桴均下調，和木等南薰。","無落於吾事，誰將帝力闻。"]', '诗', 'shi', '', NULL, '聞擊壤 石殷士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e148e9-c58a-4492-aafc-7d1617f088cb', '初日照華清宮', '初日照华清宮', '085ea94b-6ae1-4548-994c-9b4407a685b5', '唐', '["靈山初照澤，遠近見離宮。","影動參差裏，光分縹緲中。","鮮飆收晚翠，佳氣滿晴空。","林潤溫泉入，樓深複道通。","璇題生烱晃，珠綴引𦝰朧。","鳳輦何時幸，朝朝此望同。"]', '["靈山初照澤，远近见離宮。","影动參差裏，光分縹緲中。","鲜飆收晚翠，佳氣满晴空。","林潤溫泉入，楼深複道通。","璇題生烱晃，珠綴引𦝰朧。","鳳輦何时幸，朝朝此望同。"]', '诗', 'shi', '', NULL, '初日照華清宮 柴宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('451339f4-5089-443c-a899-fcc85073519d', '瑜不掩瑕', '瑜不掩瑕', '085ea94b-6ae1-4548-994c-9b4407a685b5', '唐', '["朗玉微瑕在，分明異璞瑜。","堅貞寧可雜，美惡自能殊。","待價知彌久，稱忠定不誣。","光輝今見黜，毫髮外呈符。","豈假良工指，堪爲達士模。","他山儻磨琢，慕愛是洪鑪。"]', '["朗玉微瑕在，分明異璞瑜。","堅貞寧可杂，美惡自能殊。","待價知彌久，稱忠定不誣。","光輝今见黜，毫髮外呈符。","豈假良工指，堪爲達士模。","他山儻磨琢，慕愛是洪鑪。"]', '诗', 'shi', '', NULL, '瑜不掩瑕 柴宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c2e3ce4-3733-4d80-a046-ef515841595c', '秋日懸清光', '秋日懸清光', 'e8871c76-fb0c-4039-9ef8-3c06f8c649b9', '唐', '["秋至雲容歛，天中日景清。","懸空寒色淨，委照曙光盈。","泫泫看彌上，輝輝望最明。","烟霞輪乍透，葵藿影初生。","鑒下應無極，升高自有程。","何當迴盛彩，一爲表精誠。"]', '["秋至云容歛，天中日景清。","懸空寒色淨，委照曙光盈。","泫泫看彌上，輝輝望最明。","烟霞輪乍透，葵藿影初生。","鑒下應無極，升高自有程。","何當迴盛彩，一爲表精誠。"]', '诗', 'shi', '', NULL, '秋日懸清光 陶拱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3441db69-4620-4172-abb8-8fc971c8416e', '三讓月成魄', '三讓月成魄', '99e59ce6-2846-4f8a-8ebd-416c4c05b298', '唐', '["爲禮依天象，周旋逐月成。","教人三讓美，爲客一宵生。","初進輪猶暗，終辭影漸明。","幸陪賓主位，取捨任虧盈。"]', '["爲禮依天象，周旋逐月成。","教人三讓美，爲客一宵生。","初進輪猶暗，終辞影漸明。","幸陪賓主位，取捨任虧盈。"]', '诗', 'shi', '', NULL, '三讓月成魄 劉𤤺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ac2ba7-7fd5-4b3b-bfc1-80c305540538', '海上生明月', '海上生明月', 'df25c9b3-8793-4b87-bb11-a33a8dc55426', '唐', '["皎皎秋中月，團圓海上生。","影開金鏡滿，輪抱玉壺清。","漸出三山𡵒，將凌一漢橫。","素娥嘗藥去，烏鵲遶枝驚。","照水光偏白，浮雲色最明。","此時堯砌下，蓂莢自將榮。"]', '["皎皎秋中月，團圓海上生。","影开金镜满，輪抱玉壺清。","漸出三山𡵒，將凌一漢橫。","素娥嘗藥去，烏鵲遶枝驚。","照水光偏白，浮云色最明。","此时堯砌下，蓂莢自將榮。"]', '诗', 'shi', '', NULL, '海上生明月 朱華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04803420-1f5b-48f0-abba-2940006ba36b', '月夜梧桐葉上見寒露', '月夜梧桐葉上见寒露', '8c9b5045-6d29-431c-86c3-98ffb75f5009', '唐', '["蕭疎桐葉上，月白露初團。","滴瀝清光滿，熒煌素彩寒。","風搖愁玉墜，枝動惜珠乾。","氣冷疑秋晚，聲微覺夜闌。","凝空流欲遍，潤物淨宜看。","莫厭窺臨倦，將晞聚更難。"]', '["蕭疎桐葉上，月白露初團。","滴瀝清光满，熒煌素彩寒。","风搖愁玉墜，枝动惜珠乾。","氣冷疑秋晚，声微覺夜闌。","凝空流欲遍，潤物淨宜看。","莫厭窺臨倦，將晞聚更难。"]', '诗', 'shi', '', NULL, '月夜梧桐葉上見寒露 戴察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('647dd75f-1aac-421b-99d0-f2340cbd5f33', '清露被臯蘭', '清露被臯蘭', 'd36e4315-4cbd-415b-8244-2d00edd90a3b', '唐', '["九臯蘭葉茂，八月露華清。","稍與秋陰合，還將曉色幷。","向空羅細影，臨水泫微明。","的皪添幽興，芊綿動遠情。","夕芳人未採，初降鶴先驚。","爲感生成惠，心同葵藿傾。"]', '["九臯蘭葉茂，八月露华清。","稍與秋陰合，還將晓色幷。","向空羅細影，臨水泫微明。","的皪添幽兴，芊綿动远情。","夕芳人未採，初降鹤先驚。","爲感生成惠，心同葵藿傾。"]', '诗', 'shi', '', NULL, '清露被臯蘭 孫顧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1aee806-847b-4ece-aa92-d35007d6ed33', '宿煙含白露', '宿煙含白露', 'a922aa93-c5e1-4e3e-948f-7f5d91a6fa9c', '唐', '["㭊㭊有新意，微微曙色幽。","露含疎月淨，光與曉煙浮。","迥野遙凝素，空林望已秋。","著霜寒未結，凝葉滴還流。","比玉偏清潔，如珠詎可收。","裴回阡陌上，瞻想但淹留。"]', '["㭊㭊有新意，微微曙色幽。","露含疎月淨，光與晓煙浮。","迥野遙凝素，空林望已秋。","著霜寒未結，凝葉滴還流。","比玉偏清潔，如珠詎可收。","裴回阡陌上，瞻想但淹留。"]', '诗', 'shi', '', NULL, '宿煙含白露 孫頠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9d66ce-8f64-4e4d-8e55-db4ae6930a88', '送薛大夫和蕃', '送薛大夫和蕃', 'a922aa93-c5e1-4e3e-948f-7f5d91a6fa9c', '唐', '["亞相獨推賢，乘軺向遠邊。","一心傾漢日，萬里望胡天。","忠信皇恩重，要荒聖德傳。","戎人方屈膝，塞月復嬋娟。","別思流鶯晚，歸朝候雁先。","當書外垣傳，迴奏赤墀前。"]', '["亞相独推賢，乘軺向远邊。","一心傾漢日，万里望胡天。","忠信皇恩重，要荒聖德傳。","戎人方屈膝，塞月复嬋娟。","別思流鶯晚，归朝候雁先。","當书外垣傳，迴奏赤墀前。"]', '诗', 'shi', '', NULL, '送薛大夫和蕃 孫頠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e4a3b6-d543-4a9e-b882-3d549ea54129', '風光草際浮', '风光草際浮', '1783e40e-65dd-43be-aaf3-2443b92bf20a', '唐', '["春風泛搖草，旭日遍神州。","已向花間積，還來葉上浮。","曉光緣圃麗，芳氣滿街流。","澹蕩依朱萼，颻颺帶玉溝。","向空看轉媚，臨水見彌幽。","況被崇蘭色，王孫正可遊。"]', '["春风泛搖草，旭日遍神州。","已向花间積，還来葉上浮。","晓光緣圃丽，芳氣满街流。","澹蕩依朱萼，颻颺带玉溝。","向空看轉媚，臨水见彌幽。","況被崇蘭色，王孫正可游。"]', '诗', 'shi', '', NULL, '風光草際浮 陳璀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0a0a78-ea03-4019-95e2-b78bf56c6d5f', '風光草際浮', '风光草際浮', '0c817617-cde1-462a-9f80-29445418efcd', '唐', '["澹蕩和風至，芊綿碧草長。","徐吹遙撲翠，半偃乍浮光。","葉似翻宵露，藂疑扇夕陽。","逶迤明曲渚，照耀滿迴塘。","白芷生還暮，崇蘭泛更香。","誰知攬結處，含思向餘芳。"]', '["澹蕩和风至，芊綿碧草长。","徐吹遙撲翠，半偃乍浮光。","葉似翻宵露，藂疑扇夕陽。","逶迤明曲渚，照耀满迴塘。","白芷生還暮，崇蘭泛更香。","誰知攬結处，含思向餘芳。"]', '诗', 'shi', '', NULL, '風光草際浮 裴杞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af44a21-c183-4401-88cb-d0acc94e60cf', '風光草際浮', '风光草際浮', '912b1c46-56a9-4438-89c1-3eb6596d71fb', '唐', '["香發王孫草，春生君子風。","光搖低偃處，影散豔陽中。","稍稍移蘋末，微微轉蕙叢。","浮煙傾綠野，遠色澹晴空。","泛彩池塘媚，含芳景氣融。","清暉誰不挹，幾許賞心同。"]', '["香發王孫草，春生君子风。","光搖低偃处，影散豔陽中。","稍稍移蘋末，微微轉蕙叢。","浮煙傾綠野，远色澹晴空。","泛彩池塘媚，含芳景氣融。","清暉誰不挹，幾許賞心同。"]', '诗', 'shi', '', NULL, '風光草際浮 陳祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5b57f9a-e648-49e6-a9fb-8423b5b8d301', '風光草際浮', '风光草際浮', '481f132b-4dbe-410e-a1fd-ea43e8e46a3d', '唐', '["草色春沙裏，風光曉正幽。","輕明搖不散，郁昱麗仍浮。","吹緩苗難轉，暉閑葉本柔。","碧凝煙彩入，紅是日華流。","耐可披襟對，誰應滿掬收。","恭聞掇芳客，爲此尚淹留。"]', '["草色春沙裏，风光晓正幽。","轻明搖不散，郁昱丽仍浮。","吹緩苗难轉，暉闲葉本柔。","碧凝煙彩入，紅是日华流。","耐可披襟对，誰應满掬收。","恭闻掇芳客，爲此尚淹留。"]', '诗', 'shi', '', NULL, '風光草際浮 吳秘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06f033a-f2dd-4220-9183-23c72c3ce227', '風光草際浮', '风光草際浮', '147859af-f651-42c1-be56-4838c23e962c', '唐', '["纖纖春草長，遲日度風光。","靃靡含新彩，霏微籠遠芳。","殊姿媚原野，佳色滿池塘。","最好垂清露，偏宜帶豔陽。","淺深浮嫩綠，輕麗拂餘香。","好助鶯遷勢，乘時冀便翔。"]', '["纖纖春草长，遲日度风光。","靃靡含新彩，霏微籠远芳。","殊姿媚原野，佳色满池塘。","最好垂清露，偏宜带豔陽。","淺深浮嫩綠，轻丽拂餘香。","好助鶯遷勢，乘时冀便翔。"]', '诗', 'shi', '', NULL, '風光草際浮 張復元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91937ab-5cf5-44d3-9c14-5643edde669e', '冬至日祥風應候', '冬至日祥风應候', '43b7d504-5608-4fe5-bb7b-67b108408b42', '唐', '["節逢清景至，占氣二儀中。","獨喜登臺日，先知應候風。","呈祥光舜化，表慶感堯聰。","既與乘時叶，還將入律同。","微微萬井遍，習習九門通。","更繞鑪煙起，殷勤報歲功。"]', '["節逢清景至，占氣二儀中。","独喜登台日，先知應候风。","呈祥光舜化，表慶感堯聰。","既與乘时叶，還將入律同。","微微万井遍，習習九门通。","更繞鑪煙起，殷勤報歲功。"]', '诗', 'shi', '', NULL, '冬至日祥風應候 穆寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5faeeb2-dd13-4ee4-8fbf-2c5b6581fb41', '清風戒寒', '清风戒寒', '43b7d504-5608-4fe5-bb7b-67b108408b42', '唐', '["風清物候殘，蕭灑報將寒。","掃得天衢靜，吹來眼界寬。","條鳴方有異，蟲思亂無端。","就樹收鮮膩，衝池起澀瀾。","過山嵐可掬，度月色宜看。","華實從茲始，何嗟歲序殫。"]', '["风清物候殘，蕭灑報將寒。","掃得天衢静，吹来眼界寬。","條鳴方有異，蟲思亂無端。","就樹收鲜膩，衝池起澀瀾。","過山嵐可掬，度月色宜看。","华實從茲始，何嗟歲序殫。"]', '诗', 'shi', '', NULL, '清風戒寒 穆寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709a5417-c173-4053-a93d-c0b8b99c7728', '風草不留霜', '风草不留霜', '1a21bd50-f0c5-41b4-8b71-c0b0bc239762', '唐', '["繁霜當永夜，寒草正驚風。","飄素衰蘋末，流光晚蕙叢。","悠揚方泛影，皎潔却飛空。","不定離披際，難凝蘙薈中。","低昂閑散質，肅殺想成功。","獨感玄暉詠，依依此夕同。"]', '["繁霜當永夜，寒草正驚风。","飄素衰蘋末，流光晚蕙叢。","悠揚方泛影，皎潔却飞空。","不定離披際，难凝蘙薈中。","低昂闲散質，肅殺想成功。","独感玄暉詠，依依此夕同。"]', '诗', 'shi', '', NULL, '風草不留霜 王景中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e74089-f68a-4a49-bd30-cc095f5030c9', '春雲', '春云', 'c2259983-eb7b-4caa-9a6c-ea5dc6276198', '唐', '["搖曳自西東，依林又逐風。","勢移青道裏，影泛綠波中。","夕霽方明日，朝陽復蔽空。","度關隨去馬，出塞引歸鴻。","色任寒暄變，光將遠近同。","爲霖如見用，還得助成功。"]', '["搖曳自西东，依林又逐风。","勢移青道裏，影泛綠波中。","夕霽方明日，朝陽复蔽空。","度关隨去马，出塞引归鴻。","色任寒暄变，光將远近同。","爲霖如见用，還得助成功。"]', '诗', 'shi', '', NULL, '春雲 鄧倚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3075d8-babf-4491-8b39-ed06a0a9416f', '登雲梯', '登云梯', '27b26b12-a422-454a-9a68-404e35b98238', '唐', '["謝客常游處，層巒枕碧溪。","經過殊俗境，登陟象雲梯。","步步勞山屐，行行躡澗霓。","迥臨天路廣，俯眺夕陽低。","賞詠情彌愜，風塵事已暌。","前修如可慕，投足固思齊。"]', '["謝客常游处，層巒枕碧溪。","經過殊俗境，登陟象云梯。","步步勞山屐，行行躡澗霓。","迥臨天路廣，俯眺夕陽低。","賞詠情彌愜，风塵事已暌。","前修如可慕，投足固思齊。"]', '诗', 'shi', '', NULL, '登雲梯 湯洙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('827aca67-c59b-4bd8-aec4-920f427d649f', '登雲梯', '登云梯', '3c55f900-99f3-4b49-bd38-aee038b0887c', '唐', '["碧落遠澄澄，青山路可昇。","身輕疑易蹋，步獨覺難憑。","邐迤排將近，迴翔勢漸登。","上寧愁屈曲，高更喜超騰。","江樹遙分藹，山嵐宛若凝。","赤城容許到，敢憚百千層。"]', '["碧落远澄澄，青山路可昇。","身轻疑易蹋，步独覺难憑。","邐迤排將近，迴翔勢漸登。","上寧愁屈曲，高更喜超腾。","江樹遙分藹，山嵐宛若凝。","赤城容許到，敢憚百千層。"]', '诗', 'shi', '', NULL, '登雲梯 殷琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a310c412-bcc5-4642-b824-0728a95b8351', '秋山極天淨', '秋山極天淨', '41a1c624-2cca-41f7-86c8-1a073dc0b1b8', '唐', '["雨洗高秋淨，天臨大野閑。","葱蘢清萬象，繚繞出層山。","日落千峯上，雲銷萬壑間。","綠蘿霜後翠，紅葉雨來殷。","散彩輝吳甸，分形壓楚關。","欲尋霄漢路，延首願登攀。"]', '["雨洗高秋淨，天臨大野闲。","葱蘢清万象，繚繞出層山。","日落千峯上，云銷万壑间。","綠蘿霜後翠，紅葉雨来殷。","散彩輝吳甸，分形壓楚关。","欲尋霄漢路，延首願登攀。"]', '诗', 'shi', '', NULL, '秋山極天淨 朱延齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2288e93c-1406-41e2-8eb0-fa0f3087e452', '春臺晴望', '春台晴望', '6a328da8-8f20-44a4-a5db-234ca55eae7d', '唐', '["追賞層臺迥，登臨四望頻。","熙熙山雨霽，處處柳條新。","草長秦城夕，花明漢苑春。","晴林翻去鳥，紫陌閱行人。","旅客風塵厭，山家夢寐親。","遷鶯思出谷，鶱翥待芳辰。"]', '["追賞層台迥，登臨四望頻。","熙熙山雨霽，处处柳條新。","草长秦城夕，花明漢苑春。","晴林翻去鸟，紫陌閱行人。","旅客风塵厭，山家梦寐親。","遷鶯思出谷，鶱翥待芳辰。"]', '诗', 'shi', '', NULL, '春臺晴望 鄭蕡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfd7859a-5ccb-49be-bf58-fe4effbcd1dc', '天驥呈材', '天驥呈材', '6a328da8-8f20-44a4-a5db-234ca55eae7d', '唐', '["毛骨合天經，拳奇步驟輕。","曾邀于闐駕，新出貳師營。","噴勒金鈴響，追風汗血生。","酒亭留去跡，吳坂認嘶聲。","力可通衢試，材堪聖代呈。","王良如故盻，垂耳欲長鳴。"]', '["毛骨合天經，拳奇步驟轻。","曾邀于闐駕，新出貳師營。","噴勒金鈴响，追风汗血生。","酒亭留去跡，吳坂認嘶声。","力可通衢試，材堪聖代呈。","王良如故盻，垂耳欲长鳴。"]', '诗', 'shi', '', NULL, '天驥呈材 鄭蕡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d568ec12-6d9e-4acf-9b8c-ea8d4e353c20', '律中應鐘', '律中應鐘', 'a8e21f45-e3a8-4285-a4a9-69bc2682d6c6', '唐', '["律窮方數寸，室暗在三重。","伶管灰先動，秦正節已逢。","商聲辭玉笛，羽調入金鐘。","密葉翻霜彩，輕冰歛水容。","望鴻南去絕，迎氣北來濃。","願託無凋性，寒林自比松。"]', '["律窮方數寸，室暗在三重。","伶管灰先动，秦正節已逢。","商声辞玉笛，羽調入金鐘。","密葉翻霜彩，轻冰歛水容。","望鴻南去絕，迎氣北来濃。","願託無凋性，寒林自比松。"]', '诗', 'shi', '', NULL, '律中應鐘 裴元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27ad1ce-3f14-4970-b516-196ae4a2f2ee', '閏月定四時', '閏月定四时', '7ae6e49b-cb16-4f9d-ad45-84e17090fb05', '唐', '["得閏因貞歲，吾君敬授時。","體元承夏道，推曆法堯咨。","直取歸餘改，非如再失欺。","葭灰初變律，斗柄正當離。","寒暑功前定，春秋氣可推。","更憐幽谷羽，鳴躍尚須期。"]', '["得閏因貞歲，吾君敬授时。","體元承夏道，推曆法堯咨。","直取归餘改，非如再失欺。","葭灰初变律，斗柄正當離。","寒暑功前定，春秋氣可推。","更怜幽谷羽，鳴躍尚須期。"]', '诗', 'shi', '', NULL, '閏月定四時 杜周士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2daee0b2-9317-4643-ab56-a4b62452083e', '閏月定四時', '閏月定四时', '44d5f374-d8f8-40fe-a078-ef2cff6f69e0', '唐', '["聖代承堯曆，恆將閏正時。","六旬餘可借，四序應如期。","分至寧愆素，盈虛信不欺。","斗杓重指甲，灰琯再推離。","羲氏兼和氏，行之又則之。","願言符大化，永永作元龜。"]', '["聖代承堯曆，恆將閏正时。","六旬餘可借，四序應如期。","分至寧愆素，盈虛信不欺。","斗杓重指甲，灰琯再推離。","羲氏兼和氏，行之又則之。","願言符大化，永永作元龟。"]', '诗', 'shi', '', NULL, '閏月定四時 樂伸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce6f0cb6-e492-480e-a98b-2c3794970400', '閏月定四時', '閏月定四时', 'f48d7e4c-1705-43cd-9fb0-17b854a6723d', '唐', '["積數歸成閏，羲和職舊司。","分銖標斗建，盈縮正人時。","節候潛相應，星辰自合期。","寸陰寧越度，長曆信無欺。","定向銅壺辨，還從玉律推。","高明終不謬，委鑑本無私。"]', '["積數归成閏，羲和職旧司。","分銖標斗建，盈縮正人时。","節候潛相應，星辰自合期。","寸陰寧越度，长曆信無欺。","定向銅壺辨，還從玉律推。","高明終不謬，委鑑本無私。"]', '诗', 'shi', '', NULL, '閏月定四時 徐至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5880a5b-23eb-4480-94a5-9630a958dd3a', '新陽改故陰', '新陽改故陰', '12ca5c54-0888-46b2-9674-350be6aad1a6', '唐', '["律管才推候，寒郊忽變陰。","微和方應節，積慘已辭林。","暗覺餘澌斷，潛驚麗景侵。","禁城佳氣換，北陸翠煙深。","有截知遐布，無私荷照臨。","韶光如可及，鶯谷免幽沈。"]', '["律管才推候，寒郊忽变陰。","微和方應節，積慘已辞林。","暗覺餘澌斷，潛驚丽景侵。","禁城佳氣換，北陸翠煙深。","有截知遐布，無私荷照臨。","韶光如可及，鶯谷免幽沈。"]', '诗', 'shi', '', NULL, '新陽改故陰 紇干諷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('699277cd-b4fb-4601-926d-a973d9b363d1', '春水綠波', '春水綠波', 'b014ce3c-b5d9-4125-9f89-45e87fc18e26', '唐', '["芳時淑氣和，春水澹煙波。","滉瀁滋蘭杜，淪漣長芰荷。","晚光扶翠瀲，潭影寫青莎。","歸雁追飛盡，纖鱗遊泳多。","朝宗終到海，潤下每盈科。","願假中流便，從茲發櫂歌。"]', '["芳时淑氣和，春水澹煙波。","滉瀁滋蘭杜，淪漣长芰荷。","晚光扶翠瀲，潭影寫青莎。","归雁追飞尽，纖鱗游泳多。","朝宗終到海，潤下每盈科。","願假中流便，從茲發櫂歌。"]', '诗', 'shi', '', NULL, '春水綠波 朱休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fdeec9a-29f8-4c48-99cc-06bf1892071a', '海水不揚波', '海水不揚波', 'cc000d57-d24a-439d-b583-5ba2401c1a0c', '唐', '["明朝崇大道，寰海免波揚。","既合千年聖，能安百谷王。","天心隨澤廣，水德共靈長。","不撓魚彌樂，無瀾葦可航。","化流霑率土，恩浸及殊方。","豈只朝宗國，惟聞有越裳。"]', '["明朝崇大道，寰海免波揚。","既合千年聖，能安百谷王。","天心隨澤廣，水德共靈长。","不撓鱼彌乐，無瀾葦可航。","化流霑率土，恩浸及殊方。","豈只朝宗国，惟闻有越裳。"]', '诗', 'shi', '', NULL, '海水不揚波 李沛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79a8cdc5-efef-43d8-83aa-9278f6abc423', '四水合流', '四水合流', 'cc000d57-d24a-439d-b583-5ba2401c1a0c', '唐', '["禹鑿山川地，因通四水流。","縈迴過鳳闕，會合出皇州。","天影長波裏，寒聲古度頭。","入河無晝夜，歸海有謙柔。","順物宜投石，逢時可載舟。","羨魚猶未已，臨水欲垂鉤。"]', '["禹鑿山川地，因通四水流。","縈迴過鳳闕，會合出皇州。","天影长波裏，寒声古度头。","入河無晝夜，归海有謙柔。","順物宜投石，逢时可載舟。","羨鱼猶未已，臨水欲垂鉤。"]', '诗', 'shi', '', NULL, '四水合流 李沛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f623da90-5e65-4093-8c65-c482a78a90fb', '登聖善寺閣望龍門', '登聖善寺閣望龙门', 'f3509dd8-7cff-44fe-8863-9b2d8c79f56e', '唐', '["高閣聊登望，遙分禹鑿門。","剎連多寶塔，樹滿給孤園。","香境超三界，清流振陸渾。","報慈弘孝理，行道得真源。","空淨祥煙霽，時光受日溫。","願從初地起，長奉下生尊。"]', '["高閣聊登望，遙分禹鑿门。","剎連多寶塔，樹满給孤园。","香境超三界，清流振陸渾。","報慈弘孝理，行道得真源。","空淨祥煙霽，时光受日溫。","願從初地起，长奉下生尊。"]', '诗', 'shi', '', NULL, '登聖善寺閣望龍門 成㟧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab71b92-9e7a-4f5e-a952-7f2d8ef399c5', '秋霽望廬山瀑布', '秋霽望廬山瀑布', 'fb3da050-f254-415b-a381-d7e2c6c243d8', '唐', '["常思瀑布幽，晴晀喜逢秋。","一帶連青嶂，千尋倒碧流。","濕雲應悞鶴，飜浪定驚鷗。","星浦虹初下，爐峰煙未收。","巖高時褭褭，天淨起悠悠。","儻見朝宗日，還須濟巨舟。"]', '["常思瀑布幽，晴晀喜逢秋。","一带連青嶂，千尋倒碧流。","濕云應悞鹤，飜浪定驚鷗。","星浦虹初下，爐峰煙未收。","巖高时褭褭，天淨起悠悠。","儻见朝宗日，還須濟巨舟。"]', '诗', 'shi', '', NULL, '秋霽望廬山瀑布 夏侯楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5238376f-7c3c-4fdf-a496-3e9fd7254e7d', '濟川用舟檝', '濟川用舟檝', 'be0e647a-19ac-49a9-bb21-d380c1f38fb9', '唐', '["渺渺水連天，歸程想幾千。","孤舟辭曲岸，輕檝濟長川。","迥指波濤雪，迴瞻島嶼煙。","心迷滄海上，目斷白雲邊。","泛濫雖無定，維持且自專。","還如聖明代，理國用英賢。"]', '["渺渺水連天，归程想幾千。","孤舟辞曲岸，轻檝濟长川。","迥指波濤雪，迴瞻島嶼煙。","心迷滄海上，目斷白云邊。","泛濫雖無定，維持且自專。","還如聖明代，理国用英賢。"]', '诗', 'shi', '', NULL, '濟川用舟檝 胡權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159dfda2-df2e-427b-9a37-0ef3ea06da85', '洛出書', '洛出书', '435ad42c-b78b-4ee8-8bd9-76a11384ea4e', '唐', '["德合天貺呈，龍飛聖人作。","光宅被寰區，圖書薦河洛。","象登四氣順，文闢九疇錯。","氤氳瑞彩浮，左右靈儀廓。","微造功不宰，神行利攸博。","一見皇家慶，方知禹功薄。"]', '["德合天貺呈，龙飞聖人作。","光宅被寰區，圖书薦河洛。","象登四氣順，文闢九疇錯。","氤氳瑞彩浮，左右靈儀廓。","微造功不宰，神行利攸博。","一见皇家慶，方知禹功薄。"]', '诗', 'shi', '', NULL, '洛出書 郭邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('816b26fc-46d1-4670-8f02-8526f6cb3792', '洛出書', '洛出书', 'b9f7d05e-f5c9-4206-97d4-946dd2e680bb', '唐', '["浮空九洛水，瑞聖千年質。","奇象八卦分，圖書九疇出。","含微卜筮遠，抱數陰陽密。","中得天地心，傍探鬼神吉。","昔聞夏禹代，今獻唐堯日。","謬此敘彝倫，寰宇賀清謐。"]', '["浮空九洛水，瑞聖千年質。","奇象八卦分，圖书九疇出。","含微卜筮远，抱數陰陽密。","中得天地心，傍探鬼神吉。","昔闻夏禹代，今獻唐堯日。","謬此敘彝倫，寰宇賀清謐。"]', '诗', 'shi', '', NULL, '洛出書 張欽敬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0d5bc3-5d28-42fb-8ace-59ff9222840d', '洛出書', '洛出书', 'aaccd5a2-7d84-4780-9b43-de9d5784066c', '唐', '["清洛含溫溜，玄龜薦寶書。","波開綠字出，瑞應紫宸居。","物著羣靈首，文成列卦初。","美珍翔閣鳳，慶邁躍舟魚。","俾姒惟何遠，休皇復在諸。","東都主人意，歌頌望乘輿。"]', '["清洛含溫溜，玄龟薦寶书。","波开綠字出，瑞應紫宸居。","物著羣靈首，文成列卦初。","美珍翔閣鳳，慶邁躍舟鱼。","俾姒惟何远，休皇复在諸。","东都主人意，歌頌望乘輿。"]', '诗', 'shi', '', NULL, '洛出書 叔孫玄觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52846318-0a58-4595-b3df-a6c3b1a6fdf9', '玉壺冰', '玉壺冰', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["玉壺知素結，止水復中澄。","堅白能虛受，清寒得自凝。","分形同曉鏡，照物掩宵燈。","璧映圓光入，人驚爽氣凌。","金罍何足貴，瑤席幾回升。","正值求珪瓚，提攜共飲冰。"]', '["玉壺知素結，止水复中澄。","堅白能虛受，清寒得自凝。","分形同晓镜，照物掩宵灯。","璧映圓光入，人驚爽氣凌。","金罍何足貴，瑤席幾回升。","正值求珪瓚，提携共饮冰。"]', '诗', 'shi', '', NULL, '玉壺冰 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1bd1d7-792a-4bc0-b8ee-7c3cbf0e997c', '美玉', '美玉', '704fb768-a8ed-48d3-b011-45645658436d', '唐', '["抱玉將何適，良工正在斯。","有瑕寧自掩，匪石幸君知。","雕琢嗟成器，緇磷志不移。","飾罇光宴賞，入珮奉威儀。","象德曾留記，如虹竊可奇。","終希逢善價，還得桂林枝。"]', '["抱玉將何適，良工正在斯。","有瑕寧自掩，匪石幸君知。","雕琢嗟成器，緇磷志不移。","飾罇光宴賞，入珮奉威儀。","象德曾留記，如虹竊可奇。","終希逢善價，還得桂林枝。"]', '诗', 'shi', '', NULL, '美玉 南巨川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d21f515-a565-4c51-8ef2-703b1b7e7608', '琢玉', '琢玉', 'f65e0d3c-e1a5-4da3-a86a-ba8b890031ab', '唐', '["卞玉何時獻，初疑尚在荆。","琢來聞制器，價衒勝連城。","虹氣衝天白，雲浮入信貞。","珮爲廉節德，杯作侈奢名。","露璞方期辨，雕文幸既成。","他山豈無石，寧及此時呈。"]', '["卞玉何时獻，初疑尚在荆。","琢来闻制器，價衒勝連城。","虹氣衝天白，云浮入信貞。","珮爲廉節德，杯作侈奢名。","露璞方期辨，雕文幸既成。","他山豈無石，寧及此时呈。"]', '诗', 'shi', '', NULL, '琢玉 丁居晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47b8db0-c2d6-44c3-86bb-aeb57db2cbd2', '白珪無玷', '白珪無玷', 'f724d130-cecf-481b-bf0e-7fd5e097aa0a', '唐', '["片玉表堅貞，逢時寶自呈。","色鮮同雪白，光潤奪冰清。","皎皎無瑕玷，鏘鏘有珮聲。","崑山標重價，垂棘振香名。","抱璞心常苦，全真道未行。","琢磨忻大匠，還冀動連城。"]', '["片玉表堅貞，逢时寶自呈。","色鲜同雪白，光潤奪冰清。","皎皎無瑕玷，鏘鏘有珮声。","崑山標重價，垂棘振香名。","抱璞心常苦，全真道未行。","琢磨忻大匠，還冀动連城。"]', '诗', 'shi', '', NULL, '白珪無玷 辛宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1756a5ca-ccc8-4132-8b74-107f3f2a44d6', '鮫人潛織', '鮫人潛织', 'ff9bc08c-7439-4a52-85b0-7f4831c46682', '唐', '["珠館馮夷室，靈鮫信所潛。","幽閑雲碧牖，滉瀁水精簾。","機動龍梭躍，絲縈藕淬添。","七襄牛女恨，三日大人嫌。","透手擊吳練，凝冰笑越縑。","無因聽札札，空想濯纖纖。"]', '["珠館馮夷室，靈鮫信所潛。","幽闲云碧牖，滉瀁水精簾。","機动龙梭躍，絲縈藕淬添。","七襄牛女恨，三日大人嫌。","透手擊吳練，凝冰笑越縑。","無因听札札，空想濯纖纖。"]', '诗', 'shi', '', NULL, '鮫人潛織 康翊仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b06cda-b50c-4082-b840-589ec8df9b9c', '瑕瑜不相掩', '瑕瑜不相掩', 'e07d8e81-f6db-459f-8000-4add9c35da39', '唐', '["出石溫然玉，瑕瑜素在中。","妍媸因異彩，音韻信殊風。","讓美心方竝，求疵意本同。","光華開縝密，清潤仰磨礱。","秀質非攘善，貞姿肯廢忠。","今來儻成器，分別在良工。"]', '["出石溫然玉，瑕瑜素在中。","妍媸因異彩，音韻信殊风。","讓美心方竝，求疵意本同。","光华开縝密，清潤仰磨礱。","秀質非攘善，貞姿肯廢忠。","今来儻成器，分別在良工。"]', '诗', 'shi', '', NULL, '瑕瑜不相掩 陳中師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('845ae1dd-9719-47fe-8d9c-fd9ea02ee06b', '戛玉有餘聲', '戛玉有餘声', '482b480c-3b56-4db2-bd1e-c0adb4ddaa14', '唐', '["戛玉音難盡，凝人思轉清。","依稀流戶牖，髣髴在簷楹。","更逐松風起，還將澗水幷。","樂中和舊曲，天際轉餘聲。","漂渺浮煙遠，溫柔入耳輕。","想如君子佩，時得上堂鳴。"]', '["戛玉音难尽，凝人思轉清。","依稀流戶牖，髣髴在簷楹。","更逐松风起，還將澗水幷。","乐中和旧曲，天際轉餘声。","漂渺浮煙远，溫柔入耳轻。","想如君子佩，时得上堂鳴。"]', '诗', 'shi', '', NULL, '戛玉有餘聲 管雄甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb288d8-2f69-4c73-9be3-66d96f1555dc', '珠還合浦', '珠還合浦', '585222a1-579e-4fd1-ae81-a48876e1466c', '唐', '["至寶含沖粹，清虛映浦灣。","素輝明蕩漾，圓彩色玢㻞。","昔逐諸侯去，今隨太守還。","影搖波裏月，光動水中山。","魚目徒相比，驪龍乍可攀。","願將車飾用，長得耀君顏。"]', '["至寶含沖粹，清虛映浦灣。","素輝明蕩漾，圓彩色玢㻞。","昔逐諸侯去，今隨太守還。","影搖波裏月，光动水中山。","鱼目徒相比，驪龙乍可攀。","願將车飾用，长得耀君顏。"]', '诗', 'shi', '', NULL, '珠還合浦 鄧陟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee030f15-d143-4389-a74a-365493e254b7', '濁水求珠', '濁水求珠', '4b998fb8-61b9-4988-bd3f-e8e1d62adcdf', '唐', '["至寶誠難得，潛光在濁流。","深沈當處晦，皎潔庶來求。","綴履將還用，褰裳必更收。","蚌胎應自別，魚目豈能儔。","日彩逢高鑒，星光詎暗投。","不因今日取，泥滓出無由。"]', '["至寶誠难得，潛光在濁流。","深沈當处晦，皎潔庶来求。","綴履將還用，褰裳必更收。","蚌胎應自別，鱼目豈能儔。","日彩逢高鑒，星光詎暗投。","不因今日取，泥滓出無由。"]', '诗', 'shi', '', NULL, '濁水求珠 呂價 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e983c9f5-8294-4a13-a963-9ab6a6263690', '暗投明珠', '暗投明珠', 'dda6f00b-8a66-4628-8ce6-1c60268d1f5c', '唐', '["至寶欣懷日，良茲豈可儔。","神光非易鑒，夜色信難投。","錯落珍寰宇，圓明隔淺流。","精靈辭合浦，素彩耀神州。","抱影希人識，承時望帝求。","誰言按劒者，猜忌却生讐。"]', '["至寶欣懷日，良茲豈可儔。","神光非易鑒，夜色信难投。","錯落珍寰宇，圓明隔淺流。","精靈辞合浦，素彩耀神州。","抱影希人識，承时望帝求。","誰言按劒者，猜忌却生讐。"]', '诗', 'shi', '', NULL, '暗投明珠 苑䛆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d6657f-858d-4e9e-b239-b3f2c50fa265', '暗投明珠', '暗投明珠', '1e8c2d37-ca63-4c80-9e0f-e5279592f6f1', '唐', '["媚川時未識，在掌共傳名。","報德能欺暗，投人自欲明。","月臨幽室朗，星沒曉河傾。","的皪驪龍頷，熒煌彩鳳呈。","守恩辭合浦，擅美掩連城。","魚目應難近，誰知按劒情。"]', '["媚川时未識，在掌共傳名。","報德能欺暗，投人自欲明。","月臨幽室朗，星沒晓河傾。","的皪驪龙頷，熒煌彩鳳呈。","守恩辞合浦，擅美掩連城。","鱼目應难近，誰知按劒情。"]', '诗', 'shi', '', NULL, '暗投明珠 羅泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706fcbe2-210b-4051-bdb0-5a98d8f8bd9d', '暗投明珠', '暗投明珠', '3345bcf8-3f34-47c6-b998-52c9dc2b86f2', '唐', '["至寶看懷袖，明珠出後收。","向人光不定，離掌勢難留。","皎澈虛臨夜，孤圓冷瑩秋。","乍來驚月落，疾轉怕星流。","有淚甘瑕棄，無媒自暗投。","今朝感恩處，將欲報隋侯。"]', '["至寶看懷袖，明珠出後收。","向人光不定，離掌勢难留。","皎澈虛臨夜，孤圓冷瑩秋。","乍来驚月落，疾轉怕星流。","有泪甘瑕棄，無媒自暗投。","今朝感恩处，將欲報隋侯。"]', '诗', 'shi', '', NULL, '暗投明珠 崔藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280781cf-06b6-4862-84b2-9c6fc6ff16d7', '泗濱得石磬', '泗濱得石磬', 'a2ce0668-e124-4f84-b0a6-93328a9cd62b', '唐', '["浮磬潛清深，依依呈碧潯。","出水見貞質，在懸含玉音。","對此喜還歎，幾秋還到今。","器古契良覿，韻和諧宿心。","何爲值明鑒，適得離幽沈。","自茲入清廟，無復泥沙侵。"]', '["浮磬潛清深，依依呈碧潯。","出水见貞質，在懸含玉音。","对此喜還歎，幾秋還到今。","器古契良覿，韻和諧宿心。","何爲值明鑒，適得離幽沈。","自茲入清廟，無复泥沙侵。"]', '诗', 'shi', '', NULL, '泗濱得石磬 李勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c72130-515b-42be-8313-6b9dccadaf16', '玄元皇帝應見賀聖祚無疆', '玄元皇帝應见賀聖祚無疆', '3c622a10-1287-4dde-9f07-13cfaa0ec2c4', '唐', '["聖主今司契，神功格上玄。","豈唯求[傅]野，更有叶鈞天。","審夢西山下，焚香北闕前。","道光尊聖日，福應集靈年。","咫尺真容近，巍峩大象懸。","觴從百寮獻，形爲萬方傳。","聲教唯皇矣，英威固邈然。","慚無美周頌，徒上祝堯篇。"]', '["聖主今司契，神功格上玄。","豈唯求[傅]野，更有叶鈞天。","審梦西山下，焚香北闕前。","道光尊聖日，福應集靈年。","咫尺真容近，巍峩大象懸。","觴從百寮獻，形爲万方傳。","声教唯皇矣，英威固邈然。","慚無美周頌，徒上祝堯篇。"]', '诗', 'shi', '', NULL, '玄元皇帝應見賀聖祚無疆 趙鐸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee392d1d-7b31-400d-8ccd-fd7ee2e8a258', '太常寺觀舞聖壽樂', '太常寺观舞聖壽乐', 'c70aa7e6-1a65-4fda-9294-8154cc4d64b3', '唐', '["舞字傳新慶，人文邁舊章。","沖融和氣洽，悠遠聖功長。","盛德流無外，明時樂未央。","日華增顧眄，風物助低昂。","翥鳳方齊首，高鴻忽斷行。","雲門與茲曲，同是奉陶唐。"]', '["舞字傳新慶，人文邁旧章。","沖融和氣洽，悠远聖功长。","盛德流無外，明时乐未央。","日华增顧眄，风物助低昂。","翥鳳方齊首，高鴻忽斷行。","云门與茲曲，同是奉陶唐。"]', '诗', 'shi', '', NULL, '太常寺觀舞聖壽樂 徐元鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9069ce9-e769-4a7e-9d3f-49b344f90a54', '太清宮聞滴漏', '太清宮闻滴漏', 'cf7a693d-caa4-4402-916e-df48dbb4b7d3', '唐', '["玉漏移中禁，齊車入太清。","漸知催辨色，復聽續餘聲。","乍逐微風轉，時因雜珮輕。","青樓人罷夢，紫陌騎將行。","殘魄棲初盡，餘寒滴更生。","慚非朝謁客，空有振衣情。"]', '["玉漏移中禁，齊车入太清。","漸知催辨色，复听續餘声。","乍逐微风轉，时因杂珮轻。","青楼人罷梦，紫陌騎將行。","殘魄棲初尽，餘寒滴更生。","慚非朝謁客，空有振衣情。"]', '诗', 'shi', '', NULL, '太清宮聞滴漏 嚴巨川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cab6dab-3218-4ea4-9a4e-8303d0e99782', '仲秋太常寺觀公卿輅車拜陵', '仲秋太常寺观公卿輅车拜陵', 'cf7a693d-caa4-4402-916e-df48dbb4b7d3', '唐', '["南呂初開律，金風已戒涼。","拜陵將展敬，車輅儼成行。","士庶觀祠禮，公卿習舊章。","郊原佳氣引，園寢瑞煙長。","鹵簿辭丹闕，威儀列太常。","聖心何所寄，惟德在無忘。"]', '["南呂初开律，金风已戒涼。","拜陵將展敬，车輅儼成行。","士庶观祠禮，公卿習旧章。","郊原佳氣引，园寢瑞煙长。","鹵簿辞丹闕，威儀列太常。","聖心何所寄，惟德在無忘。"]', '诗', 'shi', '', NULL, '仲秋太常寺觀公卿輅車拜陵 嚴巨川 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba485e79-4621-40fd-89d8-7c33ca2aa7f1', '貢舉人謁先師聞雅樂', '貢舉人謁先師闻雅乐', '7e8034f9-3062-4096-9bc9-388086d3fbdf', '唐', '["禮聖來羣彥，觀光在此時。","聞歌音乍遠，合樂和還遲。","調朗能諧竹，聲微又契絲。","輕泠流簨簴，繚繞動纓緌。","九變將隨節，三終必盡儀。","國風由是正，王化自雍熙。"]', '["禮聖来羣彥，观光在此时。","闻歌音乍远，合乐和還遲。","調朗能諧竹，声微又契絲。","轻泠流簨簴，繚繞动纓緌。","九变將隨節，三終必尽儀。","国风由是正，王化自雍熙。"]', '诗', 'shi', '', NULL, '貢舉人謁先師聞雅樂 呂炅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3087bf-84cc-497d-918a-436f37cc31c0', '望凌煙閣', '望凌煙閣', '1e65951c-0852-4bb4-ae56-16d2ba25fe59', '唐', '["畫閣凌虛搆，遙瞻在九天。","丹楹崇壯麗，素壁繪勳賢。","靄靄浮元氣，亭亭出瑞煙。","近看分百辟，遠揖誤羣仙。","圖列青雲外，儀刑紫禁前。","望中空霽景，驤首幾留連。"]', '["畫閣凌虛搆，遙瞻在九天。","丹楹崇壯丽，素壁繪勳賢。","靄靄浮元氣，亭亭出瑞煙。","近看分百辟，远揖誤羣仙。","圖列青云外，儀刑紫禁前。","望中空霽景，驤首幾留連。"]', '诗', 'shi', '', NULL, '望凌煙閣 劉公興 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8fee4b-0706-4947-8b9e-f116eea3373f', '觀北番謁廟', '观北番謁廟', '5f49fed5-bd45-4294-a33d-75842dab2f4e', '唐', '["肅肅層城裏，巍巍祖廟清。","聖恩覃布濩，異域獻精誠。","冠蓋分行列，戎夷變姓名。","禮終齊百拜，心潔盡忠貞。","瑞氣千重色，簫韶九奏聲。","仗移迎日轉，斾動逐風輕。","休運威儀盛，豐年俎豆盈。","不堪慚頌德，空此望簪纓。"]', '["肅肅層城裏，巍巍祖廟清。","聖恩覃布濩，異域獻精誠。","冠蓋分行列，戎夷变姓名。","禮終齊百拜，心潔尽忠貞。","瑞氣千重色，簫韶九奏声。","仗移迎日轉，斾动逐风轻。","休運威儀盛，豐年俎豆盈。","不堪慚頌德，空此望簪纓。"]', '诗', 'shi', '', NULL, '觀北番謁廟 王卓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16dd0637-0bcc-4759-b064-776da70f2563', '舞干羽兩階', '舞干羽兩階', '06b7de36-fa48-45b6-b844-a849726c93c2', '唐', '["干羽能柔遠，前階舞正陳。","欲稱文德盛，先表樂聲新。","肅肅行初列，森森氣益振。","動容和律呂，變曲靜風塵。","化美超千古，恩波及七旬。","已知天下服，不獨有苗人。"]', '["干羽能柔远，前階舞正陳。","欲稱文德盛，先表乐声新。","肅肅行初列，森森氣益振。","动容和律呂，变曲静风塵。","化美超千古，恩波及七旬。","已知天下服，不独有苗人。"]', '诗', 'shi', '', NULL, '舞干羽兩階 石倚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d01852e-e3fa-416a-82ff-cff069998185', '御製段太尉碑', '御製段太尉碑', '9421c24f-f38d-4af2-ba5e-be93092635c4', '唐', '["多難全高節，時清軫聖君。","園塋標石篆，雨露降天文。","義激忠貞沒，詞傷蘭蕙焚。","國人皆墮淚，王府已銘勳。","揭出臨新陌，長留對古墳。","睿情幽感處，應使九泉聞。"]', '["多难全高節，时清軫聖君。","园塋標石篆，雨露降天文。","義激忠貞沒，词傷蘭蕙焚。","国人皆墮泪，王府已銘勳。","揭出臨新陌，长留对古墳。","睿情幽感处，應使九泉闻。"]', '诗', 'shi', '', NULL, '御製段太尉碑 葉元良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('373093db-3cd8-47a0-9b39-0aefcd2e7665', '恩賜魏文貞公諸孫舊第以導直臣', '恩賜魏文貞公諸孫旧第以導直臣', 'c85e17ba-5926-4620-9557-fd3911e17c3a', '唐', '["邢茅雖舊錫，邸第是初榮。","迹往傷遺事，恩深感直聲。","雲孫方慶襲，池館忽春生。","古甃開泉井，新禽繞畫楹。","自然垂帶礪，況復激忠貞。","必使千年後，長書竹帛名。"]', '["邢茅雖旧錫，邸第是初榮。","迹往傷遺事，恩深感直声。","云孫方慶襲，池館忽春生。","古甃开泉井，新禽繞畫楹。","自然垂带礪，況复激忠貞。","必使千年後，长书竹帛名。"]', '诗', 'shi', '', NULL, '恩賜魏文貞公諸孫舊第以導直臣 裴大章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ce82d0-8ae8-40ef-9d4e-6194323b8e0e', '恩賜耆老布帛', '恩賜耆老布帛', 'bad3b9f4-c418-466b-b539-d67fded5aa0d', '唐', '["渙汗中天發，殊私海外存。","衰顏逢聖代，華髮受皇恩。","燭物明堯日，垂衣闢禹門。","惜時悲落景，賜帛慰餘魂。","厚澤沾祥詠，微生保子孫。","盛明今尚齒，歡洽九衢罇。"]', '["渙汗中天發，殊私海外存。","衰顏逢聖代，华髮受皇恩。","燭物明堯日，垂衣闢禹门。","惜时悲落景，賜帛慰餘魂。","厚澤沾祥詠，微生保子孫。","盛明今尚齒，歡洽九衢罇。"]', '诗', 'shi', '', NULL, '恩賜耆老布帛 崔宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cbb0e31-91ab-4f39-bc03-2907b59ba12e', '東都父老望幸', '东都父老望幸', 'fe6c24ae-0d6c-40b4-883e-cdc69a730377', '唐', '["鑾輿秦地久，羽衛洛陽空。","彼土雖憑固，茲川乃得中。","龍顏覲白日，鶴髮仰清風。","望幸誠逾邈，懷來意不窮。","昔因封泰岳，今佇躡維嵩。","天地心無異，神祇理亦同。","翠華翔渭北，玉檢候關東。","衆願其難阻，明君早勒功。"]', '["鑾輿秦地久，羽衛洛陽空。","彼土雖憑固，茲川乃得中。","龙顏覲白日，鹤髮仰清风。","望幸誠逾邈，懷来意不窮。","昔因封泰岳，今佇躡維嵩。","天地心無異，神祇理亦同。","翠华翔渭北，玉檢候关东。","衆願其难阻，明君早勒功。"]', '诗', 'shi', '', NULL, '東都父老望幸 鄭馥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47c36bbc-9c5d-474e-a665-96380be371b7', '言行相顧', '言行相顧', 'cbcbe3a9-bdf1-467f-b14f-13709b1c9fb2', '唐', '["聖人垂政教，萬古請常傳。","立志言爲本，修身行乃先。","相須寧得闕，相顧在無偏。","榮辱當於己，忠貞必動天。","大名如副寶，至道亦通玄。","千里猶能應，何云邇者焉。"]', '["聖人垂政教，万古請常傳。","立志言爲本，修身行乃先。","相須寧得闕，相顧在無偏。","榮辱當於己，忠貞必动天。","大名如副寶，至道亦通玄。","千里猶能應，何云邇者焉。"]', '诗', 'shi', '', NULL, '言行相顧 吳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3c4291-c6ef-4103-9530-5451427b0910', '言行相顧', '言行相顧', '472d53c1-ce6e-49df-a84e-9a9aeaae12aa', '唐', '["將使言堪復，常聞行欲先。","比珪斯不玷，修己直如弦。","跬步非全進，吹噓稟自然。","當令夫子察，無宿仲由賢。","正遇興邦際，因懷入署年。","坐知清監下，相顧有人焉。"]', '["將使言堪复，常闻行欲先。","比珪斯不玷，修己直如弦。","跬步非全進，吹噓稟自然。","當令夫子察，無宿仲由賢。","正遇兴邦際，因懷入署年。","坐知清監下，相顧有人焉。"]', '诗', 'shi', '', NULL, '言行相顧 孟翺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11210021-3b5c-4722-92cf-f13791de36df', '人不易知', '人不易知', 'cc2efe42-aa6f-46ee-8f98-f78fc8e70c54', '唐', '["如面誠非一，深心豈易知。","入秦書十上，投楚歲三移。","和玉翻爲泣，齊竽或濫吹。","周行雖有寘，殷鑒在前規。","寅亮推多士，清通固賞奇。","病諸方號哲，敢相反成疵。","冬日承餘愛，霜雲喜暫披。","無令見瞻後，迴照復云疲。"]', '["如面誠非一，深心豈易知。","入秦书十上，投楚歲三移。","和玉翻爲泣，齊竽或濫吹。","周行雖有寘，殷鑒在前規。","寅亮推多士，清通固賞奇。","病諸方號哲，敢相反成疵。","冬日承餘愛，霜云喜暫披。","無令见瞻後，迴照复云疲。"]', '诗', 'shi', '', NULL, '人不易知 鄭昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695fd1e1-d269-47cc-b763-281bcca61505', '早春送郎官出宰', '早春送郎官出宰', '7d8632c1-ee9b-4a55-b417-56dc8d98b922', '唐', '["仙郎今出宰，聖主下憂民。","紫陌軒車送，丹墀雨露新。","趨程猶犯雪，行縣正逢春。","粉署時迴首，銅章已在身。","鳴琴化欲展，起草戀空頻。","今日都門外，悠悠別漢臣。"]', '["仙郎今出宰，聖主下憂民。","紫陌軒车送，丹墀雨露新。","趨程猶犯雪，行縣正逢春。","粉署时迴首，銅章已在身。","鳴琴化欲展，起草戀空頻。","今日都门外，悠悠別漢臣。"]', '诗', 'shi', '', NULL, '早春送郎官出宰 袁求賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5860e1df-75d6-4ffd-827f-2e41b9d12468', '餞王將軍赴雲中', '餞王將軍赴云中', '61feabcc-3bcf-49cd-9a9e-d02a9908584e', '唐', '["一師憑廟畧，分閫佐元戎。","勢亞彤弓寵，時推金印雄。","關山橫代北，旌節壯河東。","日轉前茅影，春生細柳風。","飲冰君命速，揮涕餞筵空。","佇聽陰山靜，誰爭萬里功。"]', '["一師憑廟畧，分閫佐元戎。","勢亞彤弓寵，时推金印雄。","关山橫代北，旌節壯河东。","日轉前茅影，春生細柳风。","饮冰君命速，揮涕餞筵空。","佇听陰山静，誰爭万里功。"]', '诗', 'shi', '', NULL, '餞王將軍赴雲中 孟匡明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bcc0e82-0463-4d75-b1ba-b433de5f0172', '西戎即敘', '西戎即敘', 'ddaa6743-ba86-49b2-9748-e3c2686c33bb', '唐', '["懸首藁街中，天兵破犬戎。","營收低隴月，旗偃度湟風。","肅殺三邊勁，蕭條萬里空。","元戎咸服罪，餘孽盡輸忠。","聖理符軒化，仁恩契禹功。","降逾洞庭險，梟擬郅支窮。","已散軍容捷，還資廟算通。","今朝觀即敘，非與獻獒同。"]', '["懸首藁街中，天兵破犬戎。","營收低隴月，旗偃度湟风。","肅殺三邊勁，蕭條万里空。","元戎咸服罪，餘孽尽輸忠。","聖理符軒化，仁恩契禹功。","降逾洞庭險，梟擬郅支窮。","已散軍容捷，還資廟算通。","今朝观即敘，非與獻獒同。"]', '诗', 'shi', '', NULL, '西戎即敘 李子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95be36d7-c16c-4180-bc4f-02a21d195c5e', '禁中春松', '禁中春松', '059414f2-e1e4-4ee3-a803-b40312933935', '唐', '["鬱鬱貞松樹，陰陰在紫宸。","蔥蘢偏近日，青翠更宜春。","雅韻風來起，輕煙霽後新。","葉深棲語鶴，枝亞拂朝臣。","全節長依地，凌雲欲致身。","山苗蔭不得，生植荷陶鈞。"]', '["鬱鬱貞松樹，陰陰在紫宸。","蔥蘢偏近日，青翠更宜春。","雅韻风来起，轻煙霽後新。","葉深棲語鹤，枝亞拂朝臣。","全節长依地，凌云欲致身。","山苗蔭不得，生植荷陶鈞。"]', '诗', 'shi', '', NULL, '禁中春松 員南溟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04543aec-e5d7-4f0d-9aab-12729628de8e', '玉燭', '玉燭', '059414f2-e1e4-4ee3-a803-b40312933935', '唐', '["曆象璿璣正，休徵玉燭明。","四時佳氣滿，五緯太階平。","律呂風光至，煙雲瑞色呈。","年和知歲稔，道泰喜秋成。","寰海皇恩被，乾坤至化清。","自憐同野老，帝力詎能名。"]', '["曆象璿璣正，休徵玉燭明。","四时佳氣满，五緯太階平。","律呂风光至，煙云瑞色呈。","年和知歲稔，道泰喜秋成。","寰海皇恩被，乾坤至化清。","自怜同野老，帝力詎能名。"]', '诗', 'shi', '', NULL, '玉燭 員南溟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe98dde4-a7a5-4654-94d9-6d7d964c473e', '文宣王廟古松', '文宣王廟古松', '9341cfbe-8868-47e1-884f-676bdde4f42e', '唐', '["列植成均裏，分行古廟前。","陰森非一日，蒼翠自何年。","寒影煙霜暗，晨光枝葉妍。","近簷陰更靜，臨砌色相鮮。","每愧聞鐘磬，多慚接豆籩。","更宜教胄子，於此學貞堅。"]', '["列植成均裏，分行古廟前。","陰森非一日，蒼翠自何年。","寒影煙霜暗，晨光枝葉妍。","近簷陰更静，臨砌色相鲜。","每愧闻鐘磬，多慚接豆籩。","更宜教胄子，於此学貞堅。"]', '诗', 'shi', '', NULL, '文宣王廟古松 李胄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41372553-e1d9-4f4e-ae73-99b636159134', '華林園早梅', '华林园早梅', '3e875611-4142-4d7f-ad18-69a8f166e2c0', '唐', '["曉日東樓路，林端見早梅。","獨凌寒氣發，不逐衆花開。","素彩風前豔，韶光雪後催。","蘂香霑紫陌，枝亞拂青苔。","止渴曾爲用，和羹舊有才。","含情欲攀折，瞻望幾裴回。"]', '["晓日东楼路，林端见早梅。","独凌寒氣發，不逐衆花开。","素彩风前豔，韶光雪後催。","蘂香霑紫陌，枝亞拂青苔。","止渴曾爲用，和羹旧有才。","含情欲攀折，瞻望幾裴回。"]', '诗', 'shi', '', NULL, '華林園早梅 鄭述誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd37ade-73a8-4c75-9c6b-8dbb4d973486', '龍池春草', '龙池春草', '4cee5a26-11c7-4eae-b3bc-485a8f0737dd', '唐', '["鳳闕韶光遍，龍池草色勻。","煙波全讓綠，堤柳不爭新。","翻葉迎紅日，飄香借白蘋。","幽姿偏占暮，芳意欲留春。","已勝生金埓，長思藉玉輪。","翠華如見幸，正好及茲辰。"]', '["鳳闕韶光遍，龙池草色勻。","煙波全讓綠，堤柳不爭新。","翻葉迎紅日，飄香借白蘋。","幽姿偏占暮，芳意欲留春。","已勝生金埓，长思藉玉輪。","翠华如见幸，正好及茲辰。"]', '诗', 'shi', '', NULL, '龍池春草 宋迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c774ffa-39b3-407d-8131-e5883dbf5d1b', '龍池春草', '龙池春草', 'd5aa102d-bd6f-45cf-a23d-347abaa994bc', '唐', '["暖積龍池綠，晴連御苑春。","迎風莖未偃，裛露色猶新。","苒苒分階砌，離離雜荇蘋。","細叢依遠渚，疎影落輕淪。","遲引縈花蝶，偏宜拾翠人。","那憐獻賦者，惆悵惜茲辰。"]', '["暖積龙池綠，晴連御苑春。","迎风莖未偃，裛露色猶新。","苒苒分階砌，離離杂荇蘋。","細叢依远渚，疎影落轻淪。","遲引縈花蝶，偏宜拾翠人。","那怜獻賦者，惆悵惜茲辰。"]', '诗', 'shi', '', NULL, '龍池春草 万俟造 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79aa98c9-e800-47ff-a9b7-1b993d2ae05b', '貢院樓北新栽小松', '貢院楼北新栽小松', '22e1be7c-4857-4c79-bf7c-ee708b6e6191', '唐', '["愛此凌霜操，移來獨占春。","貞心初得地，勁節始依人。","籠月煙猶薄，當軒色轉新。","枝低無宿羽，葉靜不留塵。","每與芝蘭近，常慙雨露均。","幸因逢顧盼，生植及茲辰。"]', '["愛此凌霜操，移来独占春。","貞心初得地，勁節始依人。","籠月煙猶薄，當軒色轉新。","枝低無宿羽，葉静不留塵。","每與芝蘭近，常慙雨露均。","幸因逢顧盼，生植及茲辰。"]', '诗', 'shi', '', NULL, '貢院樓北新栽小松 錢衆仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f97571bd-2817-4661-80f4-fb88f6ac0461', '玉壺冰', '玉壺冰', '22e1be7c-4857-4c79-bf7c-ee708b6e6191', '唐', '["冬律初陰結，寒冰貯玉壺。","霜姿雖異稟，虹氣亦相符。","對月光宜竝，臨池影不孤。","貞堅方共濟，同處豈殊途。","色瑩連城璧，形分照乘珠。","提攜今在此，抱素節寧渝。"]', '["冬律初陰結，寒冰貯玉壺。","霜姿雖異稟，虹氣亦相符。","对月光宜竝，臨池影不孤。","貞堅方共濟，同处豈殊途。","色瑩連城璧，形分照乘珠。","提携今在此，抱素節寧渝。"]', '诗', 'shi', '', NULL, '玉壺冰 錢衆仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2d7e4b-a065-4bda-8246-c9105fa92d7f', '潘安仁戴星看河陽花發', '潘安仁戴星看河陽花發', '8a61e772-3119-477f-b3dc-41ea21710b01', '唐', '["行春潘令至，勤恤戴星光。","爲政宵忘寢，臨人俗冀康。","曉花迎徑發，新蘂滿城香。","秀色霑輕露，鮮輝麗早陽。","津橋見來往，空霧拂衣裳。","桃李今無數，從茲願比方。"]', '["行春潘令至，勤恤戴星光。","爲政宵忘寢，臨人俗冀康。","晓花迎徑發，新蘂满城香。","秀色霑轻露，鲜輝丽早陽。","津橋见来往，空霧拂衣裳。","桃李今無數，從茲願比方。"]', '诗', 'shi', '', NULL, '潘安仁戴星看河陽花發 呂敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1547b022-a776-43d1-a0c5-9518849a4427', '龜茲聞鶯', '龟茲闻鶯', '8a61e772-3119-477f-b3dc-41ea21710b01', '唐', '["邊樹正參差，新鶯復陸離。","嬌非胡俗變，啼是漢音移。","繡羽花間覆，繁聲風外吹。","人言曾不辨，鳥語却相知。","出谷情何寄，遷喬義取斯。","今朝鄉陌伴，幾處坐高枝。"]', '["邊樹正參差，新鶯复陸離。","嬌非胡俗变，啼是漢音移。","繡羽花间覆，繁声风外吹。","人言曾不辨，鸟語却相知。","出谷情何寄，遷喬義取斯。","今朝乡陌伴，幾处坐高枝。"]', '诗', 'shi', '', NULL, '龜茲聞鶯 呂敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d09fe6-cc93-4368-a86e-f685324f6ff6', '好鳥鳴高枝', '好鸟鳴高枝', 'c28794ce-9d3c-4222-ba95-93b7622f7d4b', '唐', '["養翮非無待，遷喬信自卑。","影高遲日度，聲遠好風隨。","雲拂千尋直，花催百囀奇。","驚人時向晚，求友聽應知。","委質經三歲，先鳴在一枝。","上林如可托，弱羽願差池。"]', '["養翮非無待，遷喬信自卑。","影高遲日度，声远好风隨。","云拂千尋直，花催百囀奇。","驚人时向晚，求友听應知。","委質經三歲，先鳴在一枝。","上林如可托，弱羽願差池。"]', '诗', 'shi', '', NULL, '好鳥鳴高枝 鄭衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712eb10c-2b04-48b9-a948-c018e73811fc', '金谷園花發懷古', '金谷园花發懷古', '7e778858-19f5-489d-836d-dc1ac2bb0258', '唐', '["今日春風至，花開石氏園。","未全紅豔折，半與素光翻。","點綴疎林遍，微明古徑繁。","窺臨鶯欲語，寂寞李無言。","谷變迷鋪錦，臺餘認樹萱。","川流人事共，千載竟誰論。"]', '["今日春风至，花开石氏园。","未全紅豔折，半與素光翻。","点綴疎林遍，微明古徑繁。","窺臨鶯欲語，寂寞李無言。","谷变迷鋪錦，台餘認樹萱。","川流人事共，千載竟誰論。"]', '诗', 'shi', '', NULL, '金谷園花發懷古 張公乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e52d049b-48e6-4ef5-827c-d6f8ca1a9101', '織鳥', '织鸟', '34adcbff-62b4-49ab-8bfd-1efa10be0d52', '唐', '["季春三月裏，戴勝下桑來。","映日華冠動，迎風繡羽開。","候驚蠶事晚，織向女工裁。","旅宿依花定，輕飛遶樹迴。","欲過高閣柳，更拂小庭梅。","所寄一枝在，寧憂弋者猜。"]', '["季春三月裏，戴勝下桑来。","映日华冠动，迎风繡羽开。","候驚蠶事晚，织向女工裁。","旅宿依花定，轻飞遶樹迴。","欲過高閣柳，更拂小庭梅。","所寄一枝在，寧憂弋者猜。"]', '诗', 'shi', '', NULL, '織鳥 張何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36061c40-4244-414e-b100-5053aad3a53b', '出籠鶻', '出籠鶻', 'cb662bc2-79d5-461a-a48c-2b5b53b214e2', '唐', '["玉鏃分花袖，金鈴出綵籠。","搖心長捧日，逸翰鎮生風。","一點青霄裏，千聲碧落中。","星眸隨狡兔，霜爪落飛鴻。","每念提攜力，常懷搏擊功。","以君能惠好，不敢沒遙空。"]', '["玉鏃分花袖，金鈴出綵籠。","搖心长捧日，逸翰鎮生风。","一点青霄裏，千声碧落中。","星眸隨狡兔，霜爪落飞鴻。","每念提携力，常懷搏擊功。","以君能惠好，不敢沒遙空。"]', '诗', 'shi', '', NULL, '出籠鶻 濮陽瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269d9b2b-9585-49e6-a4cc-8df405285e73', '試越裳貢白雉', '試越裳貢白雉', '34ef975a-f108-4e51-a159-8d19391ed13a', '唐', '["素翟宛昭彰，遙遙自越裳。","冰晴朝映日，玉羽夜含霜。","歲月三年遠，山川九澤長。","來從碧海路，入見白雲鄉。","作瑞興周后，登歌美漢皇。","朝天資孝理，惠化且無疆。"]', '["素翟宛昭彰，遙遙自越裳。","冰晴朝映日，玉羽夜含霜。","歲月三年远，山川九澤长。","来從碧海路，入见白云乡。","作瑞兴周后，登歌美漢皇。","朝天資孝理，惠化且無疆。"]', '诗', 'shi', '', NULL, '試越裳貢白雉 王若嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42bcd2a-2b00-46e3-8e8a-e442618b1e73', '勅賜三相馬', '勅賜三相马', '2d49b036-38a9-458c-ad3a-6c5ba0c98bb1', '唐', '["上苑驊騮出，中宮詔命傳。","九天班錫禮，三相代勞年。","顧主聲猶發，追風力正全。","鳴珂龍闕下，噴玉鳳池前。","四足疑雲滅，雙瞳比鏡懸。","爲因能致遠，今日表求賢。"]', '["上苑驊騮出，中宮詔命傳。","九天班錫禮，三相代勞年。","顧主声猶發，追风力正全。","鳴珂龙闕下，噴玉鳳池前。","四足疑云滅，雙瞳比镜懸。","爲因能致远，今日表求賢。"]', '诗', 'shi', '', NULL, '勅賜三相馬 張隨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8193c82-c72c-4fee-a840-d962c43548a3', '河中獻捷', '河中獻捷', '2d49b036-38a9-458c-ad3a-6c5ba0c98bb1', '唐', '["叛將忘恩久，王師不戰通。","凱歌千里內，喜氣二儀中。","寇盡條山下，兵迴漢苑東。","將軍初執訊，明主欲論功。","落日煙塵靜，寒郊壁壘空。","蒼生幸無事，自此樂堯風。"]', '["叛將忘恩久，王師不戰通。","凱歌千里內，喜氣二儀中。","寇尽條山下，兵迴漢苑东。","將軍初執訊，明主欲論功。","落日煙塵静，寒郊壁壘空。","蒼生幸無事，自此乐堯风。"]', '诗', 'shi', '', NULL, '河中獻捷 張隨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ae46d8-db38-45fc-af5d-bf118af7bcbc', '天驥呈材', '天驥呈材', 'c9f02eee-8262-4cc3-9483-3456e1f52673', '唐', '["至德符天道，龍媒應聖明。","追風奇質異，噴玉彩毛輕。","躞蹀形難狀，連拳勢乍呈。","効材矜逸態，絕影表殊名。","岐路寧辭遠，關山豈憚行。","鹽車雖不駕，今日亦長鳴。"]', '["至德符天道，龙媒應聖明。","追风奇質異，噴玉彩毛轻。","躞蹀形难狀，連拳勢乍呈。","効材矜逸態，絕影表殊名。","岐路寧辞远，关山豈憚行。","鹽车雖不駕，今日亦长鳴。"]', '诗', 'shi', '', NULL, '天驥呈材 徐仁嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af30ac8-5dd8-43bf-bb26-53968e3f07e7', '天驥呈材', '天驥呈材', '4e002f7d-e635-466f-80be-b098f4c86a39', '唐', '["異產應堯年，龍媒順制牽。","權奇初得地，躞蹀欲行天。","詎假調金埒，寧須動玉鞭。","嘶風深有戀，逐日定無前。","周滿誇常馭，燕昭恨不傳。","應知流赭汗，來自海西偏。"]', '["異產應堯年，龙媒順制牽。","權奇初得地，躞蹀欲行天。","詎假調金埒，寧須动玉鞭。","嘶风深有戀，逐日定無前。","周满誇常馭，燕昭恨不傳。","應知流赭汗，来自海西偏。"]', '诗', 'shi', '', NULL, '天驥呈材 盧征 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee5acee-aed5-4f5e-a352-0c7e81c33cd4', '雲夜聽猨吟', '云夜听猨吟', 'aae97eb1-c190-430f-a8f8-57e860b73f92', '唐', '["寒巖飛暮雪，絕壁夜猨吟。","歷歷和羣雁，寥寥思客心。","繞枝猶避箭，過嶺却投林。","風冷聲偏苦，山寒響更深。","聽時無有定，靜裏固難尋。","一宿扶桑月，聊看懷好音。"]', '["寒巖飞暮雪，絕壁夜猨吟。","歷歷和羣雁，寥寥思客心。","繞枝猶避箭，過嶺却投林。","风冷声偏苦，山寒响更深。","听时無有定，静裏固难尋。","一宿扶桑月，聊看懷好音。"]', '诗', 'shi', '', NULL, '雲夜聽猨吟 顧偉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772cebf1-5025-4f38-9d1a-b7301d8b1fec', '寒蟬樹', '寒蟬樹', 'ebcf9afd-e160-4a43-b825-5f199196b43e', '唐', '["一葉初飛日，寒蟬益易驚。","入林慙織細，依樹媿身輕。","大幹時容息，喬枝或借鳴。","心由飲露靜，響爲逐風清。","忝有翩翾分，應憐嘒唳聲。","不知微薄影，早晚挂緌纓。"]', '["一葉初飞日，寒蟬益易驚。","入林慙织細，依樹媿身轻。","大幹时容息，喬枝或借鳴。","心由饮露静，响爲逐风清。","忝有翩翾分，應怜嘒唳声。","不知微薄影，早晚挂緌纓。"]', '诗', 'shi', '', NULL, '寒蟬樹 沈鵬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a87eb3ba-764c-4568-bf8f-710002b9e154', '臨川羨魚', '臨川羨鱼', '72487263-a050-4a4f-a37a-4acd2d563cf5', '唐', '["曾是歸家客，今年且未旋。","遊鱗方有待，織網豈能捐。","向水煙波夕，吟風歲月遷。","莓苔生古岸，葭菼變清川。","不逐滄波叟，還宗內外篇。","良辰難自擲，此日願忘筌。"]', '["曾是归家客，今年且未旋。","游鱗方有待，织網豈能捐。","向水煙波夕，吟风歲月遷。","莓苔生古岸，葭菼变清川。","不逐滄波叟，還宗內外篇。","良辰难自擲，此日願忘筌。"]', '诗', 'shi', '', NULL, '臨川羨魚 薛少殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf5c241-a413-40ac-a83e-bc5345fabbbc', '臨川羨魚', '臨川羨鱼', '42325a6e-4a78-4cac-bed5-e7717d040be1', '唐', '["有客百愁侵，求魚正在今。","廣川何渺漫，高岸幾登臨。","風水寧相阻，煙霞豈憚深。","不應同逐鹿，詎肯比從禽。","結網非無力，忘筌自有心。","永存芳餌在，佇立思沈沈。"]', '["有客百愁侵，求鱼正在今。","廣川何渺漫，高岸幾登臨。","风水寧相阻，煙霞豈憚深。","不應同逐鹿，詎肯比從禽。","結網非無力，忘筌自有心。","永存芳餌在，佇立思沈沈。"]', '诗', 'shi', '', NULL, '臨川羨魚 張元正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6331791-3b3b-49f0-a08e-90f43c1fec60', '荅王無功入長安詠秋蓬見示', '荅王無功入长安詠秋蓬见示', 'f5ab1dc8-81f7-44c8-89d8-536ddc19968f', '唐', '["托根雖異所，飄葉早相依。","因風若有便，更共入雲飛。"]', '["托根雖異所，飄葉早相依。","因风若有便，更共入云飞。"]', '诗', 'shi', '', NULL, '荅王無功入長安詠秋蓬見示 辛學士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b416ce8e-4855-4983-9856-0e7925285ca6', '哭李遠', '哭李远', '196c8adf-1a61-4665-8662-d65b8d17d402', '唐', '["昨日舟還浙水湄，今朝丹旐欲何爲。","纔收北浦一竿釣，未了西齋半局棊。","洛下已傳平子賦，臨川爭寫謝公詩。","不堪舊里經行處，風木蕭蕭鄰笛悲。"]', '["昨日舟還浙水湄，今朝丹旐欲何爲。","纔收北浦一竿釣，未了西斋半局棊。","洛下已傳平子賦，臨川爭寫謝公诗。","不堪旧里經行处，风木蕭蕭鄰笛悲。"]', '诗', 'shi', '', NULL, '哭李遠 盧尚書 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b2743f-7ccb-477e-aa67-ca75ad73f933', '湘中怨諷', '湘中怨諷', 'bd8872b9-fd68-4072-85c1-9e30075e7ad0', '唐', '["青鷁苦幽獨，隔江相對稀。","夜寒蘆葉雨，空作一聲歸。"]', '["青鷁苦幽独，隔江相对稀。","夜寒蘆葉雨，空作一声归。"]', '诗', 'shi', '', NULL, '湘中怨諷 鄭僕射 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da767889-3e56-488a-abb5-cf3c7a954ac8', '登汾上閣', '登汾上閣', '411dbe7f-9d0e-4453-8125-7818e8d60131', '唐', '["汾桂秋水闊，宛似到閶門。","惆悵江湖思，惟將南客論。"]', '["汾桂秋水闊，宛似到閶门。","惆悵江湖思，惟將南客論。"]', '诗', 'shi', '', NULL, '登汾上閣 鄭中丞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797359d4-7b87-457b-88bb-5998760e42b4', '爲御史銜命出關讞獄道中看華山有詩', '爲御史銜命出关讞獄道中看华山有诗', 'c8708834-30f0-482b-9ac8-ceed43e46c7c', '唐', '["野麋蒙象暫如犀，心不驚鷗角駭雞。","一路好山無伴看，斷腸煙景寄猨啼。"]', '["野麋蒙象暫如犀，心不驚鷗角駭雞。","一路好山無伴看，斷腸煙景寄猨啼。"]', '诗', 'shi', '', NULL, '爲御史銜命出關讞獄道中看華山有詩 韓常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2a1d78-f91a-4084-b818-929fb76a3807', '寄織錦篇與薛郎中', '寄织錦篇與薛郎中', 'c8708834-30f0-482b-9ac8-ceed43e46c7c', '唐', '["錦字龍梭織錦篇，鳳皇文采間非煙。","並他時世新花樣，虛費工夫不直錢。"]', '["錦字龙梭织錦篇，鳳皇文采间非煙。","並他时世新花樣，虛費工夫不直錢。"]', '诗', 'shi', '', NULL, '寄織錦篇與薛郎中 韓常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d473c537-1d3a-47f5-bd23-2ac19d730adc', '和人憶鶴', '和人憶鹤', 'c8708834-30f0-482b-9ac8-ceed43e46c7c', '唐', '["拂拂雲衣冠紫煙，已爲丁令一千年。","留君且伴居山客，幸有松梢明月天。"]', '["拂拂云衣冠紫煙，已爲丁令一千年。","留君且伴居山客，幸有松梢明月天。"]', '诗', 'shi', '', NULL, '和人憶鶴 韓常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc4ddd2-57bc-4d5e-859c-b77437537497', '句', '句', 'c8708834-30f0-482b-9ac8-ceed43e46c7c', '唐', '["情多不似家山水，夜夜聲聲旁枕流。"]', '["情多不似家山水，夜夜声声旁枕流。"]', '诗', 'shi', '', NULL, '句 韓常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31773c95-527b-4174-adf7-e69aa3fdbdc8', '贈米都知', '贈米都知', '1285a8d5-6661-489b-b4cc-1d68a495674a', '唐', '["供奉三朝四十年，聖時流落髮衰殘。","貪將樂府歌明代，不把清吟換好官。"]', '["供奉三朝四十年，聖时流落髮衰殘。","貪將乐府歌明代，不把清吟換好官。"]', '诗', 'shi', '', NULL, '贈米都知 梁補闕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbd3c97-e050-461c-9167-2dd3d7283a84', '題安國觀', '題安国观', '196c8adf-1a61-4665-8662-d65b8d17d402', '唐', '["夕照紗窗起暗塵，青松遶殿不知春。","君看白首誦經者，半是宮中歌舞人。"]', '["夕照紗窗起暗塵，青松遶殿不知春。","君看白首誦經者，半是宮中歌舞人。"]', '诗', 'shi', '', NULL, '題安國觀 盧尚書 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65606422-0e3f-4983-a7db-e6b68f3c6c1b', '自商山宿隱居', '自商山宿隐居', 'cfabb707-de70-40c7-bd62-1f8e510d16c5', '唐', '["聞道桃源堪避秦，尋幽數日不逢人。","煙霞洞裏無雞犬，風雨林中有鬼神。","黃公石上三芝秀，陶令門前五柳春。","醉臥白雲閑入夢，不知何物是吾身。"]', '["闻道桃源堪避秦，尋幽數日不逢人。","煙霞洞裏無雞犬，风雨林中有鬼神。","黄公石上三芝秀，陶令门前五柳春。","醉臥白云闲入梦，不知何物是吾身。"]', '诗', 'shi', '', NULL, '自商山宿隱居 蘇廣文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6dacbc1-e355-4e5f-8cc4-6645eca8acc6', '夜歸華川因寄幕府', '夜归华川因寄幕府', 'cfabb707-de70-40c7-bd62-1f8e510d16c5', '唐', '["山村寥落野人稀，竹裏衡門掩翠微。","溪路夜隨明月入，亭臯春伴白雲歸。","嵇康懶慢仍耽酒，范蠡逋逃又拂衣。","汀畔數鷗閑不起，只應知我已忘機。"]', '["山村寥落野人稀，竹裏衡门掩翠微。","溪路夜隨明月入，亭臯春伴白云归。","嵇康懶慢仍耽酒，范蠡逋逃又拂衣。","汀畔數鷗闲不起，只應知我已忘機。"]', '诗', 'shi', '', NULL, '夜歸華川因寄幕府 蘇廣文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ab5e33-655c-44b0-8b70-46217142d1fe', '春日過田明府遇焦山人', '春日過田明府遇焦山人', 'cfabb707-de70-40c7-bd62-1f8e510d16c5', '唐', '["陶公歸隱白雲溪，買得春泉溉藥畦。","夜靜林間風虎嘯，月明竹上露禽棲。","陳倉邑吏驚烽火，太白山人訝鼓鼙。","相見只言秦漢事，武陵溪裏草萋萋。"]', '["陶公归隐白云溪，買得春泉溉藥畦。","夜静林间风虎嘯，月明竹上露禽棲。","陳倉邑吏驚烽火，太白山人訝鼓鼙。","相见只言秦漢事，武陵溪裏草萋萋。"]', '诗', 'shi', '', NULL, '春日過田明府遇焦山人 蘇廣文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('559906a6-ebc6-4198-8edb-8595e19ee359', '題升山', '題升山', '745a56f0-7fcc-4e0e-927f-3a5e5929e970', '唐', '["城外升山寺，城中望宛然。","及登無半日，欲到已經年。"]', '["城外升山寺，城中望宛然。","及登無半日，欲到已經年。"]', '诗', 'shi', '', NULL, '題升山 任生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e28adc-3a45-4785-94f9-0f97f65ce9ba', '投曹文姬詩', '投曹文姬诗', '745a56f0-7fcc-4e0e-927f-3a5e5929e970', '唐', '["玉皇前殿掌書仙，一染塵心下九天。","莫怪濃香薰骨膩，雲衣曾惹御爐煙。"]', '["玉皇前殿掌书仙，一染塵心下九天。","莫怪濃香薰骨膩，云衣曾惹御爐煙。"]', '诗', 'shi', '', NULL, '投曹文姬詩 任生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dc04e9-e4ba-4f75-9cbf-400f5d76f6bb', '絕句', '絕句', 'ea706621-0378-4922-b1d9-6cfa6bb1f7e3', '唐', '["去國投茲土，編茅隱舊蹤。","年年秋水上，獨對數株松。"]', '["去国投茲土，編茅隐旧蹤。","年年秋水上，独对數株松。"]', '诗', 'shi', '', NULL, '絕句 吳公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2878de-6f63-496e-a5f4-531e77314284', '獻盧常侍', '獻盧常侍', '7d0a6c55-c755-4b14-a824-c8cf94b76376', '唐', '["拜玉亭前閑送客，此時孤恨感離鄉。","尋思往歲絕纓事，肯向朱門泣夜長。"]', '["拜玉亭前闲送客，此时孤恨感離乡。","尋思往歲絕纓事，肯向朱门泣夜长。"]', '诗', 'shi', '', NULL, '獻盧常侍 曹生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706207ec-8207-47dd-815b-f2b4448bf4ef', '賦新月', '賦新月', 'fce27537-e506-4ebc-ac7f-17fe0c724ddd', '唐', '["初月如弓未上弦，分明挂在碧霄邊。","時人莫道蛾眉小，三五團圓照滿天。"]', '["初月如弓未上弦，分明挂在碧霄邊。","时人莫道蛾眉小，三五團圓照满天。"]', '诗', 'shi', '', NULL, '賦新月 繆氏子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42d2e42-00bc-4a8b-9594-794dfb7d9cac', '悼妓詩', '悼妓诗', '8e88e150-9243-4413-843c-439aaea438ea', '唐', '["惆悵金泥簇蝶裙，春來猶見伴行雲。","不教布施剛留得，渾似初逢李少君。"]', '["惆悵金泥簇蝶裙，春来猶见伴行云。","不教布施剛留得，渾似初逢李少君。"]', '诗', 'shi', '', NULL, '悼妓詩 京兆韋氏子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07400aad-ddbe-4eba-af00-017c29311a3e', '長寧公主宅流杯', '长寧公主宅流杯', '59400228-fde6-4905-b2da-a060f50def9f', '唐', '["憑高瞰逈足怡心，[菌]閣桃源不暇尋。","餘雪依林成玉樹，殘霙點岫即瑤岑。"]', '["憑高瞰逈足怡心，[菌]閣桃源不暇尋。","餘雪依林成玉樹，殘霙点岫即瑤岑。"]', '诗', 'shi', '', NULL, '長寧公主宅流杯 景龍文館學士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbfbbb23-04da-4d66-874b-1d0bd0db25b8', '侍宴桃園詠桃花應制', '侍宴桃园詠桃花應制', '5ba59602-14ed-4bbe-851a-e41a33fe7d2b', '唐', '["源水叢花無數開，丹跗紅萼間青梅。","從今結子三千歲，預喜仙遊復摘來。"]', '["源水叢花無數开，丹跗紅萼间青梅。","從今結子三千歲，預喜仙游复摘来。"]', '诗', 'shi', '', NULL, '侍宴桃園詠桃花應制 神龍從臣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cb8082-6449-4f49-9402-f2b27cbfb9e9', '玉龍子詩', '玉龙子诗', '9c610e00-6a0e-4548-8e1c-44faca39a902', '唐', '["聖運潛符瑞玉龍，自興雲雨更無蹤。","不如渭水沙中得，爭保鑾輿復九重。"]', '["聖運潛符瑞玉龙，自兴云雨更無蹤。","不如渭水沙中得，爭保鑾輿复九重。"]', '诗', 'shi', '', NULL, '玉龍子詩 天寶時人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f06bbad-53b4-44c7-8f29-f9cdbf68167e', '寄兄', '寄兄', '6bbc0948-c381-45f6-b7a1-63c586dd7652', '唐', '["涉江今日恨偏多，援筆長吁欲奈何。","倘使淚流西去得，便應添作錦江波。"]', '["涉江今日恨偏多，援笔长吁欲奈何。","倘使泪流西去得，便應添作錦江波。"]', '诗', 'shi', '', NULL, '寄兄 僖宗朝北省官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e813e68b-6afa-4a6d-a4de-e89d3214f8c2', '題屈原祠', '題屈原祠', '097f8317-a97c-4849-9b27-e8181d08e7c9', '唐', '["蒼藤古木幾經春，舊祀祠堂小水濱。","行客謾陳三酎酒，大夫元是獨醒人。"]', '["蒼藤古木幾經春，旧祀祠堂小水濱。","行客謾陳三酎酒，大夫元是独醒人。"]', '诗', 'shi', '', NULL, '題屈原祠 洪州將軍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10294dd8-7c8d-42eb-b270-210d350cf261', '題端正樹', '題端正樹', 'e8e45fac-174a-4879-9dac-3240f76f68fb', '唐', '["昔日偏霑雨露榮，德皇西幸賜嘉名。","馬嵬此去無多地，合向楊妃冢上生。"]', '["昔日偏霑雨露榮，德皇西幸賜嘉名。","马嵬此去無多地，合向楊妃冢上生。"]', '诗', 'shi', '', NULL, '題端正樹 貞元文士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6137c425-f193-43a5-acc8-9bd3561576ec', '寄內詩', '寄內诗', 'f13b5cef-95d8-4520-a678-c37dfa8cd0a8', '唐', '["握筆題詩易，荷戈征戍難。","慣從鴛被暖，怯向鴈門寒。","瘦盡寬衣帶，啼多漬枕檀。","試留青黛著，迴日畫眉看。"]', '["握笔題诗易，荷戈征戍难。","慣從鴛被暖，怯向鴈门寒。","瘦尽寬衣带，啼多漬枕檀。","試留青黛著，迴日畫眉看。"]', '诗', 'shi', '', NULL, '寄內詩 河北士人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b1a6d7-661c-4fbe-8000-860c2602fdc9', '代妻荅詩', '代妻荅诗', 'f13b5cef-95d8-4520-a678-c37dfa8cd0a8', '唐', '["蓬鬢荆釵世所稀，布裙猶是嫁時衣。","胡麻好種無人種，合是歸時底不歸。"]', '["蓬鬢荆釵世所稀，布裙猶是嫁时衣。","胡麻好種無人種，合是归时底不归。"]', '诗', 'shi', '', NULL, '代妻荅詩 河北士人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fc4aab-1b16-468c-9275-8063ebff1238', '丙申歲詩', '丙申歲诗', 'a053956f-786f-4924-a58d-981f73552bdc', '唐', '["元和天子丙申年，三十三人同得仙。","袍似爛銀文似錦，相將白日上青天。"]', '["元和天子丙申年，三十三人同得仙。","袍似爛銀文似錦，相將白日上青天。"]', '诗', 'shi', '', NULL, '丙申歲詩 元和舉子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce882edb-1da3-42ad-bf57-81c16314e90e', '刺安南事詩', '刺安南事诗', 'bf03eb5a-31d4-41b4-869c-40a12bf25d42', '唐', '["南荒不擇吏，致我交趾覆。","聯綿三四年，致我交趾辱。","儒者鬬則退，武者兵益黷。","軍容滿天下，戰將多金玉。","刮得齊民瘡，分爲猛士祿。","雄雄許昌師，忠武冠其族。","去爲萬騎風，住爲一川肉。","時有殘卒迴，千門萬戶哭。","哀聲動閭里，怨氣成山谷。","誰能聽鼓聲，不忍看金鏃。","念此堪淚流，悠悠潁川綠。"]', '["南荒不擇吏，致我交趾覆。","聯綿三四年，致我交趾辱。","儒者鬬則退，武者兵益黷。","軍容满天下，戰將多金玉。","刮得齊民瘡，分爲猛士祿。","雄雄許昌師，忠武冠其族。","去爲万騎风，住爲一川肉。","时有殘卒迴，千门万戶哭。","哀声动閭里，怨氣成山谷。","誰能听鼓声，不忍看金鏃。","念此堪泪流，悠悠潁川綠。"]', '诗', 'shi', '', NULL, '刺安南事詩 懿宗朝舉子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2e3d64-a7e8-42d9-9e2b-e1093c1203c5', '歌', '歌', 'ec23f4f8-6baa-4f31-8e06-023128dbd1c4', '唐', '["執板狂歌乞個錢，塵中流浪且隨緣。","直饒到老常如此，猶勝危時弄化權。"]', '["執板狂歌乞個錢，塵中流浪且隨緣。","直饒到老常如此，猶勝危时弄化權。"]', '诗', 'shi', '', NULL, '歌 白衫舉子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece0696f-706a-4087-8c90-64e4a9746af4', '覩野花思京師舊遊', '覩野花思京師旧游', 'f229d59e-0fdc-4938-8dd1-356c3f0d2aa2', '唐', '["曾過街西看牡丹，牡丹纔謝便心闌。","如今變作村園眼，鼓子花開也喜歡。"]', '["曾過街西看牡丹，牡丹纔謝便心闌。","如今变作村园眼，鼓子花开也喜歡。"]', '诗', 'shi', '', NULL, '覩野花思京師舊遊 唐末朝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2ec0ba-10b1-4ae3-8859-1e7752625331', '哥舒歌', '哥舒歌', '2fd1adae-e222-4919-b6c1-e3fd5c9adcfd', '唐', '["北斗七星高，哥舒夜帶刀。","至今窺牧馬，不敢過臨洮。"]', '["北斗七星高，哥舒夜带刀。","至今窺牧马，不敢過臨洮。"]', '诗', 'shi', '', NULL, '哥舒歌 西鄙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c479f9-4094-4baf-9efb-7032b61b4abc', '荅人', '荅人', 'cc80cfc4-1b56-4e7c-a5de-f76d0867881e', '唐', '["偶來松樹下，高枕石頭眠。","山中無曆日，寒盡不知年。"]', '["偶来松樹下，高枕石头眠。","山中無曆日，寒尽不知年。"]', '诗', 'shi', '', NULL, '荅人 太上隱君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f674f0-c7ef-4bdd-8462-26f10814d808', '向竹吟', '向竹吟', '9bfa1fae-c3f1-42ff-adb8-4bdee8129b1c', '唐', '["積塵爲太山，掬水成東海。","富貴有時乖，希夷無日改。","絳節出崆峒，霓衣發光彩。","古者有七賢，六個今何在。"]', '["積塵爲太山，掬水成东海。","富貴有时乖，希夷無日改。","絳節出崆峒，霓衣發光彩。","古者有七賢，六個今何在。"]', '诗', 'shi', '', NULL, '向竹吟 黃山隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c7447e-3b32-4c4c-ac43-1b0cfcdfcce9', '歌', '歌', 'b4f48677-e116-4efa-95a1-2a58235f1585', '唐', '["靜居青嶂裏，高嘯紫煙中。","塵世連仙界，瓊田前路通。"]', '["静居青嶂裏，高嘯紫煙中。","塵世連仙界，瓊田前路通。"]', '诗', 'shi', '', NULL, '歌 婺州山中人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb3c7eb-b288-48ab-99a4-fa6cfcab9668', '五子之歌 一', '五子之歌 一', 'aaba0bcf-942f-4d33-9d0c-37c11f90a09a', '唐', '["邦惟固本自安寧，臨下常須馭朽驚。","何事十旬遊不返，禍胎從此召殷兵。"]', '["邦惟固本自安寧，臨下常須馭朽驚。","何事十旬游不返，禍胎從此召殷兵。"]', '诗', 'shi', '', NULL, '五子之歌 一 同谷子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e74dfc-abc7-45c9-becf-d87106eff26c', '五子之歌 二', '五子之歌 二', 'aaba0bcf-942f-4d33-9d0c-37c11f90a09a', '唐', '["酒色聲禽號四荒，那堪峻宇又彫墙。","靜思今古爲君者，未或因茲不滅亡。"]', '["酒色声禽號四荒，那堪峻宇又彫墙。","静思今古爲君者，未或因茲不滅亡。"]', '诗', 'shi', '', NULL, '五子之歌 二 同谷子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77d3397-803e-4837-8c46-7de3abf83055', '五子之歌 三', '五子之歌 三', 'aaba0bcf-942f-4d33-9d0c-37c11f90a09a', '唐', '["唯彼陶唐有冀方，少年都不解思量。","如今算得當時事，首爲盤遊亂紀綱。"]', '["唯彼陶唐有冀方，少年都不解思量。","如今算得當时事，首爲盤游亂紀綱。"]', '诗', 'shi', '', NULL, '五子之歌 三 同谷子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d48f15b-c077-41ae-92e6-f919030224f8', '五子之歌 四', '五子之歌 四', 'aaba0bcf-942f-4d33-9d0c-37c11f90a09a', '唐', '["明明我祖萬邦君，典則貽將示子孫。","惆悵太康荒墜後，覆宗絕祀滅其門。"]', '["明明我祖万邦君，典則貽將示子孫。","惆悵太康荒墜後，覆宗絕祀滅其门。"]', '诗', 'shi', '', NULL, '五子之歌 四 同谷子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9b4ec1-9bb9-43e5-b8c4-f0a5849b2976', '五子之歌 五', '五子之歌 五', 'aaba0bcf-942f-4d33-9d0c-37c11f90a09a', '唐', '["仇讐萬姓遂無依，顏厚何曾解忸怩。","五子既歌邦已失，一場前事悔難追。"]', '["仇讐万姓遂無依，顏厚何曾解忸怩。","五子既歌邦已失，一場前事悔难追。"]', '诗', 'shi', '', NULL, '五子之歌 五 同谷子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4fd1c5-7855-4e13-80ea-b1bc42a67de3', '獻公佐詩', '獻公佐诗', '63951f0d-68b6-4575-bd69-e189b33ba33c', '唐', '["破額幞頭衫也穿，使君猶許對華筵。","今朝幸倚文章守，遮莫青蛾笑揭天。"]', '["破額幞头衫也穿，使君猶許对华筵。","今朝幸倚文章守，遮莫青蛾笑揭天。"]', '诗', 'shi', '', NULL, '獻公佐詩 崔公佐客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f9e068-6c89-4ab9-acac-53577be934fc', '贈妓茂英', '贈妓茂英', 'a845eb9d-011f-48f6-8882-dd7d8bdb8149', '唐', '["憶昔當初過柳樓，茂英年小尚嬌羞。","隔窗未省聞高語，對鏡曾窺學上頭。","一別中原俱老大，再來南國見風流。","彈弦酌酒話前事，零落碧雲生暮愁。"]', '["憶昔當初過柳楼，茂英年小尚嬌羞。","隔窗未省闻高語，对镜曾窺学上头。","一別中原俱老大，再来南国见风流。","彈弦酌酒話前事，零落碧云生暮愁。"]', '诗', 'shi', '', NULL, '贈妓茂英 洛中舉子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae719d0b-4811-4169-b7dd-8f056e9fbc37', '又贈妓茂英', '又贈妓茂英', 'a845eb9d-011f-48f6-8882-dd7d8bdb8149', '唐', '["少插花枝少下籌，須防女伴妬風流。","坐中若打占相令，除却尚書莫點頭。"]', '["少插花枝少下籌，須防女伴妬风流。","坐中若打占相令，除却尚书莫点头。"]', '诗', 'shi', '', NULL, '又贈妓茂英 洛中舉子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8e098f0-39bf-45a2-95d2-6f4f6196b897', '寄故姬', '寄故姬', 'd569ba6f-77bf-4efa-bd54-3ad398e62c56', '唐', '["陰雲羃羃下陽臺，惹著襄王更不迴。","五度看花空有淚，一心如結不曾開。","纖蘿自合依芳樹，覆水寧思返舊杯。","惆悵高麗坡底宅，春光無復下山來。"]', '["陰云羃羃下陽台，惹著襄王更不迴。","五度看花空有泪，一心如結不曾开。","纖蘿自合依芳樹，覆水寧思返旧杯。","惆悵高丽坡底宅，春光無复下山来。"]', '诗', 'shi', '', NULL, '寄故姬 江陵士子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b75ff3c-1cd8-482c-9630-4a5f8f718cb8', '吟', '吟', 'a8efebb8-6587-4b40-ad96-2ab0fb408cfa', '唐', '["學織繚綾功未多，亂拈機杼錯拋梭。","莫教官錦行家見，把此文章笑殺他。"]', '["学织繚綾功未多，亂拈機杼錯拋梭。","莫教官錦行家见，把此文章笑殺他。"]', '诗', 'shi', '', NULL, '吟 織錦人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d9c5ed-b2c7-49ae-94e3-e87546c8f61f', '句', '句', 'a8efebb8-6587-4b40-ad96-2ab0fb408cfa', '唐', '["如今不重文章士，莫把文章誇向人。"]', '["如今不重文章士，莫把文章誇向人。"]', '诗', 'shi', '', NULL, '句 織錦人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a19f611-8a36-48e8-8c2e-f5c48f52c8f8', '送南中尉', '送南中尉', '3eab9c95-8b7f-408e-a509-e7637f5a50e7', '唐', '["羨君初拜職，嗟我獨無名。","且是正員尉，全勝兼試卿。"]', '["羨君初拜職，嗟我独無名。","且是正員尉，全勝兼試卿。"]', '诗', 'shi', '', NULL, '送南中尉 吏部選人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfbbaab5-110b-43ad-b000-6f2f066510c5', '題紫微觀', '題紫微观', 'cbae2cbe-1b05-41be-9ac0-d806fdb8275b', '唐', '["昨日朝天過紫微，醮壇風冷杏花稀。","碧桃泥我傳消息，何事人間更不歸。"]', '["昨日朝天過紫微，醮壇风冷杏花稀。","碧桃泥我傳消息，何事人间更不归。"]', '诗', 'shi', '', NULL, '題紫微觀 建業卜者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a5a06a-e6c6-4c64-af4a-8bb4e1d6ccc6', '題鄧仙客墓', '題鄧仙客墓', '2e80c8e8-01a0-4c45-8d3b-0bedd4e7fe5b', '唐', '["鶴老芝田雞在籠，上清那與俗塵同。","既言白日升仙去，何事人間有殯宮。"]', '["鹤老芝田雞在籠，上清那與俗塵同。","既言白日升仙去，何事人间有殯宮。"]', '诗', 'shi', '', NULL, '題鄧仙客墓 天嶠遊人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b19f000-da4b-4773-8faf-fab469cce0ca', '題故翠微宮', '題故翠微宮', '60a767ca-d0e8-44be-a88b-78031928be27', '唐', '["翠微寺本翠微宮，樓閣亭臺幾十重。","天子不來僧又去，樵夫時倒一株松。"]', '["翠微寺本翠微宮，楼閣亭台幾十重。","天子不来僧又去，樵夫时倒一株松。"]', '诗', 'shi', '', NULL, '題故翠微宮 驪山遊人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e96c2374-51c8-4ddf-9880-e9b39d722814', '吟', '吟', 'ed8ce390-5c89-4e79-915e-bcc3e80a7f06', '唐', '["野鵲灘西一櫂孤，月光遙接洞庭湖。","堪嗟迴雁峰前過，望斷家山一字無。"]', '["野鵲灘西一櫂孤，月光遙接洞庭湖。","堪嗟迴雁峰前過，望斷家山一字無。"]', '诗', 'shi', '', NULL, '吟 衡州舟子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15456482-98d0-439e-8624-d53efd852b90', '月夜', '月夜', '9e82225b-f329-4495-813a-90e54228e937', '唐', '["澗水泠泠聲不絕，溪流茫茫野花發。","自去自來人不知，歸時常對空山月。"]', '["澗水泠泠声不絕，溪流茫茫野花發。","自去自来人不知，归时常对空山月。"]', '诗', 'shi', '', NULL, '月夜 華山老人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20704ece-bf81-41c6-826d-1215212340f8', '終南', '終南', '5b6a5825-1f21-4563-8d5a-e0f711c9b6bc', '唐', '["霜鶴鳴時夕風急，亂鴉又向寒林集。","此君輟櫂悲且吟，獨對蓮花一峰立。"]', '["霜鹤鳴时夕风急，亂鴉又向寒林集。","此君輟櫂悲且吟，独对蓮花一峰立。"]', '诗', 'shi', '', NULL, '終南 終南山翁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4263f1e-e295-45f5-b808-746af8db52a0', '大慶堂賜宴元璫有詩呈吳越王', '大慶堂賜宴元璫有诗呈吳越王', 'd5963e50-cb56-498f-9fb4-6778fe0d9461', '唐', '["非爲親賢展綺筵，恆常寧敢恣遊盤。","綠搓楊柳綿初軟，紅暈櫻桃粉未乾。","谷鳥乍啼聲似澀，甘霖方霽景猶寒。","笙歌風緊人酣醉，却遶珍叢爛熳看。"]', '["非爲親賢展綺筵，恆常寧敢恣游盤。","綠搓楊柳綿初軟，紅暈櫻桃粉未乾。","谷鸟乍啼声似澀，甘霖方霽景猶寒。","笙歌风緊人酣醉，却遶珍叢爛熳看。"]', '诗', 'shi', '', NULL, '大慶堂賜宴元璫有詩呈吳越王 吳越失姓名人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c30ecb-14a3-417d-9ef7-6bf756deeb0d', '又和大慶堂賜宴元璫有詩呈吳越王', '又和大慶堂賜宴元璫有诗呈吳越王', 'd5963e50-cb56-498f-9fb4-6778fe0d9461', '唐', '["櫻桃花下會親賢，風遠銅壺轉露盤。","蝶下粉牆梅乍折，蟻浮金斝酒難乾。","雲和緩奏泉聲咽，珠箔低垂水影寒。","狂簡斐然吟詠足，却邀羣彥重吟看。"]', '["櫻桃花下會親賢，风远銅壺轉露盤。","蝶下粉牆梅乍折，蟻浮金斝酒难乾。","云和緩奏泉声咽，珠箔低垂水影寒。","狂簡斐然吟詠足，却邀羣彥重吟看。"]', '诗', 'shi', '', NULL, '又和大慶堂賜宴元璫有詩呈吳越王 吳越失姓名人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c982d54-f0f9-42fa-abfb-b676bc06bc54', '再和大慶堂賜宴元璫有詩呈吳越王', '再和大慶堂賜宴元璫有诗呈吳越王', 'd5963e50-cb56-498f-9fb4-6778fe0d9461', '唐', '["我有嘉賓宴乍歡，畫簾紋細鳳雙盤。","影籠沼沚修篁密，聲透笙歌羯鼓乾。","散後便依書篋寐，渴來潛想玉壺寒。","櫻桃零落紅桃媚，更俟旬餘共醉看。"]', '["我有嘉賓宴乍歡，畫簾紋細鳳雙盤。","影籠沼沚修篁密，声透笙歌羯鼓乾。","散後便依书篋寐，渴来潛想玉壺寒。","櫻桃零落紅桃媚，更俟旬餘共醉看。"]', '诗', 'shi', '', NULL, '再和大慶堂賜宴元璫有詩呈吳越王 吳越失姓名人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a053b123-0b29-4377-b901-82582c68a04a', '重和大慶堂賜宴元璫有詩呈吳越王', '重和大慶堂賜宴元璫有诗呈吳越王', 'd5963e50-cb56-498f-9fb4-6778fe0d9461', '唐', '["冷宴殷勤展小園，舞鞇柔軟綵虬盤。","篸花盡日疑頭重，病酒經宵覺口乾。","嘉樹倚樓青瑣暗，晚雲藏雨碧山寒。","文章天子文章別，八采盧郎未可看。"]', '["冷宴殷勤展小园，舞鞇柔軟綵虬盤。","篸花尽日疑头重，病酒經宵覺口乾。","嘉樹倚楼青瑣暗，晚云藏雨碧山寒。","文章天子文章別，八采盧郎未可看。"]', '诗', 'shi', '', NULL, '重和大慶堂賜宴元璫有詩呈吳越王 吳越失姓名人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5ad3a2-5f02-454d-a820-2a19cc438e66', '御製春遊長句', '御製春游长句', 'd5963e50-cb56-498f-9fb4-6778fe0d9461', '唐', '["天意分明道已光，春遊嘉景勝仙鄉。","玉爐煙直風初靜，銀漢雲銷日正長。","柳帶似眉全展綠，杏苞似臉半開香。","黃鶯歷歷啼紅樹，紫燕關關語畫梁。","低檻晚晴籠翡翠，小池波暖浴鴛鴦。","馬嘶廣陌貪新草，人醉花堤怕夕陽。","比屋管弦呈妙曲，連營羅綺鬬時妝。","全吳霸越千年後，獨此昇平顯萬方。"]', '["天意分明道已光，春游嘉景勝仙乡。","玉爐煙直风初静，銀漢云銷日正长。","柳带似眉全展綠，杏苞似臉半开香。","黄鶯歷歷啼紅樹，紫燕关关語畫梁。","低檻晚晴籠翡翠，小池波暖浴鴛鴦。","马嘶廣陌貪新草，人醉花堤怕夕陽。","比屋管弦呈妙曲，連營羅綺鬬时妝。","全吳霸越千年後，独此昇平显万方。"]', '诗', 'shi', '', NULL, '御製春遊長句 吳越失姓名人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e9c75d7-efad-4f3c-b815-7a38db500c61', '明月湖醉後薔薇花歌', '明月湖醉後薔薇花歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["萬朵當軒紅灼灼，晚陰照水塵不著。","西施醉後情不禁，侍兒扶下蘂珠閣。","柔條嫩蘂輕𩸬鰓，一低一昂合又開。","深紅淺綠狀不得，日斜池畔香風來。","紅能柔，綠能軟，濃淡參差相宛轉。","舞蝶雙雙誰喚來，輕綃片片何人剪。","白髮使君思帝鄉，驅妻領女遊花傍。","持盃憶著曲江事，千花萬葉垂宮墙。","復有同心初上第，日暮華筵移水際。","笙歌日日徵教坊，傾國名倡盡佳麗。","我曾此處同諸生，飛盂落盞紛縱橫。","將欲得到上天路，剛向直道中行去。","一朝失勢當如此，萬事如灰壯心死。","誰知奏御數萬言，翻割龜符四千里。","丈夫達則賢，窮則愚，胡爲紫，胡爲朱。","莫思身外窮通事，且醉花前一百壺。"]', '["万朵當軒紅灼灼，晚陰照水塵不著。","西施醉後情不禁，侍兒扶下蘂珠閣。","柔條嫩蘂轻𩸬鰓，一低一昂合又开。","深紅淺綠狀不得，日斜池畔香风来。","紅能柔，綠能軟，濃淡參差相宛轉。","舞蝶雙雙誰喚来，轻綃片片何人剪。","白髮使君思帝乡，驱妻領女游花傍。","持盃憶著曲江事，千花万葉垂宮墙。","复有同心初上第，日暮华筵移水際。","笙歌日日徵教坊，傾国名倡尽佳丽。","我曾此处同諸生，飞盂落盞紛縱橫。","將欲得到上天路，剛向直道中行去。","一朝失勢當如此，万事如灰壯心死。","誰知奏御數万言，翻割龟符四千里。","丈夫達則賢，窮則愚，胡爲紫，胡爲朱。","莫思身外窮通事，且醉花前一百壺。"]', '诗', 'shi', '', NULL, '明月湖醉後薔薇花歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc12782-cd3c-4b6e-a929-39f538f45ea5', '春二首 一', '春二首 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["褭褭東風吹水國，金鴉影暖南山北。","蒲抽小劒割湘波，柳拂長眉舞春色。","白銅堤下煙蒼蒼，林端細蘂參差香。","綠桑枝下見桃葉，迴看青雲空斷腸。"]', '["褭褭东风吹水国，金鴉影暖南山北。","蒲抽小劒割湘波，柳拂长眉舞春色。","白銅堤下煙蒼蒼，林端細蘂參差香。","綠桑枝下见桃葉，迴看青云空斷腸。"]', '诗', 'shi', '', NULL, '春二首 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80156189-2d99-41ce-aab7-f041119c4d52', '春二首 二', '春二首 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["烏足遲遲日宮裏，天門擊鼓龍蛇起。","風師剪翠換枯條，青帝挼藍染江水。","蜂蝶繽紛抱香蘂，錦鱗跳擲紅雲尾。","繡衣白馬不歸來，雙成倚檻春心醉。"]', '["烏足遲遲日宮裏，天门擊鼓龙蛇起。","风師剪翠換枯條，青帝挼藍染江水。","蜂蝶繽紛抱香蘂，錦鱗跳擲紅云尾。","繡衣白马不归来，雙成倚檻春心醉。"]', '诗', 'shi', '', NULL, '春二首 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f345357-26c3-4dfc-8e76-49f8624e7514', '夏', '夏', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["赤帝旗迎火雲起，南山石裂吳牛死。","繡楹夜夜箔鰕鬚，象榻重重簟湘水。","彤彤日脚燒冰井，古陌塵飛野煙靜。","漢帝高堂汗若珠，班姬明月無停影。"]', '["赤帝旗迎火云起，南山石裂吳牛死。","繡楹夜夜箔鰕鬚，象榻重重簟湘水。","彤彤日脚燒冰井，古陌塵飞野煙静。","漢帝高堂汗若珠，班姬明月無停影。"]', '诗', 'shi', '', NULL, '夏 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e52f451-32d0-4fd4-9032-f1d808c18500', '秋', '秋', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月色驅秋下穹昊，梁間燕語辭巢早。","古苔凝紫貼瑤堦，露槿啼紅墮江草。","越客羈魂挂長道，西風欲揭南山倒。","粉娥恨骨不勝衣，映門楚碧蟬聲老。"]', '["月色驱秋下穹昊，梁间燕語辞巢早。","古苔凝紫貼瑤堦，露槿啼紅墮江草。","越客羈魂挂长道，西风欲揭南山倒。","粉娥恨骨不勝衣，映门楚碧蟬声老。"]', '诗', 'shi', '', NULL, '秋 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353b265c-fa15-4dc0-a037-83d9d63f96d0', '冬', '冬', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蒼茫枯磧陰雲滿，古木號空晝光短。","雲擁三峯嶽色低，冰堅九曲河聲斷。","浩汗霜風刮天地，溫泉火井無生意。","澤國龍蛇凍不伸，南山瘦柏銷殘翠。"]', '["蒼茫枯磧陰云满，古木號空晝光短。","云擁三峯嶽色低，冰堅九曲河声斷。","浩汗霜风刮天地，溫泉火井無生意。","澤国龙蛇凍不伸，南山瘦柏銷殘翠。"]', '诗', 'shi', '', NULL, '冬 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c414007e-44a0-410f-8262-6793c6a35907', '雞頭', '雞头', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["湖浪參差疊寒玉，水仙曉展鉢盤綠。","淡黃根老栗皺圓，染青刺短金罌熟。","紫羅小囊光緊蹙，一掬真珠藏蝟腹。","叢叢引觜傍蓮洲，滿川恐作天雞哭。"]', '["湖浪參差叠寒玉，水仙晓展鉢盤綠。","淡黄根老栗皺圓，染青刺短金罌熟。","紫羅小囊光緊蹙，一掬真珠藏蝟腹。","叢叢引觜傍蓮洲，满川恐作天雞哭。"]', '诗', 'shi', '', NULL, '雞頭 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff01b7b3-16d8-4508-990e-f67db21ac971', '紅薔薇', '紅薔薇', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["九天碎霞明澤國，造化工夫潛剪刻。","淺碧眉長約細枝，深紅刺短鉤春色。","晴日當樓曉香歇，錦帶盤空欲成結。","謝豹聲催麥隴秋，春風吹落猩猩血。"]', '["九天碎霞明澤国，造化工夫潛剪刻。","淺碧眉长約細枝，深紅刺短鉤春色。","晴日當楼晓香歇，錦带盤空欲成結。","謝豹声催麦隴秋，春风吹落猩猩血。"]', '诗', 'shi', '', NULL, '紅薔薇 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf510c42-d553-4816-8896-43ac1e832bfc', '斑竹簟', '斑竹簟', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["龍鱗滿牀波浪濕，血光點點湘娥泣。","一片晴霞凍不飛，深沈盡訝蛟人立。","百朵排花蜀纈明，珊瑚枕滑葛衣輕。","閑窗獨臥曉不起，冷浸羈魂錦江裏。"]', '["龙鱗满牀波浪濕，血光点点湘娥泣。","一片晴霞凍不飞，深沈尽訝蛟人立。","百朵排花蜀纈明，珊瑚枕滑葛衣轻。","闲窗独臥晓不起，冷浸羈魂錦江裏。"]', '诗', 'shi', '', NULL, '斑竹簟 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d56a819-85e1-4c64-8fbe-47d50c3afc71', '聽琴', '听琴', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["六律鏗鏘間宮徵，伶倫寫入梧桐尾。","七條瘦玉叩寒星，萬派流泉哭纖指。","空山雨腳隨雲起，古木燈青嘯山鬼。","田文墮淚曲未終，子規啼血哀猿死。"]', '["六律鏗鏘间宮徵，伶倫寫入梧桐尾。","七條瘦玉叩寒星，万派流泉哭纖指。","空山雨腳隨云起，古木灯青嘯山鬼。","田文墮泪曲未終，子規啼血哀猿死。"]', '诗', 'shi', '', NULL, '聽琴 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d7d12e-2f91-4569-887b-49d28eac2942', '石榴', '石榴', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蟬嘯秋雲槐葉齊，石榴香老庭枝低。","流霞色染紫罌粟，黃蠟紙苞紅瓠犀。","玉刻冰壺[含]露溼，斒斑似帶湘娥泣。","蕭娘初嫁嗜甘酸，嚼破水精千萬粒。"]', '["蟬嘯秋云槐葉齊，石榴香老庭枝低。","流霞色染紫罌粟，黄蠟紙苞紅瓠犀。","玉刻冰壺[含]露溼，斒斑似带湘娥泣。","蕭娘初嫁嗜甘酸，嚼破水精千万粒。"]', '诗', 'shi', '', NULL, '石榴 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70612bca-2824-47e1-8b3f-23d5a6ad4374', '秦家行', '秦家行', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["彗孛飛光照天地，九天瓦裂屯冤氣。","鬼哭聲聲怨趙高，宮花滴盡扶蘇淚。","禍起蕭牆不知戢，羽書催築長城急。","劒上忠臣血未乾，沛公已向函關入。"]', '["彗孛飞光照天地，九天瓦裂屯冤氣。","鬼哭声声怨趙高，宮花滴尽扶蘇泪。","禍起蕭牆不知戢，羽书催築长城急。","劒上忠臣血未乾，沛公已向函关入。"]', '诗', 'shi', '', NULL, '秦家行 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c1cbd4-b16d-473d-b2c7-99297fc099ea', '小蘇家', '小蘇家', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雙月謳䛩輾秋碧，細風斜掩神仙宅。","麥門冬長馬鬣青，茱萸蘂綻蠅頭赤。","流蘇斗帳懸高壁，綵鳳盤龍繳香額。","堂內月娥橫剪波，倚門腸斷鰕鬚隔。"]', '["雙月謳䛩輾秋碧，細风斜掩神仙宅。","麦门冬长马鬣青，茱萸蘂綻蠅头赤。","流蘇斗帳懸高壁，綵鳳盤龙繳香額。","堂內月娥橫剪波，倚门腸斷鰕鬚隔。"]', '诗', 'shi', '', NULL, '小蘇家 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252c496a-f8eb-47bf-ac64-878be7e60767', '斑竹', '斑竹', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["濃綠疎莖遶湘水，春風抽出蛟龍尾。","色抱霜花粉黛光，枝撑蜀錦紅霞起。","交戛敲欹無俗聲，滿林風曳刀槍橫。","殷痕苦雨洗不落，猶帶湘娥淚血腥。","嫋娜梢頭掃秋月，影穿林下疑殘雪。","我今慙愧子猷心，解愛此君名不滅。"]', '["濃綠疎莖遶湘水，春风抽出蛟龙尾。","色抱霜花粉黛光，枝撑蜀錦紅霞起。","交戛敲欹無俗声，满林风曳刀槍橫。","殷痕苦雨洗不落，猶带湘娥泪血腥。","嫋娜梢头掃秋月，影穿林下疑殘雪。","我今慙愧子猷心，解愛此君名不滅。"]', '诗', 'shi', '', NULL, '斑竹 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f37ef9c-df1a-4094-a68b-144ae3ac9bac', '天竺國胡僧水晶念珠', '天竺国胡僧水晶念珠', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天竺胡僧踏雲立，紅精素貫鮫人泣。","細影疑隨焰火銷，圓光恐滴袈裟溼。","夜梵西天千佛聲，指輪次第驅寒星。","若非葉下滴秋露，則是井底圓春冰。","淒清妙麗應難並，眼界真如意珠靜。","碧蓮花下獨提攜，堅潔何如幻泡影。"]', '["天竺胡僧踏云立，紅精素貫鮫人泣。","細影疑隨焰火銷，圓光恐滴袈裟溼。","夜梵西天千佛声，指輪次第驱寒星。","若非葉下滴秋露，則是井底圓春冰。","淒清妙丽應难並，眼界真如意珠静。","碧蓮花下独提携，堅潔何如幻泡影。"]', '诗', 'shi', '', NULL, '天竺國胡僧水晶念珠 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91cdfcea-aa76-4815-a8e9-39fc6b3e8b26', '白雪歌', '白雪歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["皇穹何處飛瓊屑，散下人間作春雪。","五花馬踏白雲衢，七香車碾瑤墀月。","蘇嵒乳洞擁山家，澗藤古栗盤銀虵。","寒郊複疊鋪柳絮，古磧爛熳吹蘆花。","流泉不下孤汀咽，斷臂老猿聲欲絕。","鳥啄冰潭玉鏡開，風敲簷溜水晶折。","拂戶初疑粉蝶飛，看山又訝白鷗歸。","孫康凍死讀書圍，火井不煖溫泉微。"]', '["皇穹何处飞瓊屑，散下人间作春雪。","五花马踏白云衢，七香车碾瑤墀月。","蘇嵒乳洞擁山家，澗藤古栗盤銀虵。","寒郊複叠鋪柳絮，古磧爛熳吹蘆花。","流泉不下孤汀咽，斷臂老猿声欲絕。","鸟啄冰潭玉镜开，风敲簷溜水晶折。","拂戶初疑粉蝶飞，看山又訝白鷗归。","孫康凍死读书圍，火井不煖溫泉微。"]', '诗', 'shi', '', NULL, '白雪歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d4b676-6d0a-42b5-9aca-d8122661b76c', '琵琶', '琵琶', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["粉胸繡臆誰家女，香撥星星共春語。","七盤嶺上走鸞鈴，十二峯頭弄雲雨。","千悲萬恨四五弦，弦中甲馬聲駢闐。","山僧撲破瑠璃鉢，壯士擊折珊瑚鞭。","珊瑚鞭折聲交戛，玉盤傾瀉真珠滑。","海神驅趁夜濤回，江娥蹙踏春冰裂。","滿坐紅妝盡淚垂，望鄉之客不勝悲。","曲終調絕忽飛去，洞庭月落孤雲歸。"]', '["粉胸繡臆誰家女，香撥星星共春語。","七盤嶺上走鸾鈴，十二峯头弄云雨。","千悲万恨四五弦，弦中甲马声駢闐。","山僧撲破瑠璃鉢，壯士擊折珊瑚鞭。","珊瑚鞭折声交戛，玉盤傾瀉真珠滑。","海神驱趁夜濤回，江娥蹙踏春冰裂。","满坐紅妝尽泪垂，望乡之客不勝悲。","曲終調絕忽飞去，洞庭月落孤云归。"]', '诗', 'shi', '', NULL, '琵琶 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61c8a78-805b-4e68-bfd7-7593670a86bf', '傷哉行', '傷哉行', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["兔走烏飛不相見，人事依稀速如電。","王母夭桃一度開，玉樓紅粉千回變。","車馳馬走咸陽道，石家舊宅空荒草。","秋雨無情不惜花，芙蓉一一驚顛倒。","勸君莫謾栽荆棘，秦皇虛費驅山力。","英風一去更無言，白骨沈埋暮山碧。"]', '["兔走烏飞不相见，人事依稀速如電。","王母夭桃一度开，玉楼紅粉千回变。","车驰马走咸陽道，石家旧宅空荒草。","秋雨無情不惜花，芙蓉一一驚顛倒。","勸君莫謾栽荆棘，秦皇虛費驱山力。","英风一去更無言，白骨沈埋暮山碧。"]', '诗', 'shi', '', NULL, '傷哉行 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9592f274-8188-4339-8a33-11fbf76a3c83', '留贈偃師主人', '留贈偃師主人', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["孤城漏未殘，徒侶拂征鞍。","洛北去愁遠，淮南歸夢闌。","曉燈迴壁暗，晴雪卷簾寒。","更盡主人酒，出門行路難。"]', '["孤城漏未殘，徒侶拂征鞍。","洛北去愁远，淮南归梦闌。","晓灯迴壁暗，晴雪卷簾寒。","更尽主人酒，出门行路难。"]', '诗', 'shi', '', NULL, '留贈偃師主人 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f535f0f-23fa-473f-91e0-e6afa433b99b', '長門', '长门', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["悵望黃金屋，恩衰似越逃。","花生針眼刺，月送剪腸刀。","地近歡娛遠，天低雨露高。","時看迴輦處，淚臉濕夭桃。"]', '["悵望黄金屋，恩衰似越逃。","花生針眼刺，月送剪腸刀。","地近歡娛远，天低雨露高。","时看迴輦处，泪臉濕夭桃。"]', '诗', 'shi', '', NULL, '長門 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb323057-9632-4475-85e8-fad977214766', '宴李家宅', '宴李家宅', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["畫屏深掩瑞雲光，羅綺花飛白玉堂。","銀榼酒傾魚尾倒，金鑪灰滿鴨心香。","輕搖綠水青蛾歛，亂觸紅絲皓腕狂。","今日恩榮許同聽，不辭沈醉一千觴。"]', '["畫屏深掩瑞云光，羅綺花飞白玉堂。","銀榼酒傾鱼尾倒，金鑪灰满鴨心香。","轻搖綠水青蛾歛，亂觸紅絲皓腕狂。","今日恩榮許同听，不辞沈醉一千觴。"]', '诗', 'shi', '', NULL, '宴李家宅 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837555e0-34d6-466e-9164-1f8603fc593b', '長信宮', '长信宮', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["細草侵堦亂碧鮮，宮門深鎖綠楊天。","珠簾欲捲擡秋水，羅幌微開動冷煙。","風引漏聲過枕上，月移花影到窗前。","獨挑殘燭魂堪斷，却恨青蛾誤少年。"]', '["細草侵堦亂碧鲜，宮门深鎖綠楊天。","珠簾欲捲擡秋水，羅幌微开动冷煙。","风引漏声過枕上，月移花影到窗前。","独挑殘燭魂堪斷，却恨青蛾誤少年。"]', '诗', 'shi', '', NULL, '長信宮 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f8885e-652d-4352-83c9-bf18d12b0394', '驪山感懷', '驪山感懷', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["武帝尋仙駕海遊，禁門高閉水空流。","深宮帶日年年色，翠柏凝煙夜夜愁。","鸞鳳影沈歸萬古，歌鐘聲斷夢千秋。","晚來惆悵無人會，雲雨能飛傍玉樓。"]', '["武帝尋仙駕海游，禁门高閉水空流。","深宮带日年年色，翠柏凝煙夜夜愁。","鸾鳳影沈归万古，歌鐘声斷梦千秋。","晚来惆悵無人會，云雨能飞傍玉楼。"]', '诗', 'shi', '', NULL, '驪山感懷 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5cb9070-ac9a-4086-9b20-4a52128a4ed0', '絕句', '絕句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["石沈遼海闊，劒別楚山長。","會合知無日，離心滿夕陽。"]', '["石沈遼海闊，劒別楚山长。","會合知無日，離心满夕陽。"]', '诗', 'shi', '', NULL, '絕句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b9c5d37-8ba4-4c8e-ae62-fd37c09da846', '聽唱鷓鴣', '听唱鷓鴣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["金谷歌傳第一流，鷓鴣清怨碧雲愁。","夜來省得曾聞處，萬里月明湘水流。"]', '["金谷歌傳第一流，鷓鴣清怨碧云愁。","夜来省得曾闻处，万里月明湘水流。"]', '诗', 'shi', '', NULL, '聽唱鷓鴣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa68c92-a7da-48d8-8523-f16ecbc00928', '雜詩 一', '杂诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["勸君莫惜金縷衣，勸君須惜少年時。","有花堪折直須折，莫待無花空折枝。"]', '["勸君莫惜金縷衣，勸君須惜少年时。","有花堪折直須折，莫待無花空折枝。"]', '诗', 'shi', '', NULL, '雜詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46fd701e-778c-40a9-b80a-e41bc65b2dd6', '雜詩 二', '杂诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["青天無雲月如燭，露泣梨花白如玉。","子規一夜啼到明，美人獨在空房宿。"]', '["青天無云月如燭，露泣梨花白如玉。","子規一夜啼到明，美人独在空房宿。"]', '诗', 'shi', '', NULL, '雜詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db56fd2f-189a-492a-8e26-22b0c1a8eac0', '雜詩 三', '杂诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["空賜羅衣不賜恩，一薰香後一銷魂。","雖然舞袖何曾舞，常對春風裛淚痕。"]', '["空賜羅衣不賜恩，一薰香後一銷魂。","雖然舞袖何曾舞，常对春风裛泪痕。"]', '诗', 'shi', '', NULL, '雜詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde072f7-3a49-4fae-9da7-7627fce5bf71', '雜詩 四', '杂诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不洗殘粧凭繡牀，也同女伴繡鴛鴦。","迴鍼刺到雙飛處，憶著征夫淚數行。"]', '["不洗殘粧凭繡牀，也同女伴繡鴛鴦。","迴鍼刺到雙飞处，憶著征夫泪數行。"]', '诗', 'shi', '', NULL, '雜詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54543804-e7ce-42e5-b871-a117755880bf', '雜詩 五', '杂诗 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["眼想心思夢裏驚，無人知我此時情。","不如池上鴛鴦鳥，雙宿雙飛過一生。"]', '["眼想心思梦裏驚，無人知我此时情。","不如池上鴛鴦鸟，雙宿雙飞過一生。"]', '诗', 'shi', '', NULL, '雜詩 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b618330-f54e-4dfd-a2d0-f603d076b8a3', '雜詩 六', '杂诗 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一去遼陽繫夢魂，忽傳征騎到中門。","紗窗不肯施紅粉，徒遣蕭郎問淚痕。"]', '["一去遼陽繫梦魂，忽傳征騎到中门。","紗窗不肯施紅粉，徒遣蕭郎问泪痕。"]', '诗', 'shi', '', NULL, '雜詩 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d15f0f-3fdf-4dfa-8d8c-701255b5ab91', '雜詩 七', '杂诗 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鸎啼露冷酒初醒，罨畫樓西曉角鳴。","翠羽帳中人夢覺，寶釵斜墜枕函聲。"]', '["鸎啼露冷酒初醒，罨畫楼西晓角鳴。","翠羽帳中人梦覺，寶釵斜墜枕函声。"]', '诗', 'shi', '', NULL, '雜詩 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9397f505-cf4b-48d2-b26d-9de799b8cb88', '雜詩 八', '杂诗 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["行人南北分征路，流水東西接御溝。","終日坡前怨離別，謾名長樂是長愁。"]', '["行人南北分征路，流水东西接御溝。","終日坡前怨離別，謾名长乐是长愁。"]', '诗', 'shi', '', NULL, '雜詩 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952f107b-d061-43a8-a750-8c93a6400d05', '雜詩 九', '杂诗 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["偏倚繡床愁不起，雙垂玉筯翠鬟低。","卷簾相待無消息，夜合花前日又西。"]', '["偏倚繡床愁不起，雙垂玉筯翠鬟低。","卷簾相待無消息，夜合花前日又西。"]', '诗', 'shi', '', NULL, '雜詩 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae7fde3-76e8-4415-9f55-ed486a6302c6', '雜詩 十', '杂诗 十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["悔將淚眼向東開，特地愁從望裏來。","三十六峯猶不見，況伊如鷰這身材。"]', '["悔將泪眼向东开，特地愁從望裏来。","三十六峯猶不见，況伊如鷰這身材。"]', '诗', 'shi', '', NULL, '雜詩 十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054435f1-48f9-4765-9571-6e289cf04fc7', '雜詩 十一', '杂诗 十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["滿目笙歌一段空，萬般離恨總隨風。","多情爲謝殘陽意，與展晴霞片片紅。"]', '["满目笙歌一段空，万般離恨總隨风。","多情爲謝殘陽意，與展晴霞片片紅。"]', '诗', 'shi', '', NULL, '雜詩 十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a67886-8eeb-4d0e-aeb6-5e5640b3f07e', '雜詩 十二', '杂诗 十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["兩心不語暗知情，燈下裁縫月下行。","行到堦前知未睡，夜深聞放剪刀聲。"]', '["兩心不語暗知情，灯下裁縫月下行。","行到堦前知未睡，夜深闻放剪刀声。"]', '诗', 'shi', '', NULL, '雜詩 十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e9a6b0-5035-4b1b-a9d3-ff1c279f53b6', '雜詩 十三', '杂诗 十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["近寒食雨草萋萋，著麥苗風柳映堤。","早是有家歸未得，杜鵑休向耳邊啼。"]', '["近寒食雨草萋萋，著麦苗风柳映堤。","早是有家归未得，杜鵑休向耳邊啼。"]', '诗', 'shi', '', NULL, '雜詩 十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fdef021-d2c3-4a5a-b8ed-2c8505b61294', '雜詩 十四', '杂诗 十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["水紋珍簟思悠悠，千里佳期一夕休。","從此無心愛良夜，任他明月下西樓。"]', '["水紋珍簟思悠悠，千里佳期一夕休。","從此無心愛良夜，任他明月下西楼。"]', '诗', 'shi', '', NULL, '雜詩 十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('763aac84-d842-4758-a3c3-d53a4d43b0bf', '雜詩 十五', '杂诗 十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["數日相隨兩不忘，郎心如妾妾如郎。","出門便是東西路，把取紅牋各斷腸。"]', '["數日相隨兩不忘，郎心如妾妾如郎。","出门便是东西路，把取紅牋各斷腸。"]', '诗', 'shi', '', NULL, '雜詩 十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59473944-8de7-43a0-a63a-86c48132adbb', '雜詩 十六', '杂诗 十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["無定河邊暮角聲，赫連臺畔旅人情。","函關歸路千餘里，一夕秋風白髮生。"]', '["無定河邊暮角声，赫連台畔旅人情。","函关归路千餘里，一夕秋风白髮生。"]', '诗', 'shi', '', NULL, '雜詩 十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47742bce-f9c3-4192-9c50-10fe206eee55', '雜詩 十七', '杂诗 十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["花落長川草色青，暮山重疊兩冥冥。","逢春便覺飄蓬苦，今日分飛一涕零。"]', '["花落长川草色青，暮山重叠兩冥冥。","逢春便覺飄蓬苦，今日分飞一涕零。"]', '诗', 'shi', '', NULL, '雜詩 十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e256a71-4613-4f65-bb15-f0a8e67c70d3', '雜詩 十八', '杂诗 十八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["洛陽才子隣簫恨，湘水佳人錦瑟愁。","今昔兩成惆悵事，臨邛春盡暮江流。"]', '["洛陽才子隣簫恨，湘水佳人錦瑟愁。","今昔兩成惆悵事，臨邛春尽暮江流。"]', '诗', 'shi', '', NULL, '雜詩 十八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4efe75c-a2ee-4ba6-9fe1-fe9472f6ebe8', '雜詩 十九', '杂诗 十九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["浙江輕浪去悠悠，望海樓吹望海愁。","莫怪鄉心隨魄斷，十年爲客在他州。"]', '["浙江轻浪去悠悠，望海楼吹望海愁。","莫怪乡心隨魄斷，十年爲客在他州。"]', '诗', 'shi', '', NULL, '雜詩 十九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('098c0261-265f-413b-bbbf-4bef538e9f49', '初過漢江', '初過漢江', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["襄陽好向峴亭看，人物蕭條值歲闌。","爲報習家多置酒，夜來風雪過江寒。"]', '["襄陽好向峴亭看，人物蕭條值歲闌。","爲報習家多置酒，夜来风雪過江寒。"]', '诗', 'shi', '', NULL, '初過漢江 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e743c1-8f09-494f-9025-cccb68d3382f', '讀庾信集', '读庾信集', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["四朝十帝盡風流，建業長安兩醉游。","惟有一篇楊柳曲，江南江北爲君愁。"]', '["四朝十帝尽风流，建業长安兩醉游。","惟有一篇楊柳曲，江南江北爲君愁。"]', '诗', 'shi', '', NULL, '讀庾信集 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d14f18b1-3b2f-493e-804e-d6c7b1f44f50', '題長樂驛壁', '題长乐驛壁', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["三十驊騮一烘塵，來時不鎖杏園春。","楊花滿地如飛雪，應有偷游曲水人。"]', '["三十驊騮一烘塵，来时不鎖杏园春。","楊花满地如飞雪，應有偷游曲水人。"]', '诗', 'shi', '', NULL, '題長樂驛壁 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b54b321-35d0-489f-a2fe-a33a297418b5', '絕句', '絕句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["傳聞天子訪沈淪，萬里懷書西入秦。","早知不用無媒客，恨別江南楊柳春。"]', '["傳闻天子訪沈淪，万里懷书西入秦。","早知不用無媒客，恨別江南楊柳春。"]', '诗', 'shi', '', NULL, '絕句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7917717-cd6e-4a0e-af0b-7b97eb085ba7', '題取經詩', '題取經诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["晉宋齊梁唐代間，高僧求法離長安。","去人成百歸無十，後者安知前者難。","路遠碧天唯冷結，沙河遮日力疲殫。","後賢如未諳斯旨，往往將經容易看。"]', '["晉宋齊梁唐代间，高僧求法離长安。","去人成百归無十，後者安知前者难。","路远碧天唯冷結，沙河遮日力疲殫。","後賢如未諳斯旨，往往將經容易看。"]', '诗', 'shi', '', NULL, '題取經詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2d6131-6a10-4183-8d96-a7246587ba9f', '題水心寺水軒', '題水心寺水軒', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["分飛南渡春風晚，却返家林事業空。","無限離情似楊柳，萬條垂向楚江東。"]', '["分飞南渡春风晚，却返家林事業空。","無限離情似楊柳，万條垂向楚江东。"]', '诗', 'shi', '', NULL, '題水心寺水軒 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4100ce-db2b-47f4-a022-3c6e9266a993', '王昭君', '王昭君', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["猗蘭恩寵歇，昭陽幸御稀。","朝辭漢闕去，夕見胡塵飛。","寄信秦樓下，因書秋雁歸。"]', '["猗蘭恩寵歇，昭陽幸御稀。","朝辞漢闕去，夕见胡塵飞。","寄信秦楼下，因书秋雁归。"]', '诗', 'shi', '', NULL, '王昭君 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78aacbc1-0ecd-4e40-b8f1-682175855943', '王昭君', '王昭君', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一回望月一回悲，望月月移人不移。","何時得見漢朝使，爲妾傳書斬畫師。"]', '["一回望月一回悲，望月月移人不移。","何时得见漢朝使，爲妾傳书斬畫師。"]', '诗', 'shi', '', NULL, '王昭君 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364e745d-66d7-4904-87cc-2f7863144ef6', '粉牋題詩', '粉牋題诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["三月江南花滿枝，風輕簾幕燕爭飛。","游人休惜夜秉燭，楊柳陰濃春欲歸。"]', '["三月江南花满枝，风轻簾幕燕爭飞。","游人休惜夜秉燭，楊柳陰濃春欲归。"]', '诗', 'shi', '', NULL, '粉牋題詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e275b62a-85de-4aa2-a6c1-17e1d1c171a1', '詠美人騎馬', '詠美人騎马', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["駿馬嬌仍穩，春風灞岸晴。","促來金鐙短，扶上玉人輕。","帽束雲鬟亂，鞭籠翠袖明。"]', '["駿马嬌仍穩，春风灞岸晴。","促来金鐙短，扶上玉人轻。","帽束云鬟亂，鞭籠翠袖明。"]', '诗', 'shi', '', NULL, '詠美人騎馬 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29d0432-2c5c-4d1f-922a-b2cf2f7f7ac3', '六言詩', '六言诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["把酒留君聽琴，那堪歲暮離心。","霜葉無風自落，秋天不雨多陰。","人愁荒村路遠，馬怯寒溪水深。"]', '["把酒留君听琴，那堪歲暮離心。","霜葉無风自落，秋天不雨多陰。","人愁荒村路远，马怯寒溪水深。"]', '诗', 'shi', '', NULL, '六言詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c6be59-8b61-4de3-b770-dc1dce751378', '胡笳曲', '胡笳曲', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月明星稀霜滿野，氈車夜宿陰山下。","漢家自失李將軍，單于公然來牧馬。"]', '["月明星稀霜满野，氈车夜宿陰山下。","漢家自失李將軍，單于公然来牧马。"]', '诗', 'shi', '', NULL, '胡笳曲 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32fa2b8e-0571-4ef1-acc2-fde440203005', '桃源行送友人', '桃源行送友人', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["武陵川徑入幽遐，中有雞犬秦人家，家傍流水多桃花。","桃花兩邊種來久，流水一道何時有？","垂條落蕊暗春風，夾岸芳菲至山口。","歲歲年年能寂寥，林下青苔日爲厚。","時有仙鳥來銜花，曾無世人此攜手。","可憐不知若爲名，君往從之多所更。","古驛荒橋平路盡，崩湍怪石小谿行。","相見維舟登覽處，紅堤綠岸宛然成。","多君此去從仙隱，令人晚節悔營營。"]', '["武陵川徑入幽遐，中有雞犬秦人家，家傍流水多桃花。","桃花兩邊種来久，流水一道何时有？","垂條落蕊暗春风，夾岸芳菲至山口。","歲歲年年能寂寥，林下青苔日爲厚。","时有仙鸟来銜花，曾無世人此携手。","可怜不知若爲名，君往從之多所更。","古驛荒橋平路尽，崩湍怪石小谿行。","相见維舟登覽处，紅堤綠岸宛然成。","多君此去從仙隐，令人晚節悔營營。"]', '诗', 'shi', '', NULL, '桃源行送友人 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e31368c-8afb-4a94-93a2-6d0ceb248349', '唐衢墓', '唐衢墓', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["京洛先生三尺墳，陰風慘慘土和雲。","從來有感君皆哭，今日無君誰哭君。"]', '["京洛先生三尺墳，陰风慘慘土和云。","從来有感君皆哭，今日無君誰哭君。"]', '诗', 'shi', '', NULL, '唐衢墓 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc96a52-850b-46e6-b991-ca341cd0cce4', '宮詞', '宮词', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["花萼樓前春正濃，濛濛柳絮舞晴空。","金錢擲罷嬌無力，笑倚欄干屈曲中。"]', '["花萼楼前春正濃，濛濛柳絮舞晴空。","金錢擲罷嬌無力，笑倚欄干屈曲中。"]', '诗', 'shi', '', NULL, '宮詞 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daba8726-c799-41a4-a3d2-f00c17448fd0', '拋毬詩', '拋毬诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["侍宴黃昏未肯休，玉階夜色月如流。","朝來自詫承恩最，笑倩傍人認繡毬。"]', '["侍宴黄昏未肯休，玉階夜色月如流。","朝来自詫承恩最，笑倩傍人認繡毬。"]', '诗', 'shi', '', NULL, '拋毬詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('977be29a-c260-414e-82a1-3f669eafc0a1', '豔歌', '豔歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月裏嫦娥不畫眉，只將雲霧作羅衣。","不知夢逐青鸞去，猶把花枝蓋面歸。"]', '["月裏嫦娥不畫眉，只將云霧作羅衣。","不知梦逐青鸾去，猶把花枝蓋面归。"]', '诗', 'shi', '', NULL, '豔歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41fa2c63-f207-4fdd-9fbf-742484a5b842', '楊柳枝', '楊柳枝', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["萬里長江一帶開，岸邊楊柳幾千栽。","錦帆未落西風起，惆悵龍舟去不迴。"]', '["万里长江一带开，岸邊楊柳幾千栽。","錦帆未落西风起，惆悵龙舟去不迴。"]', '诗', 'shi', '', NULL, '楊柳枝 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49241ff1-8ea2-4878-a549-921812d5a53b', '河中石刻', '河中石刻', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雨滴空堦曉，無心換夕香。","井梧花落盡，一半在銀床。"]', '["雨滴空堦晓，無心換夕香。","井梧花落尽，一半在銀床。"]', '诗', 'shi', '', NULL, '河中石刻 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a355887-3e7d-4cdb-a6ac-bc2fb243d06b', '古硯', '古硯', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["癖性愛古物，終歲求不得。","昨朝得古硯，蘭河灘之側。","波濤所擊觸，背面生隟隙。","質狀朴且醜，令人作不得。"]', '["癖性愛古物，終歲求不得。","昨朝得古硯，蘭河灘之側。","波濤所擊觸，背面生隟隙。","質狀朴且醜，令人作不得。"]', '诗', 'shi', '', NULL, '古硯 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('746fb9e8-8d20-4272-ba30-1584afaa9671', '絕句', '絕句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["釣罷孤舟繫葦梢，酒開新甕鮓開包。","自從江浙爲漁父，二十餘年手不扠。"]', '["釣罷孤舟繫葦梢，酒开新甕鮓开包。","自從江浙爲漁父，二十餘年手不扠。"]', '诗', 'shi', '', NULL, '絕句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09bb4165-7761-43b4-98c0-7c79f1ad24ec', '題童氏畫', '題童氏畫', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["林下材華雖可尚，筆端人物更清妍。","如何不出深閨裏，能以丹青寫外邊。"]', '["林下材华雖可尚，笔端人物更清妍。","如何不出深閨裏，能以丹青寫外邊。"]', '诗', 'shi', '', NULL, '題童氏畫 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e824b012-fe2c-45ae-a412-97d471b18ced', '失題', '失題', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["春朝散微雨，庭樹開芸綠。","上有懷春鳥，間關斷復續。","謂言□野中，定是珠城曲。","我自牽時幸，以慚羈旅束。","爾下鳴幽林，來此將何欲。"]', '["春朝散微雨，庭樹开芸綠。","上有懷春鸟，间关斷复續。","謂言□野中，定是珠城曲。","我自牽时幸，以慚羈旅束。","爾下鳴幽林，来此將何欲。"]', '诗', 'shi', '', NULL, '失題 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658cf5bd-a4cc-44b5-8240-3507bc7a500c', '姜宣彈小胡笳引歌', '姜宣彈小胡笳引歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雷氏金徽琴，王君寶重輕千金。","三峽流中將得來，明窗拂席幽匣開。","朱弦宛轉盤鳳足，驟擊數聲風雨迴。","哀笳慢指董家本，姜宣得之妙思忖。","汎徽胡雁咽蕭蕭，繞指轆轤圓衮衮。","吞恨含情乍輕激，故國關山心歷歷。","潺湲疑是舞鸊鵜，砉騞如聞發鳴鏑。","流宮變徵漸幽咽，別鶴欲飛猨欲絕。","秋霜滿樹葉辭風，寒雛墜地烏啼血。","哀弦已罷春恨長，恨長何如懷我鄉。","我鄉安在長城窟，聞君膚奏心飄忽。","何時窄袖短貂裘，臙脂山下彎明月。"]', '["雷氏金徽琴，王君寶重轻千金。","三峽流中將得来，明窗拂席幽匣开。","朱弦宛轉盤鳳足，驟擊數声风雨迴。","哀笳慢指董家本，姜宣得之妙思忖。","汎徽胡雁咽蕭蕭，繞指轆轤圓衮衮。","吞恨含情乍轻激，故国关山心歷歷。","潺湲疑是舞鸊鵜，砉騞如闻發鳴鏑。","流宮变徵漸幽咽，別鹤欲飞猨欲絕。","秋霜满樹葉辞风，寒雛墜地烏啼血。","哀弦已罷春恨长，恨长何如懷我乡。","我乡安在长城窟，闻君膚奏心飄忽。","何时窄袖短貂裘，臙脂山下彎明月。"]', '诗', 'shi', '', NULL, '姜宣彈小胡笳引歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df559fd7-2153-42e2-ac50-e33f7bd06020', '羅浮山', '羅浮山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["四百餘峯海上排，根連蓬島蔭天台。","百靈若爲移中土，嵩華都爲一小堆。"]', '["四百餘峯海上排，根連蓬島蔭天台。","百靈若爲移中土，嵩华都爲一小堆。"]', '诗', 'shi', '', NULL, '羅浮山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5a817b-5c58-4aa7-943f-dcdea3d7f64d', '湯周山', '湯周山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["湯周二大仙，廬此得昇天。","風俗因興廟，春秋不記年。","錦雲張紫蓋，琴溜瀉鳴泉。","丹竈猶存鼎，仙花發故園。"]', '["湯周二大仙，廬此得昇天。","风俗因兴廟，春秋不記年。","錦云張紫蓋，琴溜瀉鳴泉。","丹竈猶存鼎，仙花發故园。"]', '诗', 'shi', '', NULL, '湯周山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('302144a7-ed89-4073-80e0-dbb916c83a0a', '永州舜廟詩', '永州舜廟诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["游湘有餘怨，豈是聖人心。","行路猿啼古，祠宮夢草深。","素風傳舊俗，異跡閉荒林。","巡狩去不返，煙雲愁至今。","九嶷天一半，山盡海沈沈。"]', '["游湘有餘怨，豈是聖人心。","行路猿啼古，祠宮梦草深。","素风傳旧俗，異跡閉荒林。","巡狩去不返，煙云愁至今。","九嶷天一半，山尽海沈沈。"]', '诗', 'shi', '', NULL, '永州舜廟詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3214588-84a1-4046-b426-a233efe2ddf8', '絕句', '絕句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["綠楊陰轉畫橋斜，舟有笙歌岸有花。","盡日會稽山色裏，蓬萊清淺水仙家。"]', '["綠楊陰轉畫橋斜，舟有笙歌岸有花。","尽日會稽山色裏，蓬萊清淺水仙家。"]', '诗', 'shi', '', NULL, '絕句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cebd753a-47a0-480f-b9d4-5ddb39723435', '三學山盤陀石上刻詩', '三学山盤陀石上刻诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["拔地山巒秀，排空殿閣斜。","雲供數州雨，樹獻九天花。","夜月摩峰頂，秋鐘徹海涯。","長松拂星漢，一一是仙槎。"]', '["拔地山巒秀，排空殿閣斜。","云供數州雨，樹獻九天花。","夜月摩峰頂，秋鐘徹海涯。","长松拂星漢，一一是仙槎。"]', '诗', 'shi', '', NULL, '三學山盤陀石上刻詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb12da5f-2601-4a4a-9ef3-5548d37a5b71', '合水縣玉泉石崖刻', '合水縣玉泉石崖刻', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山脉逗飛泉，泓澄傍巖石。","亂垂寒玉篠，碎灑珍珠滴。","澄波涵萬象，明鏡瀉天色。","有時乘月來，賞詠還自適。"]', '["山脉逗飞泉，泓澄傍巖石。","亂垂寒玉篠，碎灑珍珠滴。","澄波涵万象，明镜瀉天色。","有时乘月来，賞詠還自適。"]', '诗', 'shi', '', NULL, '合水縣玉泉石崖刻 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21797f1d-5ae3-4c66-98cc-99680a9d88a1', '紀遊東觀山', '紀游东观山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["瑰奇恣搜討，貝闕青瑤房。","才隘疑永巷，俄敞如華堂。","玉梁窈浮溪，瓊戶正當窗。","仙佛肖彷彿，鐘鼓鍧擊撞。","贔贔左顧龜，狺狺欲吠[尨]。","丹竈儼亡恙，芝田靄生香。","搏噬千怪聚，絢爛五色光。","更無一塵涴，但覺六月涼。","玲瓏穿屢折，詰曲通三湘。","神鬼若剜刻，乾坤真混茫。","入如深夜暗，出喜皦日光。","隔世驚瞬息，異境難揣量。"]', '["瑰奇恣搜討，貝闕青瑤房。","才隘疑永巷，俄敞如华堂。","玉梁窈浮溪，瓊戶正當窗。","仙佛肖彷彿，鐘鼓鍧擊撞。","贔贔左顧龟，狺狺欲吠[尨]。","丹竈儼亡恙，芝田靄生香。","搏噬千怪聚，絢爛五色光。","更無一塵涴，但覺六月涼。","玲瓏穿屢折，詰曲通三湘。","神鬼若剜刻，乾坤真混茫。","入如深夜暗，出喜皦日光。","隔世驚瞬息，異境难揣量。"]', '诗', 'shi', '', NULL, '紀遊東觀山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b337d13d-301b-42a5-bd39-3888a294def3', '題焚經臺', '題焚經台', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["門徑蕭蕭長綠苔，一回登此一徘徊。","青牛謾說函關去，白馬親從印土來。","確實是非憑烈焰，要分真僞築高臺。","春風也解嫌狼籍，吹盡當年道教灰。"]', '["门徑蕭蕭长綠苔，一回登此一徘徊。","青牛謾说函关去，白马親從印土来。","確實是非憑烈焰，要分真僞築高台。","春风也解嫌狼籍，吹尽當年道教灰。"]', '诗', 'shi', '', NULL, '題焚經臺 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb4f06f-75b2-4d42-8ad4-e3cad515de5f', '日暮山河清', '日暮山河清', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天高爽氣晶，馳景忽西傾。","山列千重靜，河流一帶明。","想同金鏡澈，寧讓玉壺清。","纖翳無由出，浮埃不復生。","榮紆分漢苑，表裏見秦城。","逸興終難繫，抽毫仰此情。"]', '["天高爽氣晶，驰景忽西傾。","山列千重静，河流一带明。","想同金镜澈，寧讓玉壺清。","纖翳無由出，浮埃不复生。","榮紆分漢苑，表裏见秦城。","逸兴終难繫，抽毫仰此情。"]', '诗', 'shi', '', NULL, '日暮山河清 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148ea71b-3f6a-4f6b-a0a8-ea84620db56f', '秋日懸清光', '秋日懸清光', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["寥廓涼天靜，晶明白日秋。","圓光含萬象，碎影人閑流。","迥與青冥合，遙同江甸浮。","晝陰殊衆木，斜影下危樓。","宋玉登高怨，張衡望遠愁。","餘輝如可託，雲路豈悠悠。"]', '["寥廓涼天静，晶明白日秋。","圓光含万象，碎影人闲流。","迥與青冥合，遙同江甸浮。","晝陰殊衆木，斜影下危楼。","宋玉登高怨，張衡望远愁。","餘輝如可託，云路豈悠悠。"]', '诗', 'shi', '', NULL, '秋日懸清光 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17052128-5f54-48c9-b74b-24a16433faf2', '落日山照曜', '落日山照曜', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["裴回空山下，晼晚殘陽落。","圓影過峰巒，半規入林薄。","餘光澈羣岫，亂彩分重壑。","石鏡共澄明，巖光同照灼。","棲禽去杳杳，夕煙生漠漠。","此境誰復知，獨懷謝康樂。"]', '["裴回空山下，晼晚殘陽落。","圓影過峰巒，半規入林薄。","餘光澈羣岫，亂彩分重壑。","石镜共澄明，巖光同照灼。","棲禽去杳杳，夕煙生漠漠。","此境誰复知，独懷謝康乐。"]', '诗', 'shi', '', NULL, '落日山照曜 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f72fcb6-286c-4b53-93e1-37c95d4b801d', '月映清淮流', '月映清淮流', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["淮月秋偏靜，含虛夜轉明。","桂花窺鏡發，蟾影映波生。","澹灩輪初上，裴回魄正盈。","遙塘分草樹，近浦寫山城。","桐柏流光逐，蠙珠濯景清。","孤舟方利涉，更喜照前程。"]', '["淮月秋偏静，含虛夜轉明。","桂花窺镜發，蟾影映波生。","澹灩輪初上，裴回魄正盈。","遙塘分草樹，近浦寫山城。","桐柏流光逐，蠙珠濯景清。","孤舟方利涉，更喜照前程。"]', '诗', 'shi', '', NULL, '月映清淮流 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d42f62-a639-4631-8629-03706b1937c8', '壽星見', '壽星见', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玄象今何應，時和政亦平。","祥爲一人壽，色映九霄明。","皎潔垂銀漢，光芒近斗城。","合規同月滿，表瑞得天清。","甘露盈條降，祥煙向日生。","無如此嘉祉，率土荷秋成。"]', '["玄象今何應，时和政亦平。","祥爲一人壽，色映九霄明。","皎潔垂銀漢，光芒近斗城。","合規同月满，表瑞得天清。","甘露盈條降，祥煙向日生。","無如此嘉祉，率土荷秋成。"]', '诗', 'shi', '', NULL, '壽星見 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a98f776-9a84-4f37-8262-fb78e4ef0a48', '華山慶雲見', '华山慶云见', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["聖主祠名岳，高風發慶雲。","金柯初繚繞，玉葉漸氛氳。","氣色含珠日，光明吐翠雰。","依稀來鶴態，髣髴列仙羣。","萬樹流光影，千潭寫錦文。","蒼生忻有望，祥瑞在吾君。"]', '["聖主祠名岳，高风發慶云。","金柯初繚繞，玉葉漸氛氳。","氣色含珠日，光明吐翠雰。","依稀来鹤態，髣髴列仙羣。","万樹流光影，千潭寫錦文。","蒼生忻有望，祥瑞在吾君。"]', '诗', 'shi', '', NULL, '華山慶雲見 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8580f60-6a8c-4cfa-8ab4-46e6bf57e17e', '清風戒寒', '清风戒寒', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蕭颯清風至，悠然發思端。","入林翻別葉，繞樹敗紅蘭。","曉拂輕霜度，宵分遠籟攢。","稍依簾隙靜，徧覺坐隅寒。","乍逐驚蓬振，偏催急漏殘。","遙知洞庭水，此夕起波瀾。"]', '["蕭颯清风至，悠然發思端。","入林翻別葉，繞樹敗紅蘭。","晓拂轻霜度，宵分远籟攢。","稍依簾隙静，徧覺坐隅寒。","乍逐驚蓬振，偏催急漏殘。","遙知洞庭水，此夕起波瀾。"]', '诗', 'shi', '', NULL, '清風戒寒 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9a7402-69f3-4ddb-b1da-e410e328d08e', '空水共澄鮮', '空水共澄鲜', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["悠然四望通，渺渺水無窮。","海鶴飛天際，煙林出鏡中。","雲消澄徧碧，霞起澹微紅。","落日浮光滿，遙山翠色同。","樵聲喧竹嶼，櫂唱入蓮藂。","遠客舟中興，煩襟暫一空。"]', '["悠然四望通，渺渺水無窮。","海鹤飞天際，煙林出镜中。","云消澄徧碧，霞起澹微紅。","落日浮光满，遙山翠色同。","樵声喧竹嶼，櫂唱入蓮藂。","远客舟中兴，煩襟暫一空。"]', '诗', 'shi', '', NULL, '空水共澄鮮 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9909e0d-fea0-4dd5-97b5-22a3b88d8b81', '寒流聚細文', '寒流聚細文', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["曉野方閑眺，橫溪賞亂流。","寒文趨浦急，圓折逐煙浮。","不謂飄疎雨，非關浴遠鷗。","觀魚鱗共細，間石影疑稠。","獵獵風泠夕，潺潺瀨響秋。","仙槎如共泛，天漢適淹留。"]', '["晓野方闲眺，橫溪賞亂流。","寒文趨浦急，圓折逐煙浮。","不謂飄疎雨，非关浴远鷗。","观鱼鱗共細，间石影疑稠。","獵獵风泠夕，潺潺瀨响秋。","仙槎如共泛，天漢適淹留。"]', '诗', 'shi', '', NULL, '寒流聚細文 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f93ea94-02e3-4c07-bf9f-2fd98ca4d9e3', '長安早春', '长安早春', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["杳靄三春色，先從帝里芳。","折楊猶恨短，測景已忻長。","鶯和紅樓樂，花連紫禁香。","躍魚驚太液，佳氣接溫湯。","風送飛珂響，塵蒙翠輦光。","熙熙晴煦遠，徒欲奉堯觴。"]', '["杳靄三春色，先從帝里芳。","折楊猶恨短，測景已忻长。","鶯和紅楼乐，花連紫禁香。","躍鱼驚太液，佳氣接溫湯。","风送飞珂响，塵蒙翠輦光。","熙熙晴煦远，徒欲奉堯觴。"]', '诗', 'shi', '', NULL, '長安早春 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2148c3cd-4896-4713-8b27-57888307ec05', '嘉和合頴', '嘉和合頴', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天祚皇王德，神呈瑞穀嘉。","感時苗特秀，證道葉方華。","氣轉騰佳色，雲披映早霞。","薰風浮合頴，湛露淨祥花。","六穗垂兼倒，孤莖嫋復斜。","影同唐叔獻，稱慶比周家。"]', '["天祚皇王德，神呈瑞穀嘉。","感时苗特秀，證道葉方华。","氣轉腾佳色，云披映早霞。","薰风浮合頴，湛露淨祥花。","六穗垂兼倒，孤莖嫋复斜。","影同唐叔獻，稱慶比周家。"]', '诗', 'shi', '', NULL, '嘉和合頴 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e91d71f2-ecc1-4784-ae49-768d25323fc4', '膏澤多豐年', '膏澤多豐年', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["帝德方多澤，莓莓井徑同。","八方甘雨布，四遠報年豐。","厫慶千廂在，山流萬壑通。","候時勤稼穡，擊壤樂農功。","畎畝人無惰，田廬歲不空。","何須憂伏臘，千載賀堯風。"]', '["帝德方多澤，莓莓井徑同。","八方甘雨布，四远報年豐。","厫慶千廂在，山流万壑通。","候时勤稼穡，擊壤乐農功。","畎畝人無惰，田廬歲不空。","何須憂伏臘，千載賀堯风。"]', '诗', 'shi', '', NULL, '膏澤多豐年 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd558c28-8f0e-42f7-b9c8-bce4f32ec8e1', '玉壺冰', '玉壺冰', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玄律陰風勁，堅冰在玉壺。","暗中花更出，曉後色全無。","涸沍誰能伴，淒清詎可渝。","任圓空似璧，照物不成珠。","素質情方契，孤明道豈殊。","幽人若相比，還得詠生芻。"]', '["玄律陰风勁，堅冰在玉壺。","暗中花更出，晓後色全無。","涸沍誰能伴，淒清詎可渝。","任圓空似璧，照物不成珠。","素質情方契，孤明道豈殊。","幽人若相比，還得詠生芻。"]', '诗', 'shi', '', NULL, '玉壺冰 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89d829fd-4c57-4567-8945-c0404741bc20', '望禁苑祥光', '望禁苑祥光', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["佳氣生天苑，蔥蘢幾效祥。","樹遙三殿際，日映九城傍。","山霧寧同色，卿雲未可彰。","眺汾疑鼎氣，臨渭想榮光。","當並舂陵發，應開聖曆長。","微臣時一望，短羽欲飛翔。"]', '["佳氣生天苑，蔥蘢幾效祥。","樹遙三殿際，日映九城傍。","山霧寧同色，卿云未可彰。","眺汾疑鼎氣，臨渭想榮光。","當並舂陵發，應开聖曆长。","微臣时一望，短羽欲飞翔。"]', '诗', 'shi', '', NULL, '望禁苑祥光 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13de6ae-a369-4b06-b7b0-d3a7249217b6', '晨光動翠華', '晨光动翠华', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["早朝開紫殿，佳氣逐清晨。","北闕華旌在，東方曙景新。","影連香霧合，光媚慶雲頻。","鳥羽飄初定，龍文照轉真。","直疑冠佩入，長愛冕旒親。","搖動祥雲裏，朝朝映侍臣。"]', '["早朝开紫殿，佳氣逐清晨。","北闕华旌在，东方曙景新。","影連香霧合，光媚慶云頻。","鸟羽飄初定，龙文照轉真。","直疑冠佩入，长愛冕旒親。","搖动祥云裏，朝朝映侍臣。"]', '诗', 'shi', '', NULL, '晨光動翠華 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4dcc10-0724-4036-918a-87e95751042b', '觀南郊回仗', '观南郊回仗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["傳警千門寂，南郊綵仗迴。","但驚龍再見，誰識日雙開。","德澤施雲雨，恩光變燼灰。","閱兵貔武振，聽樂鳳凰來。","候刻移宸輦，尊時集觀臺。","多慙遠臣賤，不得禮容陪。"]', '["傳警千门寂，南郊綵仗迴。","但驚龙再见，誰識日雙开。","德澤施云雨，恩光变燼灰。","閱兵貔武振，听乐鳳凰来。","候刻移宸輦，尊时集观台。","多慙远臣賤，不得禮容陪。"]', '诗', 'shi', '', NULL, '觀南郊回仗 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa5786ec-bf1b-49c3-8ac1-35babbd3a710', '謁見日將至雙闕', '謁见日將至雙闕', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["曉色臨雙闕，微臣禮位陪。","遠驚龍鳳覩，誰識冕旒開。","藹藹千年盛，顒顒萬國來。","天文標日月，時令布雲雷。","迥出黃金殿，全分白玉臺。","雕蟲意何取，瞻戀不知迴。"]', '["晓色臨雙闕，微臣禮位陪。","远驚龙鳳覩，誰識冕旒开。","藹藹千年盛，顒顒万国来。","天文標日月，时令布云雷。","迥出黄金殿，全分白玉台。","雕蟲意何取，瞻戀不知迴。"]', '诗', 'shi', '', NULL, '謁見日將至雙闕 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804c508c-5ffe-4513-a6b0-870404b04f52', '尚書郎上直聞春漏', '尚书郎上直闻春漏', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["地即尚書省，人惟鴛鷺行。","審時傳玉漏，直夜遞星郎。","歷歷聞仙暑，泠泠出建章。","自空來斷續，隨月散淒鏘。","物靜知聲遠，寒輕覺夜長。","聽餘殘月落，曙色滿東方。"]', '["地即尚书省，人惟鴛鷺行。","審时傳玉漏，直夜遞星郎。","歷歷闻仙暑，泠泠出建章。","自空来斷續，隨月散淒鏘。","物静知声远，寒轻覺夜长。","听餘殘月落，曙色满东方。"]', '诗', 'shi', '', NULL, '尚書郎上直聞春漏 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b366a21d-8b6c-46b6-becf-dc903861948b', '華清宮望幸', '华清宮望幸', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["驪岫接新豐，岧嶤駕碧空。","鑿山開祕殿，隱霧蔽仙宮。","絳闕猶棲鳳，雕梁尚帶虹。","溫泉曾浴日，華館舊迎風。","肅穆瞻雲輦，深沈閉綺櫳。","東郊望幸處，瑞氣靄濛濛。"]', '["驪岫接新豐，岧嶤駕碧空。","鑿山开祕殿，隐霧蔽仙宮。","絳闕猶棲鳳，雕梁尚带虹。","溫泉曾浴日，华館旧迎风。","肅穆瞻云輦，深沈閉綺櫳。","东郊望幸处，瑞氣靄濛濛。"]', '诗', 'shi', '', NULL, '華清宮望幸 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae730d3a-61cd-43d2-9b6d-cc9302dda7fb', '御題國子監', '御題国子監', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["宸翰符玄造，榮題國子門。","筆鋒迴日月，字勢動乾坤。","簷下雲光繞，梁間鵲影翻。","張英聖莫擬，索靖妙難言。","爲著盤龍迹，能彰舞鳳蹲。","更隨垂露像，常以沐皇恩。"]', '["宸翰符玄造，榮題国子门。","笔鋒迴日月，字勢动乾坤。","簷下云光繞，梁间鵲影翻。","張英聖莫擬，索靖妙难言。","爲著盤龙迹，能彰舞鳳蹲。","更隨垂露像，常以沐皇恩。"]', '诗', 'shi', '', NULL, '御題國子監 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d37a10-351a-4863-afe1-91dbd5a5eb4f', '郊壇聽雅樂', '郊壇听雅乐', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["泰壇恭祀事，彩仗下寒坰。","展禮陳嘉樂，齋心動衆靈。","韻長飄更遠，曲度靜宜聽。","泛響何清越，隨風散杳冥。","徹懸和氣聚，旋退曉山青。","本自鈞天降，還疑列洞庭。"]', '["泰壇恭祀事，彩仗下寒坰。","展禮陳嘉乐，斋心动衆靈。","韻长飄更远，曲度静宜听。","泛响何清越，隨风散杳冥。","徹懸和氣聚，旋退晓山青。","本自鈞天降，還疑列洞庭。"]', '诗', 'shi', '', NULL, '郊壇聽雅樂 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a14fed-7272-4132-abbc-6f9ca1470477', '冊上公太常奏雅樂', '冊上公太常奏雅乐', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["司樂陳金石，逶迤引上公。","奏音人語絕，清韻佩聲通。","應律煙雲改，來儀鳥獸同。","得賢因舉頌，修禮便觀風。","聖壽三稱內，天歡九奏中。","寂寥高曲盡，猶自滿宸聰。"]', '["司乐陳金石，逶迤引上公。","奏音人語絕，清韻佩声通。","應律煙云改，来儀鸟獸同。","得賢因舉頌，修禮便观风。","聖壽三稱內，天歡九奏中。","寂寥高曲尽，猶自满宸聰。"]', '诗', 'shi', '', NULL, '冊上公太常奏雅樂 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a05802fa-082b-48af-a717-8f12efc75832', '聽霜鐘', '听霜鐘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["渺渺飛霜夜，寥寥遠岫鐘。","出雲疑斷續，入戶乍舂容。","度枕頻驚夢，隨風幾韻松。","悠揚來不已，杳靄去何從。","髣髴煙嵐隔，依俙巖嶠重。","此時聊一聽，餘響繞千峰。"]', '["渺渺飞霜夜，寥寥远岫鐘。","出云疑斷續，入戶乍舂容。","度枕頻驚梦，隨风幾韻松。","悠揚来不已，杳靄去何從。","髣髴煙嵐隔，依俙巖嶠重。","此时聊一听，餘响繞千峰。"]', '诗', 'shi', '', NULL, '聽霜鐘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994d44c0-6514-4394-976d-a8503ed82085', '聽霜鐘', '听霜鐘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["寥亮來豐嶺，分明辨古鐘。","應霜如自擊，中節每相從。","靜聽非閑扣，潛應蘊聖蹤。","風間時斷續，雲外更舂容。","虛警和清籟，雄鳴隔亂峰。","因之論知己，感激更難逢。"]', '["寥亮来豐嶺，分明辨古鐘。","應霜如自擊，中節每相從。","静听非闲扣，潛應蘊聖蹤。","风间时斷續，云外更舂容。","虛警和清籟，雄鳴隔亂峰。","因之論知己，感激更难逢。"]', '诗', 'shi', '', NULL, '聽霜鐘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ba8cc0-caca-4935-b8dc-c7081ae6fbff', '笙磬同音', '笙磬同音', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["笙磬聞何處，淒鏘宛在東。","激揚音自徹，高下曲宜同。","歷歷俱盈耳，泠泠遞散空。","獸因繁奏舞，人感至和通。","詎間洪纖韻，能齊搏拊功。","四懸今盡美，一聽辨移風。"]', '["笙磬闻何处，淒鏘宛在东。","激揚音自徹，高下曲宜同。","歷歷俱盈耳，泠泠遞散空。","獸因繁奏舞，人感至和通。","詎间洪纖韻，能齊搏拊功。","四懸今尽美，一听辨移风。"]', '诗', 'shi', '', NULL, '笙磬同音 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17733bea-3744-4068-a752-d862d94df3cf', '玉巵無當', '玉巵無當', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["共惜連城寶，翻爲無當巵。","詎慙君子貴，深訝拙工隳。","泛蟻功全少，如虹色不移。","可憐珍礫石，何計辨糟醨。","江海誠難滿，盤筵莫妄施。","縱乖斟酌意，猶得奉光儀。"]', '["共惜連城寶，翻爲無當巵。","詎慙君子貴，深訝拙工隳。","泛蟻功全少，如虹色不移。","可怜珍礫石，何計辨糟醨。","江海誠难满，盤筵莫妄施。","縱乖斟酌意，猶得奉光儀。"]', '诗', 'shi', '', NULL, '玉巵無當 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02dd0c30-49c0-43ee-a4a4-af61216a9f61', '府試古鏡', '府試古镜', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舊是秦時鏡，今來古匣中。","龍盤初挂月，鳳舞欲生風。","石黛曾留殿，朱光適在宮。","應祥知道泰，監物覺神通。","肝膽誠難隱，妍媸信易窮。","幸居君子室，長願免塵蒙。"]', '["旧是秦时镜，今来古匣中。","龙盤初挂月，鳳舞欲生风。","石黛曾留殿，朱光適在宮。","應祥知道泰，監物覺神通。","肝膽誠难隐，妍媸信易窮。","幸居君子室，长願免塵蒙。"]', '诗', 'shi', '', NULL, '府試古鏡 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c225bfc0-186c-425a-bce4-c21edb0cfb5c', '焚裘', '焚裘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今主臨前殿，懲奢爇異裘。","忽看陽焰發，如覩吉光流。","麗彩辭宸扆，餘香在御樓。","火隨餘燼滅，氣逐遠煙浮。","素朴回風變，凋華逐志休。","永垂恭儉德，千古揖皇猷。"]', '["今主臨前殿，懲奢爇異裘。","忽看陽焰發，如覩吉光流。","丽彩辞宸扆，餘香在御楼。","火隨餘燼滅，氣逐远煙浮。","素朴回风变，凋华逐志休。","永垂恭儉德，千古揖皇猷。"]', '诗', 'shi', '', NULL, '焚裘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102bb61e-3d81-4f54-b884-496c116761af', '送薛大夫和蕃', '送薛大夫和蕃', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["戎王歸漢命，魏絳諭皇恩。","旌斾辭雙闕，風沙上五原。","往途遵塞道，出祖耀都門。","策令天文盛，宣威使者尊。","澄波望四海，入貢佇諸蕃。","秋杪迎迴騎，無勞枉夢魂。"]', '["戎王归漢命，魏絳諭皇恩。","旌斾辞雙闕，风沙上五原。","往途遵塞道，出祖耀都门。","策令天文盛，宣威使者尊。","澄波望四海，入貢佇諸蕃。","秋杪迎迴騎，無勞枉梦魂。"]', '诗', 'shi', '', NULL, '送薛大夫和蕃 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5727a45-db62-47b7-9c3b-ad1059a4eb7c', '觀劒南獻捷', '观劒南獻捷', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["遐圻新破虜，名將舊登壇。","戎馘西南至，氈裘長幼觀。","邊疆氛已息，矛戟血猶殘。","紫陌歡聲動，丹墀喜氣盤。","唐虞方德易，衛霍比功難。","共覩俘囚入，賡歌萬國安。"]', '["遐圻新破虜，名將旧登壇。","戎馘西南至，氈裘长幼观。","邊疆氛已息，矛戟血猶殘。","紫陌歡声动，丹墀喜氣盤。","唐虞方德易，衛霍比功难。","共覩俘囚入，賡歌万国安。"]', '诗', 'shi', '', NULL, '觀劒南獻捷 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0083e1ea-b686-46b1-9822-402df77cc81c', '雲母屏風隔坐', '云母屏风隔坐', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["彩障成雲母，丹墀隔上公。","才彰二紀盛，榮播一朝同。","近玉初齊白，臨花乍散紅。","凝姿分縹緲，轉佩辨𤫩瓏。","意愜恩偏厚，名新寵更崇。","誰知歷千古，猶自仰清風。"]', '["彩障成云母，丹墀隔上公。","才彰二紀盛，榮播一朝同。","近玉初齊白，臨花乍散紅。","凝姿分縹緲，轉佩辨𤫩瓏。","意愜恩偏厚，名新寵更崇。","誰知歷千古，猶自仰清风。"]', '诗', 'shi', '', NULL, '雲母屏風隔坐 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae7fb822-b8b3-4444-a032-d711433237c3', '白受采', '白受采', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["皛皛金方色，遷移妙不窮。","輕衣塵跡化，淨壁繢文通。","沙變藍溪漬，冰渝墨沼空。","似甘言受和，由禮學資忠。","皎潔形無定，玄黃用莫同。","素心如可教，願染古人風。"]', '["皛皛金方色，遷移妙不窮。","轻衣塵跡化，淨壁繢文通。","沙变藍溪漬，冰渝墨沼空。","似甘言受和，由禮学資忠。","皎潔形無定，玄黄用莫同。","素心如可教，願染古人风。"]', '诗', 'shi', '', NULL, '白受采 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e0e39c-f02a-4f15-8b2e-bf382e8c4bac', '人不易知', '人不易知', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["權衡諒匪易，愚智信難移。","九德皆殊進，三端豈易施。","同稱崑岫寶，共握桂林枝。","鄭鼠今奚別，齊竽或濫吹。","瑤臺有光鑑，屢照不應疲。","片善當無掩，先鳴貴在斯。","龍門峻且極，驥足庶來馳。","太息李元禮，期君幸一知。"]', '["權衡諒匪易，愚智信难移。","九德皆殊進，三端豈易施。","同稱崑岫寶，共握桂林枝。","鄭鼠今奚別，齊竽或濫吹。","瑤台有光鑑，屢照不應疲。","片善當無掩，先鳴貴在斯。","龙门峻且極，驥足庶来驰。","太息李元禮，期君幸一知。"]', '诗', 'shi', '', NULL, '人不易知 無名氏 shi');
